import React, { useState, useEffect } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { MapContainer, Marker, Popup, useMapEvents, TileLayer } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { FaStore, FaUserPlus } from 'react-icons/fa';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  Alert,
} from '../components/ui';

function LocationMap({ setLocation }) {
  const map = useMapEvents({
    click(e) {
      const { lat, lng } = e.latlng;
      setLocation({ lat, lng });
      map.flyTo(e.latlng, map.getZoom());
    },
  });

  return null;
}

const RegisterShopper = () => {
  const [formData, setFormData] = useState({
    full_name: '',
    email: '',
    password: '',
  });

  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('error');
  const [location, setLocation] = useState({ lat: '', lng: '' });
  const [currentLocation, setCurrentLocation] = useState({ lat: 9.145, lng: 40.4897 }); // Default location (Ethiopia)

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setCurrentLocation({ lat: latitude, lng: longitude });
        },
        (error) => {
          console.error(error);
        }
      );
    }
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const payload = {
      full_name: formData.full_name,
      email: formData.email,
      password: formData.password,
      role: 'seller',
      seller_level: 'reseller',
      location_lat: location.lat || currentLocation.lat,
      location_lng: location.lng || currentLocation.lng,
    };

    try {
      const response = await apiClient.post('/api/user/register', payload);
      setMessage(response.data.message || 'Seller registered successfully.');
      setMessageType('success');
      setFormData({ full_name: '', email: '', password: '' });
      setLocation({ lat: '', lng: '' });
    } catch (error) {
      console.error('Error:', error);
      setMessage('An error occurred. Please try again.');
      setMessageType('error');
    }
  };

  return (
    <AdminLayout>
      <div className="max-w-2xl mx-auto">
        <PageHeader
          icon={<FaStore />}
          title="Register Seller"
          subtitle="Add a new seller account and set their location on the map"
        />

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-5">
            <Input
              label="Full Name"
              id="full_name"
              name="full_name"
              type="text"
              value={formData.full_name}
              onChange={handleInputChange}
              placeholder="Enter seller's full name"
              required
            />

            <Input
              label="Email"
              id="email"
              name="email"
              type="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Enter seller's email address"
              required
            />

            {/* Location picker using the map */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Location (Pick from Map)
                <span className="text-red-500 ml-1">*</span>
              </label>
              <Card padding="none" className="overflow-hidden border border-gray-200 h-[300px] sm:h-[400px]">
                <MapContainer
                  center={[currentLocation.lat, currentLocation.lng]}
                  zoom={13}
                  style={{ height: '100%', width: '100%' }}
                >
                  <TileLayer
                    url={`https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png`}
                  />
                  {/* Google Maps tile layer */}
                  <TileLayer
                    url={`https://mt1.google.com/vt/lyrs=m&x={x}&y={y}&z={z}&key=YOUR_GOOGLE_MAPS_API_KEY`}
                  />
                  <LocationMap setLocation={setLocation} />
                  {/* Custom marker icon */}
                  {location.lat && location.lng ? (
                    <Marker position={[location.lat, location.lng]} icon={new L.Icon({ iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png ' })}>
                      <Popup>
                        <span>Selected Location</span>
                      </Popup>
                    </Marker>
                  ) : (
                    <Marker position={[currentLocation.lat, currentLocation.lng]} icon={new L.Icon({ iconUrl: '/pin.svg' })}>
                      <Popup>
                        <span>Your Current Location</span>
                      </Popup>
                    </Marker>
                  )}
                </MapContainer>
              </Card>
              {location.lat && location.lng && (
                <div className="mt-2 text-sm text-gray-600">
                  <p>Latitude: {location.lat}</p>
                  <p>Longitude: {location.lng}</p>
                </div>
              )}
            </div>

            <Input
              label="Password"
              id="password"
              name="password"
              type="password"
              value={formData.password}
              onChange={handleInputChange}
              placeholder="Enter a secure password"
              required
            />

            <Button
              type="submit"
              variant="primary"
              size="lg"
              fullWidth
              icon={<FaUserPlus />}
            >
              Register Seller
            </Button>
          </form>

          {message && (
            <div className="mt-5">
              <Alert
                type={messageType}
                onClose={() => setMessage('')}
              >
                {message}
              </Alert>
            </div>
          )}
        </Card>
      </div>
    </AdminLayout>
  );
};

export default RegisterShopper;
