import React from 'react';

const variants = {
  default: 'bg-gray-100 text-gray-700',
  blue: 'bg-brand-50 text-brand-700',
  green: 'bg-green-50 text-green-700',
  red: 'bg-red-50 text-red-700',
  yellow: 'bg-amber-50 text-amber-700',
  purple: 'bg-purple-50 text-purple-700',
  indigo: 'bg-indigo-50 text-indigo-700',
};

const sizes = {
  sm: 'px-2 py-0.5 text-xs',
  md: 'px-2.5 py-1 text-xs',
  lg: 'px-3 py-1.5 text-sm',
};

const Badge = ({ children, variant = 'default', size = 'md', className = '' }) => {
  return (
    <span className={`
      inline-flex items-center font-medium rounded-md
      ${variants[variant] || variants.default}
      ${sizes[size] || sizes.md}
      ${className}
    `}>
      {children}
    </span>
  );
};

// Helper to map status strings to badge variants
export const statusVariant = (status) => {
  const s = (status || '').toLowerCase();
  if (['approved', 'verified', 'active', 'completed', 'success', 'delivered', 'paid'].includes(s)) return 'green';
  if (['pending', 'waiting', 'processing', 'unverified'].includes(s)) return 'yellow';
  if (['declined', 'rejected', 'cancelled', 'failed', 'inactive', 'suspended'].includes(s)) return 'red';
  if (['shipped', 'assigned', 'on_the_way'].includes(s)) return 'blue';
  return 'default';
};

export default Badge;
