import React from 'react';

const Card = ({
  children,
  className = '',
  padding = 'md',
  hover = false,
  onClick = null,
  ...props
}) => {
  const paddings = {
    none: '',
    sm: 'p-4',
    md: 'p-5',
    lg: 'p-6',
  };

  const base = 'bg-white rounded-lg border border-gray-200 shadow-sm';
  const hoverCls = hover ? 'hover:shadow-md hover:border-gray-300 transition-all duration-200 cursor-pointer' : '';

  return (
    <div
      className={`${base} ${paddings[padding] || paddings.md} ${hoverCls} ${className}`}
      onClick={onClick}
      {...props}
    >
      {children}
    </div>
  );
};

export default Card;
