import React, { useState, useEffect } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import AdminLayout from '../components/AdminLayout';
import { MapContainer, Marker, Circle, TileLayer, useMapEvents } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { FaClipboardCheck, FaMapMarkerAlt, FaCheckCircle } from 'react-icons/fa';
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  Modal,
  EmptyState,
  Checkbox,
} from '../components/ui';

const DEFAULT_RADIUS = 3; // km
const DEFAULT_CENTER = { lat: 9.03, lng: 38.74 };

function LocationPicker({ location, setLocation }) {
  useMapEvents({
    click(e) {
      setLocation({ lat: e.latlng.lat, lng: e.latlng.lng });
    },
  });
  return null;
}

const ApproveOrders = () => {
  const [orders, setOrders] = useState([]);
  const [deliveryBoys, setDeliveryBoys] = useState([]);
  const [shoppers, setShoppers] = useState([]); // Add shoppers state
  const [assignments, setAssignments] = useState({});
  // New state for nearby assignment
  const [showNearbyModal, setShowNearbyModal] = useState(false);
  const [modalOrder, setModalOrder] = useState(null);
  const [mapLocation, setMapLocation] = useState(DEFAULT_CENTER);
  const [radius, setRadius] = useState(DEFAULT_RADIUS);
  const [nearbyResult, setNearbyResult] = useState(null);
  const [assigningNearby, setAssigningNearby] = useState(false);
  // Multi-delivery selection for nearby modal
  const [selectedDeliveryIds, setSelectedDeliveryIds] = useState([]);

  const fetchData = async () => {
    try {
      const ordersResponse = await apiClient.get('/api/payments/orders');
      const ordersData = ordersResponse.data.orders.filter(order => order.payment_status === 'Approved');
      setOrders(ordersData);

      const deliveryBoysResponse = await apiClient.get('/api/deliveryboy');
      setDeliveryBoys(deliveryBoysResponse.data.deliveryBoys || []);

      // Fetch shoppers
      const shoppersResponse = await apiClient.get('/api/shoppers');
      setShoppers(shoppersResponse.data.shoppers || []);
    } catch (error) {
      toast.error('Error fetching data. Please try again later.');
    }
  };

  useEffect(() => { fetchData(); }, []);

  const handleSelectChange = (orderId, field, value) => {
    setAssignments((prev) => ({
      ...prev,
      [orderId]: {
        ...prev[orderId],
        [field]: value,
      },
    }));
  };

  const handleAssignOrder = async (orderId) => {
    const { shopper_id, delivery_id } = assignments[orderId] || {};
    const order = orders.find(order => order.id === orderId);
    if (!shopper_id && !delivery_id) {
      toast.error('Please select at least a shopper or a delivery boy.');
      return;
    }
    if (!order || !order.id) {
      toast.error('Order information is missing for this order.');
      return;
    }
    try {
      const assignmentData = { payment_id: order.id };
      if (shopper_id) assignmentData.shopper_id = shopper_id;
      if (delivery_id) assignmentData.delivery_id = delivery_id;
      await apiClient.post('/api/assign/assign', assignmentData);
      toast.success('Order assigned successfully!');
      fetchData();
    } catch (error) {
      toast.error('Error assigning order. Please try again.');
    }
  };

  // --- New: Assign to Nearby Delivery ---
  const openNearbyModal = (order) => {
    setModalOrder(order);
    setShowNearbyModal(true);
    setMapLocation(DEFAULT_CENTER);
    setRadius(DEFAULT_RADIUS);
    setNearbyResult(null);
    setSelectedDeliveryIds([]);
  };
  const closeNearbyModal = () => {
    setShowNearbyModal(false);
    setModalOrder(null);
    setNearbyResult(null);
    setSelectedDeliveryIds([]);
  };
  const handleDeliverySelection = (deliveryId) => {
    setSelectedDeliveryIds(prev => {
      if (prev.includes(deliveryId)) {
        return prev.filter(id => id !== deliveryId);
      } else {
        return [...prev, deliveryId];
      }
    });
  };
  const handleNearbyAssign = async () => {
    if (!modalOrder) return;
    if (!selectedDeliveryIds.length) {
      toast.error('Please select at least one delivery person.');
      return;
    }
    setAssigningNearby(true);
    try {
      const res = await apiClient.post(
        `/api/payments/assign-nearby/${modalOrder.id}`,
        { delivery_ids: selectedDeliveryIds, location: mapLocation, radius_km: radius }
      );
      setNearbyResult(res.data);
      toast.success(res.data.message || 'Order sent to nearby deliveries!');
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to assign to nearby deliveries.');
      setNearbyResult(null);
    } finally {
      setAssigningNearby(false);
    }
  };

  const getNearbyDeliveries = () => {
    if (!mapLocation) return [];
    return deliveryBoys.filter(delivery => {
      if (!delivery.latitude || !delivery.longitude || !delivery.is_available) {
        return false;
      }
      // Calculate distance using Haversine formula
      const R = 6371;
      const dLat = (delivery.latitude - mapLocation.lat) * Math.PI / 180;
      const dLon = (delivery.longitude - mapLocation.lng) * Math.PI / 180;
      const a =
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(mapLocation.lat * Math.PI / 180) * Math.cos(delivery.latitude * Math.PI / 180) *
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      const distance = R * c;
      return distance <= radius;
    });
  };
  const nearbyDeliveries = getNearbyDeliveries();

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaClipboardCheck />}
          title="Approve and Assign Orders"
          subtitle="Assign approved orders to shoppers and/or delivery personnel"
        />

        {orders.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {orders.map((order) => (
              <Card key={order.id} padding="md" className="flex flex-col">
                <div className="flex items-center justify-between mb-3">
                  <h3 className="font-semibold text-base sm:text-lg text-gray-900">Order #{order.id}</h3>
                  <Badge variant={order.isAssigned ? 'green' : 'blue'} size="sm">
                    {order.isAssigned ? 'Assigned' : 'Pending'}
                  </Badge>
                </div>
                <div className="space-y-1 mb-4">
                  <p className="text-sm text-gray-600">
                    Payment Status: <span className="font-semibold text-gray-900">{order.payment_status}</span>
                  </p>
                  <p className="text-sm text-gray-600">
                    Total Price: <span className="font-semibold text-gray-900">{order.total_price}</span>
                  </p>
                </div>

                <div className="flex flex-col gap-3 mb-4">
                  {/* Shopper */}
                  <Select
                    label="Select Shopper"
                    id={`shopper-${order.id}`}
                    value={assignments[order.id]?.shopper_id || ''}
                    onChange={(e) => handleSelectChange(order.id, 'shopper_id', e.target.value)}
                    disabled={order.isAssigned}
                    placeholder="Select Shopper"
                    options={shoppers.map((shopper) => ({ value: shopper.id, label: shopper.full_name }))}
                  />
                  {/* Delivery Boy */}
                  <Select
                    label="Select Delivery Boy"
                    id={`deliveryBoy-${order.id}`}
                    value={assignments[order.id]?.delivery_id || ''}
                    onChange={(e) => handleSelectChange(order.id, 'delivery_id', e.target.value)}
                    disabled={order.isAssigned}
                    placeholder="Select Delivery Boy"
                    options={deliveryBoys.map((deliveryBoy) => ({ value: deliveryBoy.id, label: deliveryBoy.full_name }))}
                  />
                </div>

                <div className="flex flex-col sm:flex-row gap-2 mt-auto">
                  <Button
                    onClick={() => handleAssignOrder(order.id)}
                    disabled={order.isAssigned}
                    fullWidth
                  >
                    {order.isAssigned ? 'Assigned' : 'Assign Order'}
                  </Button>
                  <Button
                    onClick={() => openNearbyModal(order)}
                    variant="outline"
                    icon={<FaMapMarkerAlt />}
                    fullWidth
                  >
                    Nearby Delivery
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <Card padding="lg">
            <EmptyState
              icon={<FaClipboardCheck />}
              title="No approved orders found"
              description="There are currently no approved orders waiting to be assigned."
            />
          </Card>
        )}

        <ToastContainer />

        {/* Modal for Assign to Nearby Delivery */}
        <Modal
          open={showNearbyModal}
          onClose={closeNearbyModal}
          title="Assign to Nearby Delivery"
          size="lg"
          footer={
            <Button
              onClick={handleNearbyAssign}
              loading={assigningNearby}
              disabled={nearbyDeliveries.length === 0 || selectedDeliveryIds.length === 0}
              fullWidth
            >
              Send to Nearby Deliveries
            </Button>
          }
        >
          <div className="space-y-4">
            <p className="text-sm text-gray-600">Pick location and radius to notify available deliveries.</p>

            {/* Filter delivery boys by radius and location */}
            <div>
              <label className="block font-semibold text-sm text-gray-700 mb-2">Select Delivery People:</label>
              {nearbyDeliveries.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2">
                  {nearbyDeliveries.map((delivery) => (
                    <Checkbox
                      key={delivery.id}
                      label={delivery.full_name}
                      checked={selectedDeliveryIds.includes(delivery.id)}
                      onChange={() => handleDeliverySelection(delivery.id)}
                    />
                  ))}
                </div>
              ) : (
                <EmptyState
                  title="No delivery accessible"
                  description="No delivery is accessible within the selected radius. Try increasing the radius or selecting a different location."
                />
              )}
              <p className="text-xs text-gray-400 mt-2">You can select multiple delivery people.</p>
            </div>

            <div className="rounded-lg overflow-hidden border border-gray-200 shadow-sm">
              <MapContainer
                center={[mapLocation.lat, mapLocation.lng]}
                zoom={13}
                style={{ height: '220px', width: '100%' }}
                scrollWheelZoom={true}
              >
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                <Marker position={[mapLocation.lat, mapLocation.lng]} />
                <Circle center={[mapLocation.lat, mapLocation.lng]} radius={radius * 1000} pathOptions={{ color: 'blue' }} />
                <LocationPicker location={mapLocation} setLocation={setMapLocation} />
              </MapContainer>
              <div className="flex flex-col sm:flex-row sm:items-center gap-2 p-3">
                <label className="text-sm text-gray-600">Radius:</label>
                <input
                  type="range"
                  min={1}
                  max={10}
                  value={radius}
                  onChange={e => setRadius(Number(e.target.value))}
                  className="w-32 accent-brand-500"
                />
                <span className="text-sm font-semibold text-gray-700">{radius} km</span>
              </div>
            </div>

            {nearbyResult && (
              <div className="p-4 bg-brand-50 rounded-lg border border-brand-100">
                <div className="flex items-center gap-2 text-brand-600 font-semibold text-sm mb-2">
                  <FaCheckCircle /> {nearbyResult.message}
                </div>
                {nearbyResult.notified_deliveries && (
                  <div>
                    <div className="text-sm font-semibold text-brand-600 mb-1">Notified Deliveries:</div>
                    <ul className="list-disc ml-5 text-sm text-brand-500">
                      {nearbyResult.notified_deliveries.map(d => (
                        <li key={d.id}>{d.name} (ID: {d.id})</li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            )}
          </div>
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default ApproveOrders;
