import React, { useState, useEffect, useCallback } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { FaRulerCombined, FaBoxOpen, FaImage } from "react-icons/fa";
import apiClient, { API_BASE_URL } from '../config/api';
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  FileInput,
  Alert,
  Modal,
  Spinner,
  EmptyState,
  SearchBar,
} from '../components/ui';

// Helper function to parse the first image from the product data
const parseFirstImage = (imageJsonString, baseUrl) => {
  if (!imageJsonString) return null;
  try {
    let imagesArray;
    if (Array.isArray(imageJsonString)) {
      imagesArray = imageJsonString;
    } else if (typeof imageJsonString === 'string') {
      imagesArray = JSON.parse(imageJsonString);
    } else {
      return null;
    }

    if (Array.isArray(imagesArray) && imagesArray.length > 0) {
      let path = imagesArray[0];
      if (typeof path === 'string') {
        if (path.startsWith('http://') || path.startsWith('https://')) {
          return path;
        }
        if (path.startsWith('/')) {
          return `${baseUrl}${path}`;
        }
      }
    }
  } catch (e) {
    console.error("Failed to parse product image JSON string:", imageJsonString, "Error:", e);
  }
  return null;
};

const uomTypeOptions = [
  { value: "size", label: "Size" },
  { value: "volume", label: "Volume" },
  { value: "weight", label: "Weight" },
  { value: "level", label: "Level" },
  { value: "piece", label: "Piece" },
  { value: "pack", label: "Pack" },
  { value: "box", label: "Box" },
  { value: "other", label: "Other" },
];

const stockOptions = [
  { value: "in_stock", label: "In Stock" },
  { value: "out_of_stock", label: "Out of Stock" },
  { value: "limited_stock", label: "Limited Stock" },
];

const UOMCreate = () => {
  const { productId: routeProductId } = useParams();
  const navigate = useNavigate();

  const [type, setType] = useState("size");
  const [value, setValue] = useState("");
  const [price, setPrice] = useState("");
  const [stock, setStock] = useState("in_stock");
  const [image, setImage] = useState(null);

  const [modalIsOpen, setModalIsOpen] = useState(false);

  const [products, setProducts] = useState([]);
  const [isLoadingProducts, setIsLoadingProducts] = useState(false);
  const [productFetchError, setProductFetchError] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");

  const fetchProducts = useCallback(async () => {
    setIsLoadingProducts(true);
    setProductFetchError(null);
    try {
      const res = await apiClient.get('/api/prod');
      console.log("Fetched products response:", res.data);

      let fetchedProducts = [];
      if (Array.isArray(res.data)) {
        fetchedProducts = res.data;
      } else if (res.data && Array.isArray(res.data.products)) {
        fetchedProducts = res.data.products;
      } else if (res.data && Array.isArray(res.data.data)) {
        fetchedProducts = res.data.data;
      } else {
        console.warn("Products data is not in a recognized array format:", res.data);
      }

      const mappedProducts = fetchedProducts.map(p => ({
        ...p,
        name: p.title || p.name || 'Unnamed Product',
        price: p.price || 0,
        image_url: parseFirstImage(p.image, API_BASE_URL)
      }));
      setProducts(mappedProducts);

    } catch (err) {
      console.error("Failed to fetch products:", err);
      setProductFetchError("Failed to load products. Please check connection and try again.");
      setProducts([]);
    } finally {
      setIsLoadingProducts(false);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  useEffect(() => {
    if (routeProductId && products.length > 0 && !selectedProduct) {
      const numericProductId = parseInt(routeProductId, 10);
      const productToSelect = products.find(p => p.id === numericProductId);
      if (productToSelect) {
        setSelectedProduct(productToSelect);
      } else {
        toast.warn(`Product with ID ${routeProductId} not found.`);
      }
    }
  }, [routeProductId, products, selectedProduct]);


  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedProduct || !value || !price) {
      toast.error("Please select a product and fill in UOM value and price.");
      return;
    }

    const formData = new FormData();
    formData.append("product_id", selectedProduct.id);
    formData.append("type", type);
    formData.append("value", value);
    formData.append("price", price);
    formData.append("stock", stock);
    if (image) {
      formData.append("image", image);
    }

    try {
      await apiClient.post('/api/uoms', formData);
      toast.success(`UOM (${type}: ${value}) created successfully for ${selectedProduct.name}! You can add another.`);

      setValue("");
      setPrice("");
      setImage(null);
      const fileInput = document.getElementById('uom-image');
      if (fileInput) fileInput.value = "";

    } catch (error) {
      console.error("Error creating UOM:", error.response?.data || error.message);
      toast.error(error.response?.data?.message || "Failed to create UOM. Please try again.");
    }
  };

  const openModal = () => {
    setSearchTerm("");
    setModalIsOpen(true);
  }
  const closeModal = () => setModalIsOpen(false);

  const handleProductSelect = (product) => {
    setSelectedProduct(product);
    setType("size");
    setValue("");
    setPrice("");
    setStock("in_stock");
    setImage(null);
    const fileInput = document.getElementById('uom-image');
    if (fileInput) fileInput.value = "";
    closeModal();
  };

  const filteredProducts = products.filter(product =>
    product.name && product.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <AdminLayout>
      <ToastContainer position="top-right" autoClose={4000} hideProgressBar={false} newestOnTop closeOnClick rtl={false} pauseOnFocusLoss draggable pauseOnHover />

      <div className="max-w-2xl mx-auto p-4 sm:p-6">
        <PageHeader
          icon={<FaRulerCombined />}
          title="Create Unit of Measurement"
          subtitle="Add units of measurement for a selected product"
        />

        {/* Product Selection Section */}
        <Card padding="md" className="mb-6">
          <Button
            variant="primary"
            size="lg"
            fullWidth
            icon={<FaBoxOpen />}
            onClick={openModal}
          >
            {selectedProduct ? `Change Product (Selected: ${selectedProduct.name})` : "Select Product *"}
          </Button>

          {selectedProduct && (
            <div className="mt-4 border border-amber-200 bg-amber-50/50 p-4 rounded-lg">
              <h3 className="text-lg font-semibold text-gray-900">{selectedProduct.name}</h3>
              <p className="text-gray-600 text-sm">Base Price: {selectedProduct.price} ETB</p>
              {selectedProduct.image_url && (
                <img
                  src={selectedProduct.image_url}
                  alt={selectedProduct.name}
                  className="w-24 h-24 sm:w-32 sm:h-32 object-cover mt-2 rounded-lg border border-gray-200"
                />
              )}
              {!selectedProduct.image_url && (
                <div className="w-24 h-24 sm:w-32 sm:h-32 object-cover mt-2 rounded-lg border border-gray-200 bg-gray-100 flex items-center justify-center">
                  <span className="text-gray-400 text-xs">No Product Image</span>
                </div>
              )}
            </div>
          )}
        </Card>

        {/* UOM Creation Form - Only show if a product is selected */}
        {selectedProduct && (
          <Card padding="md">
            <p className="text-sm text-gray-600 mb-5">
              Adding UOM for: <strong className="text-brand-500">{selectedProduct.name}</strong>
            </p>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Select
                  label="UOM Type"
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  options={uomTypeOptions}
                  placeholder={null}
                />

                <Select
                  label="Stock Status"
                  value={stock}
                  onChange={(e) => setStock(e.target.value)}
                  options={stockOptions}
                  placeholder={null}
                />

                <Input
                  label="Value"
                  type="text"
                  value={value}
                  onChange={(e) => setValue(e.target.value)}
                  required
                  placeholder="e.g., Medium, 500ml, 1kg, 6-pack"
                />

                <Input
                  label="Price for this UOM (ETB)"
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  required
                  step="0.01"
                  min="0"
                  placeholder="e.g., 100.00"
                />
              </div>

              <FileInput
                id="uom-image"
                label="Image for this UOM (Optional)"
                onChange={(e) => setImage(e.target.files[0])}
                accept="image/*"
                hint="Upload an optional image representing this unit of measurement"
              />

              <Button
                type="submit"
                variant="warning"
                size="lg"
                fullWidth
              >
                Create UOM for {selectedProduct.name}
              </Button>
            </form>
          </Card>
        )}

        {!selectedProduct && (
          <Card padding="lg">
            <EmptyState
              icon={<FaBoxOpen />}
              title="No product selected"
              description="Please select a product to add Units of Measurement."
              action={
                <Button variant="primary" size="md" icon={<FaBoxOpen />} onClick={openModal}>
                  Select Product
                </Button>
              }
            />
          </Card>
        )}

        {/* Product Selection Modal */}
        <Modal
          open={modalIsOpen}
          onClose={closeModal}
          title="Select a Product"
          size="xl"
        >
          <div className="space-y-4">
            <SearchBar
              value={searchTerm}
              onChange={setSearchTerm}
              placeholder="Search products by name..."
            />

            {isLoadingProducts && (
              <div className="py-12">
                <Spinner size="lg" label="Loading products..." />
              </div>
            )}

            {productFetchError && (
              <Alert type="error" title="Error">
                {productFetchError}
              </Alert>
            )}

            {!isLoadingProducts && !productFetchError && products.length === 0 && !searchTerm && (
              <EmptyState
                icon={<FaBoxOpen />}
                title="No products available"
                description="There are no products to select from."
              />
            )}

            {!isLoadingProducts && !productFetchError && filteredProducts.length === 0 && searchTerm && (
              <EmptyState
                icon={<FaBoxOpen />}
                title="No products found"
                description={`No products found matching "${searchTerm}".`}
              />
            )}

            {!isLoadingProducts && !productFetchError && filteredProducts.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 sm:gap-4">
                {filteredProducts.map((product) => (
                  <Card
                    key={product.id}
                    padding="sm"
                    hover
                    onClick={() => handleProductSelect(product)}
                    className="flex flex-col items-center text-center h-full"
                  >
                    {product.image_url && (
                      <img
                        src={product.image_url}
                        alt={product.name}
                        className="w-20 h-20 sm:w-24 sm:h-24 object-cover mb-2 rounded-lg border"
                      />
                    )}
                    {!product.image_url && (
                      <div className="w-20 h-20 sm:w-24 sm:h-24 mb-2 rounded-lg border bg-gray-100 flex items-center justify-center">
                        <FaImage className="text-gray-300 text-2xl" />
                      </div>
                    )}
                    <p className="font-medium text-gray-900 text-sm leading-tight line-clamp-2 flex-grow">{product.name}</p>
                    <p className="text-xs text-gray-500 mt-1">{product.price} ETB</p>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default UOMCreate;
