"use client"

import { useState, useEffect } from "react"
import apiClient, { API_BASE_URL } from '../config/api'
import { ToastContainer, toast } from "react-toastify"
import "react-toastify/dist/ReactToastify.css"
import AdminLayout from '../components/AdminLayout'
import {
  Package,
  CheckCircle,
  ArrowRight,
  Plus,
  Smartphone,
  Tag,
  DollarSign,
  Palette,
  Ruler,
  Building,
  Mail,
  ImageIcon,
  RotateCcw,
  Zap,
  Globe,
} from "lucide-react"
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  FileInput,
  TextArea,
} from '../components/ui'

const productTypeOptions = [
  { value: "retail", label: "Retail" },
  { value: "wholesale", label: "Wholesale" },
  { value: "import", label: "Import" },
  { value: "export", label: "Export" },
]

const sellerLevelOptions = [
  { value: "importer", label: "Importer" },
  { value: "exporter", label: "Exporter" },
  { value: "reseller", label: "Reseller" },
]

const uomTypeOptions = [
  { value: "size", label: "Size" },
  { value: "volume", label: "Volume" },
  { value: "weight", label: "Weight" },
  { value: "level", label: "Level" },
  { value: "piece", label: "Piece" },
  { value: "pack", label: "Pack" },
  { value: "box", label: "Box" },
  { value: "other", label: "Other" },
]

const stockOptions = [
  { value: "in_stock", label: "In Stock" },
  { value: "out_of_stock", label: "Out of Stock" },
  { value: "limited_stock", label: "Limited Stock" },
]

const productFields = [
  { label: "Product Title", name: "title", type: "text", required: true, icon: <Package className="w-4 h-4" /> },
  { label: "SKU (Optional)", name: "sku", type: "text", required: false, icon: <Tag className="w-4 h-4" /> },
  { label: "Color", name: "color", type: "text", required: true, icon: <Palette className="w-4 h-4" /> },
  { label: "Size", name: "size", type: "text", required: true, icon: <Ruler className="w-4 h-4" /> },
  { label: "Brand", name: "brand", type: "text", required: true, icon: <Building className="w-4 h-4" /> },
  { label: "Price (ETB)", name: "price", type: "number", required: true, icon: <DollarSign className="w-4 h-4" /> },
  { label: "Seller Email", name: "seller_email", type: "email", required: true, icon: <Mail className="w-4 h-4" /> },
]

const CombinedProductUOM = () => {
  // Step management
  const [currentStep, setCurrentStep] = useState(1)
  const [createdProduct, setCreatedProduct] = useState(null)

  // Product form state
  const [productData, setProductData] = useState({
    title: "",
    sku: "",
    color: "",
    size: "",
    brand: "",
    price: "",
    description: "",
    catItems: "",
    subcat: "",
    seller_email: "",
    product_type: "retail",
    seller_level: "reseller",
    origin_country: "",
    destination_country: "",
  })
  const [images, setImages] = useState([])
  const [previewImages, setPreviewImages] = useState([])
  const [categories, setCategories] = useState([])
  const [subcategories, setSubcategories] = useState([])
  const [productLoading, setProductLoading] = useState(false)

  // UOM form state
  const [type, setType] = useState("size")
  const [value, setValue] = useState("")
  const [uomPrice, setUomPrice] = useState("")
  const [stock, setStock] = useState("in_stock")
  const [uomImage, setUomImage] = useState(null)
  const [uomLoading, setUomLoading] = useState(false)

  // Helper function to parse the first image from the product data
  const parseFirstImage = (imageJsonString, baseUrl) => {
    if (!imageJsonString) return null
    try {
      let imagesArray
      if (Array.isArray(imageJsonString)) {
        imagesArray = imageJsonString
      } else if (typeof imageJsonString === "string") {
        imagesArray = JSON.parse(imageJsonString)
      } else {
        return null
      }

      if (Array.isArray(imagesArray) && imagesArray.length > 0) {
        const path = imagesArray[0]
        if (typeof path === "string") {
          if (path.startsWith("http://") || path.startsWith("https://")) {
            return path
          }
          if (path.startsWith("/")) {
            return `${baseUrl}${path}`
          }
        }
      }
    } catch (e) {
      console.error("Failed to parse product image JSON string:", imageJsonString, "Error:", e)
    }
    return null
  }

  // Fetch categories and subcategories
  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await apiClient.get('/api/catitem')
        setCategories(response.data)
      } catch (error) {
        console.error("Error fetching categories:", error)
      }
    }
    fetchCategories()
  }, [])

  useEffect(() => {
    const fetchSubcategories = async () => {
      try {
        const response = await apiClient.get('/api/subcat')
        setSubcategories(response.data)
      } catch (error) {
        console.error("Error fetching subcategories:", error)
      }
    }
    fetchSubcategories()
  }, [])

  // Product form handlers
  const handleProductChange = (e) => {
    const { name, value } = e.target
    setProductData({ ...productData, [name]: value })
  }

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files)
    setImages(files)
    const previewUrls = files.map((file) => URL.createObjectURL(file))
    setPreviewImages(previewUrls)
  }

  // Product submission
  const handleProductSubmit = async (e) => {
    e.preventDefault()
    const formData = new FormData()
    Object.keys(productData).forEach((key) => {
      // Only include origin_country when product_type is import
      if (key === "origin_country" && productData.product_type !== "import") {
        return
      }
      // Only include destination_country when product_type is export
      if (key === "destination_country" && productData.product_type !== "export") {
        return
      }
      formData.append(key, productData[key])
    })
    images.forEach((image) => {
      formData.append("image", image)
    })

    setProductLoading(true)
    try {
      const response = await apiClient.post('/api/prod', formData, {
        headers: { "Content-Type": "multipart/form-data" },
      })

      const newProduct = response.data.product || response.data
      setCreatedProduct({
        ...newProduct,
        name: newProduct.title || newProduct.name || "New Product",
        image_url: parseFirstImage(newProduct.image, API_BASE_URL),
      })

      toast.success("Product created! Now add your UOMs", {
        position: "top-center",
      })

      // Move to step 2 (UOM creation)
      setCurrentStep(2)
    } catch (error) {
      console.error(error)
      if (error.response && error.response.data.errors) {
        const validationErrors = error.response.data.errors.join(", ")
        toast.error(`${validationErrors}`, {
          position: "top-center",
        })
      } else {
        toast.error("Error adding product. Please try again.", {
          position: "top-center",
        })
      }
    } finally {
      setProductLoading(false)
    }
  }

  // UOM submission
  const handleUOMSubmit = async (e) => {
    e.preventDefault()
    if (!createdProduct || !value || !uomPrice) {
      toast.error("Please fill in UOM value and price.")
      return
    }

    const formData = new FormData()
    formData.append("product_id", createdProduct.id)
    formData.append("type", type)
    formData.append("value", value)
    formData.append("price", uomPrice)
    formData.append("stock", stock)
    if (uomImage) {
      formData.append("image", uomImage)
    }

    setUomLoading(true)
    try {
      await apiClient.post('/api/uoms', formData)
      toast.success(`${type}: ${value} added successfully!`)

      // Clear UOM form for next entry
      setValue("")
      setUomPrice("")
      setUomImage(null)
      const fileInput = document.getElementById('uom-image-file')
      if (fileInput) fileInput.value = ""
    } catch (error) {
      console.error("Error creating UOM:", error.response?.data || error.message)
      toast.error(error.response?.data?.message || "Failed to create UOM. Please try again.")
    } finally {
      setUomLoading(false)
    }
  }

  // Reset everything to start over
  const handleStartOver = () => {
    setCurrentStep(1)
    setCreatedProduct(null)
    setProductData({
      title: "",
      sku: "",
      color: "",
      size: "",
      brand: "",
      price: "",
      description: "",
      catItems: "",
      subcat: "",
      seller_email: "",
      product_type: "retail",
      seller_level: "reseller",
      origin_country: "",
      destination_country: "",
    })
    setImages([])
    setPreviewImages([])
    setValue("")
    setUomPrice("")
    setType("size")
    setStock("in_stock")
    setUomImage(null)
    const fileInput = document.getElementById('uom-image-file')
    if (fileInput) fileInput.value = ""
  }

  const categoryOptions = categories.map((cat) => ({ value: cat.id, label: cat.name }))
  const subcategoryOptions = subcategories.map((subcat) => ({ value: subcat.id, label: subcat.name }))

  return (
    <AdminLayout>
      <ToastContainer
        position="top-center"
        autoClose={3000}
        hideProgressBar={false}
        newestOnTop
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable
        pauseOnHover
        theme="colored"
      />

      <div className="max-w-2xl mx-auto p-4 sm:p-6">
        <PageHeader
          icon={<Smartphone className="w-5 h-5" />}
          title="Product Creator"
          subtitle="Create a product and add its units of measurement in two steps"
        />

        {/* Progress indicator */}
        <Card padding="md" className="mb-6">
          <div className="max-w-sm mx-auto">
            <div className="flex items-center justify-between mb-3 min-w-[280px]">
              <div className="flex items-center space-x-2">
                <div
                  className={`flex items-center justify-center w-10 h-10 rounded-full transition-all duration-300 ${
                    currentStep >= 1 ? "bg-brand-500 text-white shadow-sm scale-110" : "bg-gray-100 text-gray-400"
                  }`}
                >
                  {currentStep > 1 ? <CheckCircle className="w-6 h-6" /> : "1"}
                </div>
                <span className="text-sm font-medium text-gray-700">Product</span>
              </div>

              <div
                className={`h-1 flex-1 mx-4 rounded-full transition-all duration-500 ${
                  currentStep >= 2 ? "bg-brand-500" : "bg-gray-200"
                }`}
              />

              <div className="flex items-center space-x-2">
                <div
                  className={`flex items-center justify-center w-10 h-10 rounded-full transition-all duration-300 ${
                    currentStep >= 2 ? "bg-brand-500 text-white shadow-sm scale-110" : "bg-gray-100 text-gray-400"
                  }`}
                >
                  {currentStep >= 2 ? <Zap className="w-6 h-6" /> : "2"}
                </div>
                <span className="text-sm font-medium text-gray-700">UOMs</span>
              </div>
            </div>
          </div>
        </Card>

        {/* Step 1: Add Product */}
        {currentStep === 1 && (
          <Card padding="md">
            <div className="flex items-center space-x-3 mb-6">
              <div className="bg-brand-50 p-3 rounded-lg text-brand-500">
                <Package className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-gray-900">Create Product</h2>
                <p className="text-gray-500 text-sm">Fill in your product details</p>
              </div>
            </div>

            <form onSubmit={handleProductSubmit} className="space-y-5">
              {productFields.map(({ label, name, type, required, icon }) => (
                <Input
                  key={name}
                  label={label}
                  type={type}
                  value={productData[name]}
                  onChange={handleProductChange}
                  required={required}
                  icon={icon}
                  placeholder={`Enter ${label.toLowerCase()}`}
                />
              ))}

              {/* Product Type & Seller Level */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Select
                  label="Product Type"
                  value={productData.product_type}
                  onChange={handleProductChange}
                  options={productTypeOptions}
                  required
                  placeholder={null}
                />

                <Select
                  label="Seller Level"
                  value={productData.seller_level}
                  onChange={handleProductChange}
                  options={sellerLevelOptions}
                  required
                  placeholder={null}
                />
              </div>

              {/* Conditional: Origin Country (import) */}
              {productData.product_type === "import" && (
                <Input
                  label="Origin Country"
                  type="text"
                  value={productData.origin_country}
                  onChange={handleProductChange}
                  required
                  icon={<Globe className="w-4 h-4" />}
                  placeholder="Enter origin country"
                />
              )}

              {/* Conditional: Destination Country (export) */}
              {productData.product_type === "export" && (
                <Input
                  label="Destination Country"
                  type="text"
                  value={productData.destination_country}
                  onChange={handleProductChange}
                  required
                  icon={<Globe className="w-4 h-4" />}
                  placeholder="Enter destination country"
                />
              )}

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Select
                  label="Category"
                  value={productData.catItems}
                  onChange={handleProductChange}
                  options={categoryOptions}
                  required
                  placeholder="Select Category"
                />

                <Select
                  label="Subcategory"
                  value={productData.subcat}
                  onChange={handleProductChange}
                  options={subcategoryOptions}
                  required
                  placeholder="Select Subcategory"
                />
              </div>

              <TextArea
                label="Description"
                value={productData.description}
                onChange={handleProductChange}
                required
                rows={4}
                placeholder="Describe your product..."
              />

              {/* Product Images - multiple file selection */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Product Images
                  <span className="text-red-500 ml-1">*</span>
                </label>
                <input
                  id="product-images"
                  type="file"
                  multiple
                  onChange={handleImageChange}
                  required
                  accept="image/*"
                  className="w-full text-sm text-gray-500 file:mr-4 file:py-2.5 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-brand-50 file:text-brand-600 hover:file:bg-brand-100 file:cursor-pointer cursor-pointer transition-all border-2 border-dashed border-gray-200 rounded-lg p-4 bg-gray-50"
                />
                {previewImages.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 mt-4">
                    {previewImages.map((src, index) => (
                      <div key={index} className="relative group">
                        <img
                          src={src || "/placeholder.svg"}
                          alt={`Preview ${index}`}
                          className="w-full h-24 object-cover rounded-lg shadow-md group-hover:shadow-sm transition-shadow"
                        />
                        <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-20 rounded-lg transition-all"></div>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <Button
                type="submit"
                variant="primary"
                size="lg"
                fullWidth
                loading={productLoading}
                iconRight={<ArrowRight className="w-5 h-5" />}
              >
                Create Product
              </Button>
            </form>
          </Card>
        )}

        {/* Step 2: Add UOMs */}
        {currentStep === 2 && createdProduct && (
          <div className="space-y-6">
            {/* Product Success Card */}
            <Card padding="md" className="bg-brand-500 border-brand-500">
              <div className="flex items-center space-x-3 mb-4">
                <CheckCircle className="w-8 h-8 text-white" />
                <div>
                  <h3 className="text-lg font-bold text-white">Product Created!</h3>
                  <p className="text-brand-100 text-sm">{createdProduct.name}</p>
                </div>
              </div>

              <div className="flex items-center space-x-4 bg-white/20 rounded-lg p-4">
                {createdProduct.image_url ? (
                  <img
                    src={createdProduct.image_url || "/placeholder.svg"}
                    alt={createdProduct.name}
                    className="w-16 h-16 object-cover rounded-lg border-2 border-white"
                  />
                ) : (
                  <div className="w-16 h-16 bg-white/30 rounded-lg flex items-center justify-center">
                    <ImageIcon className="w-8 h-8 text-white" />
                  </div>
                )}
                <div>
                  <p className="font-semibold text-white">{createdProduct.name}</p>
                  <p className="text-brand-100 text-sm">Base Price: {createdProduct.price} ETB</p>
                </div>
              </div>
            </Card>

            {/* UOM Form */}
            <Card padding="md">
              <div className="flex items-center space-x-3 mb-6">
                <div className="bg-amber-50 p-3 rounded-lg text-amber-600">
                  <Zap className="w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-gray-900">Add UOM</h2>
                  <p className="text-gray-500 text-sm">Create units of measurement</p>
                </div>
              </div>

              <form onSubmit={handleUOMSubmit} className="space-y-5">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <Select
                    label="UOM Type"
                    value={type}
                    onChange={(e) => setType(e.target.value)}
                    options={uomTypeOptions}
                    placeholder={null}
                  />

                  <Select
                    label="Stock Status"
                    value={stock}
                    onChange={(e) => setStock(e.target.value)}
                    options={stockOptions}
                    placeholder={null}
                  />
                </div>

                <Input
                  label="Value"
                  type="text"
                  value={value}
                  onChange={(e) => setValue(e.target.value)}
                  required
                  placeholder="e.g., Medium, 500ml, 1kg, 6-pack"
                />

                <Input
                  label="Price for this UOM (ETB)"
                  type="number"
                  value={uomPrice}
                  onChange={(e) => setUomPrice(e.target.value)}
                  required
                  step="0.01"
                  min="0"
                  placeholder="100.00"
                />

                <FileInput
                  id="uom-image-file"
                  label="UOM Image (Optional)"
                  onChange={(e) => setUomImage(e.target.files[0])}
                  accept="image/*"
                  hint="Upload an optional image representing this unit of measurement"
                />

                <div className="flex flex-col sm:flex-row gap-3">
                  <Button
                    type="submit"
                    variant="warning"
                    size="lg"
                    loading={uomLoading}
                    icon={<Plus className="w-5 h-5" />}
                    className="flex-1"
                  >
                    Add UOM
                  </Button>

                  <Button
                    type="button"
                    variant="secondary"
                    size="lg"
                    onClick={handleStartOver}
                    icon={<RotateCcw className="w-5 h-5" />}
                  >
                    Start Over
                  </Button>
                </div>
              </form>
            </Card>
          </div>
        )}
      </div>
    </AdminLayout>
  )
}

export default CombinedProductUOM
