import React, { useState } from "react";
import apiClient, { API_BASE_URL } from "../config/api";
import { motion, AnimatePresence } from "framer-motion";
import useSWR from "swr";
import AdminLayout from "../components/AdminLayout";
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  Alert,
  Modal,
  Spinner,
  EmptyState,
  SearchBar,
  statusVariant,
} from "../components/ui";
import {
  FaSyncAlt,
  FaEye,
  FaCheck,
  FaTimes,
  FaPencilAlt,
  FaBoxOpen,
} from "react-icons/fa";

const fetcher = (url) => apiClient.get(url).then((res) => res.data);

const SellerProductManagement = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [modalIsOpen, setModalIsOpen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isEditingStatus, setIsEditingStatus] = useState(false);
  const [tempStatus, setTempStatus] = useState("");
  const [alertMessage, setAlertMessage] = useState("");
  const [alertType, setAlertType] = useState("error");

  const { data, error, mutate } = useSWR(
    "/api/prod?seller_only=true",
    fetcher
  );

  // Normalize the API response — handle both array and { products: [] } formats
  const products = Array.isArray(data)
    ? data
    : data && Array.isArray(data.products)
    ? data.products
    : [];

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await mutate();
    setIsRefreshing(false);
  };

  const updateProductStatus = async (id, action) => {
    try {
      const newStatus = action === "approve" ? "approved" : "declined";
      await apiClient.put(`/api/prod/${id}/status`, { status: newStatus });
      mutate();

      if (selectedProduct && selectedProduct.id === id) {
        setSelectedProduct((prev) => ({
          ...prev,
          status: newStatus,
        }));
      }
    } catch (error) {
      console.error("Status update error:", error);
      setAlertType("error");
      setAlertMessage(`Failed to ${action} product.`);
    }
  };

  const handleEditStatus = () => {
    setIsEditingStatus(true);
    setTempStatus(selectedProduct.status);
  };

  const handleSaveStatus = async () => {
    try {
      await apiClient.put(`/api/prod/${selectedProduct.id}/status`, {
        status: tempStatus,
      });

      mutate();
      setSelectedProduct((prev) => ({ ...prev, status: tempStatus }));
      setIsEditingStatus(false);
    } catch (error) {
      console.error("Failed to update status:", error);
      setAlertType("error");
      setAlertMessage("Failed to update status.");
    }
  };

  const filteredProducts = products.filter((product) =>
    (product.title || "").toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Helper function to parse image URLs.
  // Handles all the formats the DB/API can return:
  //   - JSON array string: '["/uploads/x.png"]'
  //   - Plain path string: '/uploads/x.png'
  //   - Already an array (rare): ['/uploads/x.png']
  //   - Empty/null/undefined: []
  const parseImageUrls = (raw) => {
    if (!raw) return [];
    try {
      // Already an array (API parsed it for us)
      if (Array.isArray(raw)) {
        return raw.map((image) => `${API_BASE_URL}${image}`);
      }
      // String — could be a JSON array or a plain path
      if (typeof raw === "string") {
        const trimmed = raw.trim();
        if (!trimmed) return [];
        // JSON array form
        if (trimmed.startsWith("[")) {
          const images = JSON.parse(trimmed);
          return Array.isArray(images)
            ? images.map((image) => `${API_BASE_URL}${image}`)
            : [];
        }
        // Plain path form — wrap it
        return [`${API_BASE_URL}${trimmed}`];
      }
      return [];
    } catch (error) {
      console.error("Error parsing image URLs:", error);
      return [];
    }
  };

  const statusOptions = [
    { value: "pending", label: "Pending" },
    { value: "approved", label: "Approved" },
    { value: "declined", label: "Declined" },
  ];

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaBoxOpen />}
          title="Seller Product Management"
          subtitle="Review and manage seller product listings"
          actions={
            <Button
              variant="outline"
              size="sm"
              icon={<FaSyncAlt className={isRefreshing ? "animate-spin" : ""} />}
              onClick={handleRefresh}
            >
              Refresh
            </Button>
          }
        />

        {/* Alert for action errors */}
        {alertMessage && (
          <div className="mb-5">
            <Alert type={alertType} onClose={() => setAlertMessage("")}>
              {alertMessage}
            </Alert>
          </div>
        )}

        {/* Search bar */}
        <div className="mb-5 flex gap-2">
          <SearchBar
            value={searchTerm}
            onChange={setSearchTerm}
            placeholder="Search products..."
          />
        </div>

        {/* Error loading products */}
        {error && (
          <Alert type="error">Failed to load products. Please try again.</Alert>
        )}

        {/* Loading state */}
        {!error && !data && (
          <Card padding="md">
            <Spinner label="Loading products..." className="py-16" />
          </Card>
        )}

        {/* Empty state */}
        {!error && data && filteredProducts.length === 0 && (
          <Card padding="md">
            <EmptyState
              icon={<FaBoxOpen />}
              title="No products found"
              description="No seller products match your search."
            />
          </Card>
        )}

        {/* Product grid */}
        {!error && data && filteredProducts.length > 0 && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredProducts.map((product) => {
              const imageUrls = parseImageUrls(product.image);
              return (
                <motion.div
                  key={product.id}
                  layout
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                >
                  <Card padding="md" hover className="flex flex-col h-full">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center space-x-3">
                        {imageUrls.length > 0 && (
                          <img
                            src={imageUrls[0]}
                            alt={product.title}
                            className="w-10 h-10 rounded-full object-cover"
                          />
                        )}
                        <div>
                          <h3 className="font-semibold text-gray-900">{product.title}</h3>
                          <p className="text-sm text-gray-500">{product.seller_email}</p>
                        </div>
                      </div>
                      <Badge variant={statusVariant(product.status)} size="md">
                        {product.status}
                      </Badge>
                    </div>

                    {/* Product type and seller level badges */}
                    <div className="flex flex-wrap gap-2 mb-2">
                      {product.product_type && (
                        <Badge variant="blue" size="sm">
                          {product.product_type}
                        </Badge>
                      )}
                      {product.seller_level && (
                        <Badge variant="purple" size="sm">
                          Level: {product.seller_level}
                        </Badge>
                      )}
                    </div>

                    <div className="flex flex-col sm:flex-row justify-end gap-2 mt-4">
                      <Button
                        variant="primary"
                        size="sm"
                        icon={<FaEye />}
                        onClick={() => {
                          setSelectedProduct({ ...product, imageUrls });
                          setModalIsOpen(true);
                        }}
                      >
                        Details
                      </Button>
                      {product.status === "pending" && (
                        <>
                          <Button
                            variant="success"
                            size="sm"
                            icon={<FaCheck />}
                            onClick={() => updateProductStatus(product.id, "approve")}
                          >
                            Approve
                          </Button>
                          <Button
                            variant="danger"
                            size="sm"
                            icon={<FaTimes />}
                            onClick={() => updateProductStatus(product.id, "decline")}
                          >
                            Decline
                          </Button>
                        </>
                      )}
                    </div>
                  </Card>
                </motion.div>
              );
            })}
          </div>
        )}

        {/* Product Details Modal */}
        <AnimatePresence>
          {modalIsOpen && selectedProduct && (
            <Modal
              open={modalIsOpen}
              onClose={() => {
                setModalIsOpen(false);
                setIsEditingStatus(false);
              }}
              title="Product Details"
              size="lg"
              footer={
                <div className="flex flex-col sm:flex-row justify-end gap-2">
                  {isEditingStatus ? (
                    <>
                      <Button
                        variant="primary"
                        size="md"
                        onClick={handleSaveStatus}
                      >
                        Save
                      </Button>
                      <Button
                        variant="secondary"
                        size="md"
                        onClick={() => setIsEditingStatus(false)}
                      >
                        Cancel
                      </Button>
                    </>
                  ) : (
                    <Button
                      variant="secondary"
                      size="md"
                      onClick={() => setModalIsOpen(false)}
                    >
                      Close
                    </Button>
                  )}
                </div>
              }
            >
              <motion.div
                initial={{ opacity: 0, y: 50 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 50 }}
                className="space-y-3"
              >
                {selectedProduct.imageUrls.length > 0 && (
                  <img
                    src={selectedProduct.imageUrls[0]}
                    alt={selectedProduct.title}
                    className="w-20 h-20 rounded-full mx-auto"
                  />
                )}
                <p><strong>Title:</strong> {selectedProduct.title}</p>
                <p><strong>Seller Email:</strong> {selectedProduct.seller_email}</p>
                <p><strong>Price:</strong> {selectedProduct.price}</p>
                <p><strong>Description:</strong> {selectedProduct.description}</p>

                {/* Product type and seller level badges in modal */}
                <div className="flex flex-wrap gap-2">
                  {selectedProduct.product_type && (
                    <Badge variant="blue" size="sm">
                      {selectedProduct.product_type}
                    </Badge>
                  )}
                  {selectedProduct.seller_level && (
                    <Badge variant="purple" size="sm">
                      Level: {selectedProduct.seller_level}
                    </Badge>
                  )}
                </div>

                <div className="flex items-center space-x-2">
                  <strong>Status:</strong>
                  {isEditingStatus ? (
                    <Select
                      value={tempStatus}
                      onChange={(e) => setTempStatus(e.target.value)}
                      options={statusOptions}
                      placeholder=""
                      className="w-48"
                    />
                  ) : (
                    <Badge variant={statusVariant(selectedProduct.status)} size="md">
                      {selectedProduct.status}
                    </Badge>
                  )}
                  {!isEditingStatus && (
                    <Button
                      variant="ghost"
                      size="sm"
                      icon={<FaPencilAlt />}
                      onClick={handleEditStatus}
                    >
                      Edit
                    </Button>
                  )}
                </div>
              </motion.div>
            </Modal>
          )}
        </AnimatePresence>
      </div>
    </AdminLayout>
  );
};

export default SellerProductManagement;
