import React from 'react';
import { FaSpinner } from 'react-icons/fa';

const Spinner = ({ size = 'md', label = null, className = '' }) => {
  const sizes = {
    sm: 'w-5 h-5 border-2',
    md: 'w-8 h-8 border-2',
    lg: 'w-12 h-12 border-[3px]',
  };
  const textSize = { sm: 'text-xs', md: 'text-sm', lg: 'text-base' };

  return (
    <div className={`flex flex-col items-center justify-center gap-3 ${className}`}>
      <div className={`${sizes[size] || sizes.md} border-brand-100 border-t-brand-500 rounded-full animate-spin`} />
      {label && <span className={`text-gray-500 font-medium ${textSize[size] || textSize.md}`}>{label}</span>}
    </div>
  );
};

export default Spinner;
