import React, { useState, useEffect } from "react";
import apiClient, { API_BASE_URL } from '../config/api';
import AdminLayout from '../components/AdminLayout';
import { FaClipboardList, FaBoxOpen, FaTimes } from 'react-icons/fa';
import {
  PageHeader,
  Card,
  Button,
  Badge,
  Alert,
  Modal,
  Spinner,
  EmptyState,
  Table,
  statusVariant,
} from '../components/ui';

const AssignedOrders = () => {
  const [assignedOrders, setAssignedOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [orderDetails, setOrderDetails] = useState(null);

  useEffect(() => {
    const fetchAssignedOrders = async () => {
      try {
        const response = await apiClient.get("/api/assign/assigned-orders");
        setAssignedOrders(response.data.data || []);
      } catch (err) {
        setError(err.response?.data?.message || "Failed to fetch assigned orders.");
      } finally {
        setLoading(false);
      }
    };
    fetchAssignedOrders();
  }, []);

  const openModal = async (order) => {
    if (!order.payment?.id) return;
    setSelectedOrder(order);
    try {
      const response = await apiClient.get(`/api/payments/orders/${order.payment.id}`);
      setOrderDetails(response.data.data);
    } catch (err) {
      setOrderDetails(null);
    }
  };

  const closeModal = () => {
    setSelectedOrder(null);
    setOrderDetails(null);
  };

  const columns = [
    { header: 'Payment ID', key: 'payment', render: (order) => order.payment?.id || "N/A" },
    { header: 'Shopper Name', key: 'shopper', render: (order) => order.shopper?.full_name || "N/A" },
    { header: 'Shopper Email', key: 'shopperEmail', render: (order) => order.shopper?.email || "N/A" },
    { header: 'Delivery Boy Name', key: 'deliveryBoy', render: (order) => order.deliveryBoy?.full_name || "N/A" },
    { header: 'Delivery Boy Email', key: 'deliveryEmail', render: (order) => order.deliveryBoy?.email || "N/A" },
    {
      header: 'Status',
      key: 'status',
      render: (order) => (
        <Badge variant={statusVariant(order.status)} size="sm">
          {order.status || "Pending"}
        </Badge>
      ),
    },
  ];

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaClipboardList />}
          title="Assigned Orders"
          subtitle="View all orders that have been assigned to shoppers and delivery personnel"
        />

        {loading ? (
          <Card padding="lg">
            <Spinner size="lg" label="Loading assigned orders..." />
          </Card>
        ) : error ? (
          <Alert type="error" title="Error">{error}</Alert>
        ) : assignedOrders.length === 0 ? (
          <Card padding="lg">
            <EmptyState
              icon={<FaClipboardList />}
              title="No assigned orders found"
              description="There are currently no orders that have been assigned."
            />
          </Card>
        ) : (
          <Table
            columns={columns}
            data={assignedOrders}
            onRowClick={openModal}
            emptyMessage="No assigned orders found."
          />
        )}

        {/* Modal: Order Details */}
        <Modal
          open={!!(selectedOrder && orderDetails)}
          onClose={closeModal}
          title="Order Details"
          size="lg"
          footer={
            <div className="flex justify-end">
              <Button variant="danger" onClick={closeModal} icon={<FaTimes />}>
                Close
              </Button>
            </div>
          }
        >
          {orderDetails && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="text-sm text-gray-700"><strong>Order ID:</strong> {orderDetails.order_id}</div>
                <div className="text-sm text-gray-700"><strong>Payment Method:</strong> {orderDetails.payment_method}</div>
                <div className="text-sm text-gray-700">
                  <strong>Payment Status:</strong>{' '}
                  <Badge variant={statusVariant(orderDetails.payment_status)} size="sm">
                    {orderDetails.payment_status}
                  </Badge>
                </div>
                <div className="text-sm text-gray-700"><strong>Total Price:</strong> {orderDetails.total_price} ETB</div>
                <div className="text-sm text-gray-700"><strong>Customer Name:</strong> {orderDetails.customer_name}</div>
                <div className="text-sm text-gray-700"><strong>Customer Email:</strong> {orderDetails.customer_email}</div>
                <div className="text-sm text-gray-700"><strong>Customer Phone:</strong> {orderDetails.customer_phone}</div>
                <div className="text-sm text-gray-700 sm:col-span-2"><strong>Shipping Address:</strong> {orderDetails.shipping_address}</div>
              </div>

              <div>
                <strong className="text-sm text-gray-700">Payment Screenshot:</strong>
                <img
                  src={`${API_BASE_URL}/${orderDetails.payment_screenshot}`}
                  alt="Payment Screenshot"
                  className="w-full max-w-xs h-40 object-cover rounded-lg mt-2 mx-auto border border-gray-200"
                />
              </div>

              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                  <FaBoxOpen /> Cart Items:
                </h3>
                <div className="max-h-60 overflow-y-auto space-y-2">
                  {orderDetails.cart_items ? (
                    JSON.parse(orderDetails.cart_items).map((item) => (
                      <div key={item.id} className="p-3 bg-gray-50 rounded-lg border border-gray-100">
                        <div className="flex flex-col sm:flex-row sm:justify-between">
                          <span className="font-medium text-gray-900">{item.title}</span>
                          <span className="text-sm text-gray-600">Price: {item.price} ETB</span>
                        </div>
                        <div className="flex flex-col sm:flex-row sm:justify-between mt-1">
                          <span className="text-sm text-gray-600">Quantity: {item.quantity}</span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <Alert type="warning">No cart items available</Alert>
                  )}
                </div>
              </div>
            </div>
          )}
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default AssignedOrders;
