"use client"

import { useState, useEffect, useRef, useCallback, useMemo } from "react"
import apiClient from "../config/api"
import { useNavigate } from "react-router-dom"
import {
  FaArrowLeft,
  FaPaperPlane,
  FaSearch,
  FaTimes,
  FaSmile,
  FaPaperclip,
  FaImage,
  FaFile,
  FaDownload,
  FaCheck,
  FaCheckDouble,
  FaCircle,
  FaEllipsisV,
  FaPhone,
  FaVideo,
  FaUser,
  FaComments,
  FaFilter,
  FaInbox,
} from "react-icons/fa"
import EmojiPicker from "emoji-picker-react"

// Utility function to get the token from localStorage
export const getTokenFromLocalStorage = () => {
  return localStorage.getItem("adminToken")
}

const POLL_INTERVAL = 3500
const TYPING_TIMEOUT = 3000

// ─── Date separator helper ─────────────────────────────────────────
const formatDateSeparator = (timestamp) => {
  if (!timestamp) return ""
  const date = new Date(timestamp)
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const msgDate = new Date(date.getFullYear(), date.getMonth(), date.getDate())
  const diffDays = Math.round((today - msgDate) / (1000 * 60 * 60 * 24))

  if (diffDays === 0) return "Today"
  if (diffDays === 1) return "Yesterday"
  if (diffDays < 7) return date.toLocaleDateString("en-US", { weekday: "long" })
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: msgDate.getFullYear() !== now.getFullYear() ? "numeric" : undefined })
}

// ─── Animated typing dots ──────────────────────────────────────────
const TypingDots = () => (
  <div className="flex items-center gap-1 px-4 py-3 bg-white border border-gray-200 rounded-lg rounded-bl-md shadow-sm">
    {[0, 1, 2].map((i) => (
      <span
        key={i}
        className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"
        style={{ animationDelay: `${i * 0.15}s`, animationDuration: "0.6s" }}
      />
    ))
    }
  </div>
)

// ─── Avatar component ──────────────────────────────────────────────
const Avatar = ({ user, size = "md", showStatus = true, status }) => {
  const sizes = {
    sm: "w-9 h-9 text-sm",
    md: "w-11 h-11 text-base",
    lg: "w-12 h-12 text-lg",
  }
  const dotSizes = {
    sm: "w-3 h-3",
    md: "w-3.5 h-3.5",
    lg: "w-4 h-4",
  }
  const isOnline = status === "online"

  return (
    <div className="relative flex-shrink-0">
      {user?.avatar ? (
        <img
          src={user.avatar}
          alt={user.name}
          className={`${sizes[size]} rounded-full object-cover ring-2 ring-white shadow-sm`}
        />
      ) : (
        <div className={`${sizes[size]} flex items-center justify-center bg-brand-500 text-white font-bold rounded-full ring-2 ring-white shadow-sm`}>
          {user?.name?.[0]?.toUpperCase() || "?"}
        </div>
      )}
      {showStatus && (
        <span
          className={`absolute -bottom-0.5 -right-0.5 ${dotSizes[size]} rounded-full ring-2 ring-white ${
            isOnline ? "bg-green-500" : "bg-gray-400"
          }`}
        />
      )}
    </div>
  )
}

// ─── Role badge ────────────────────────────────────────────────────
const RoleBadge = ({ role }) => {
  const styles = {
    delivery: "bg-amber-100 text-amber-700",
    shopper: "bg-purple-100 text-purple-700",
    seller: "bg-brand-50 text-brand-600",
  }
  return (
    <span className={`text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full ${styles[role] || "bg-gray-100 text-gray-600"}`}>
      {role}
    </span>
  )
}

const Chat = () => {
  const [users, setUsers] = useState([])
  const [filteredUsers, setFilteredUsers] = useState([])
  const [selectedUser, setSelectedUser] = useState(null)
  const [messages, setMessages] = useState([])
  const [newMessage, setNewMessage] = useState("")
  const [adminId, setAdminId] = useState(null)
  const [sending, setSending] = useState(false)
  const [error, setError] = useState("")
  const [userStatus, setUserStatus] = useState({})
  const [searchQuery, setSearchQuery] = useState("")
  const [roleFilter, setRoleFilter] = useState("all")
  const [showEmojiPicker, setShowEmojiPicker] = useState(false)
  const [showAttachments, setShowAttachments] = useState(false)
  const [typingUsers, setTypingUsers] = useState(new Set())
  const [messageSearch, setMessageSearch] = useState("")
  const [showMessageSearch, setShowMessageSearch] = useState(false)
  const [unreadCounts, setUnreadCounts] = useState({})
  const [lastSeen, setLastSeen] = useState({})
  const [isOnline, setIsOnline] = useState(navigator.onLine)
  const [showSidebarMobile, setShowSidebarMobile] = useState(true)
  const [sidebarOpen, setSidebarOpen] = useState(false)

  const navigate = useNavigate()
  const messagesEndRef = useRef(null)
  const messagesContainerRef = useRef(null)
  const pollingIntervalRef = useRef(null)
  const fileInputRef = useRef(null)
  const imageInputRef = useRef(null)
  const typingTimeoutRef = useRef(null)
  const messageInputRef = useRef(null)

  // ─── Authentication ──────────────────────────────────────────────
  useEffect(() => {
    const token = getTokenFromLocalStorage()
    if (token) {
      try {
        const decodedToken = JSON.parse(atob(token.split(".")[1]))
        setAdminId(decodedToken.id)
      } catch {
        navigate("/login")
      }
    } else {
      navigate("/login")
    }
  }, [navigate])

  // ─── Online/offline detection ────────────────────────────────────
  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)
    window.addEventListener("online", handleOnline)
    window.addEventListener("offline", handleOffline)
    return () => {
      window.removeEventListener("online", handleOnline)
      window.removeEventListener("offline", handleOffline)
    }
  }, [])

  // ─── Fetch users ─────────────────────────────────────────────────
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const [deliveryResponse, shoppersResponse] = await Promise.all([
          apiClient.get("/api/deliveryboy/"),
          apiClient.get("/api/shoppers/"),
        ])

        const deliveryBoys = (deliveryResponse.data.deliveryBoys || []).map((user) => ({
          id: user.id,
          name: user.full_name,
          email: user.email,
          role: "delivery",
          avatar: user.avatar || null,
          lastMessage: "",
          lastMessageTime: null,
        }))

        const shoppers = (shoppersResponse.data.shoppers || []).map((user) => ({
          id: user.id,
          name: user.full_name,
          email: user.email,
          role: "shopper",
          avatar: user.avatar || null,
          lastMessage: "",
          lastMessageTime: null,
        }))

        const allUsers = [...deliveryBoys, ...shoppers]
        setUsers(allUsers)

        const status = {}
        const lastSeenData = {}
        const unreadData = {}
        allUsers.forEach((user) => {
          const online = Math.random() > 0.3
          status[user.id] = online ? "online" : "offline"
          if (!online) {
            lastSeenData[user.id] = new Date(Date.now() - (Math.floor(Math.random() * 120) + 1) * 60000)
          }
          unreadData[user.id] = Math.floor(Math.random() * 5)
        })
        setUserStatus(status)
        setLastSeen(lastSeenData)
        setUnreadCounts(unreadData)
      } catch (err) {
        setError("Failed to fetch users.")
        console.error("Fetch users error:", err)
      }
    }
    fetchUsers()
  }, [])

  // ─── Filter users by search + role ───────────────────────────────
  useEffect(() => {
    let filtered = users
    if (searchQuery.trim()) {
      filtered = filtered.filter(
        (u) =>
          u.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
          u.email.toLowerCase().includes(searchQuery.toLowerCase()),
      )
    }
    if (roleFilter !== "all") {
      filtered = filtered.filter((u) => u.role === roleFilter)
    }
    setFilteredUsers(filtered)
  }, [searchQuery, roleFilter, users])

  // ─── Fetch chat history ──────────────────────────────────────────
  const fetchChatHistory = useCallback(async () => {
    if (selectedUser && adminId) {
      try {
        const response = await apiClient.get(
          `/api/chat/history/${adminId}/admin/${selectedUser.id}/${selectedUser.role}`,
        )
        if (Array.isArray(response.data.data)) {
          const messagesWithStatus = response.data.data.map((msg) => ({
            ...msg,
            status: msg.sender_id === adminId ? "delivered" : "received",
          }))
          setMessages(messagesWithStatus)
          setUnreadCounts((prev) => ({ ...prev, [selectedUser.id]: 0 }))
        } else {
          setMessages([])
        }
        setError("")
      } catch (err) {
        setError("Failed to fetch chat history.")
        setMessages([])
      }
    }
  }, [selectedUser, adminId])

  useEffect(() => {
    if (selectedUser && adminId && isOnline) {
      fetchChatHistory()
      pollingIntervalRef.current = setInterval(fetchChatHistory, POLL_INTERVAL)
    }
    return () => {
      if (pollingIntervalRef.current) clearInterval(pollingIntervalRef.current)
    }
  }, [selectedUser, adminId, isOnline, fetchChatHistory])

  // ─── Auto-scroll ─────────────────────────────────────────────────
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" })
  }, [messages])

  // ─── Send message ────────────────────────────────────────────────
  const sendMessage = async (messageText = newMessage, attachments = null) => {
    if (!messageText.trim() && !attachments) return
    if (!adminId || !selectedUser?.id || !selectedUser?.role) return

    const messagePayload = {
      sender_id: adminId,
      receiver_id: selectedUser.id,
      sender_role: "admin",
      receiver_role: selectedUser.role,
      message: messageText,
      attachments: attachments,
      timestamp: new Date().toISOString(),
    }

    const tempMessage = {
      ...messagePayload,
      id: `temp-${Date.now()}`,
      created_at: new Date().toISOString(),
      status: "sending",
    }

    setMessages((prev) => [...prev, tempMessage])
    setNewMessage("")
    setShowEmojiPicker(false)
    setShowAttachments(false)

    try {
      setSending(true)
      const response = await apiClient.post("/api/chat/send", messagePayload)
      setMessages((prev) =>
        prev.map((msg) => (msg.id === tempMessage.id ? { ...response.data, status: "sent" } : msg)),
      )
      setTimeout(() => {
        setMessages((prev) =>
          prev.map((msg) => (msg.id === response.data.id ? { ...msg, status: "delivered" } : msg)),
        )
      }, 1000)
    } catch {
      setMessages((prev) => prev.filter((msg) => msg.id !== tempMessage.id))
      setNewMessage(messageText)
      setError("Failed to send message.")
    } finally {
      setSending(false)
    }
  }

  const onEmojiClick = (emojiObject) => {
    setNewMessage((prev) => prev + emojiObject.emoji)
    messageInputRef.current?.focus()
  }

  const handleFileUpload = (event, type) => {
    const file = event.target.files[0]
    if (file) {
      const fileData = { name: file.name, size: file.size, type: file.type, url: URL.createObjectURL(file) }
      sendMessage(`📎 ${file.name}`, [fileData])
    }
  }

  const handleInputChange = (e) => {
    setNewMessage(e.target.value)
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current)
    typingTimeoutRef.current = setTimeout(() => {}, TYPING_TIMEOUT)
  }

  const handleInputKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      sendMessage()
    }
  }

  // ─── Time / date helpers ─────────────────────────────────────────
  const formatTime = (timestamp) => {
    if (!timestamp) return ""
    const date = new Date(timestamp)
    return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
  }

  const formatLastSeen = (timestamp) => {
    if (!timestamp) return ""
    const diff = new Date() - timestamp
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(minutes / 60)
    const days = Math.floor(hours / 24)
    if (minutes < 1) return "just now"
    if (minutes < 60) return `${minutes}m ago`
    if (hours < 24) return `${hours}h ago`
    return `${days}d ago`
  }

  // ─── Message status icon ─────────────────────────────────────────
  const getMessageStatusIcon = (status) => {
    switch (status) {
      case "sending": return <div className="w-3 h-3 border border-gray-300 border-t-brand-500 rounded-full animate-spin" />
      case "sent": return <FaCheck className="text-gray-400 text-[10px]" />
      case "delivered": return <FaCheckDouble className="text-gray-400 text-[10px]" />
      case "read": return <FaCheckDouble className="text-brand-500 text-[10px]" />
      default: return null
    }
  }

  // ─── Filtered messages ───────────────────────────────────────────
  const filteredMessages = useMemo(() => {
    return messageSearch.trim()
      ? messages.filter((msg) => msg.message.toLowerCase().includes(messageSearch.toLowerCase()))
      : messages
  }, [messageSearch, messages])

  // ─── Group messages by date ──────────────────────────────────────
  const groupedMessages = useMemo(() => {
    const groups = []
    let currentDate = null
    filteredMessages.forEach((msg) => {
      const dateKey = formatDateSeparator(msg.created_at)
      if (dateKey !== currentDate) {
        groups.push({ type: "separator", date: dateKey, id: `sep-${dateKey}` })
        currentDate = dateKey
      }
      groups.push({ type: "message", msg })
    })
    return groups
  }, [filteredMessages])

  // ─── Handle user selection ───────────────────────────────────────
  const handleSelectUser = (user) => {
    setSelectedUser(user)
    setShowSidebarMobile(false)
    setSidebarOpen(false)
  }

  // ─── Total unread count ──────────────────────────────────────────
  const totalUnread = useMemo(() => Object.values(unreadCounts).reduce((a, b) => a + b, 0), [unreadCounts])

  // ═══════════════════════════════════════════════════════════════════════════
  //  RENDER
  // ═══════════════════════════════════════════════════════════════════════════
  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden">
      {/* ─── Mobile sidebar toggle button ─────────────────────────── */}
      {selectedUser && (
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="lg:hidden fixed top-4 left-4 z-50 w-10 h-10 bg-white rounded-lg shadow-sm flex items-center justify-center text-gray-600 hover:bg-gray-50 transition-colors"
        >
          {sidebarOpen ? <FaTimes /> : <FaComments />}
          {totalUnread > 0 && !sidebarOpen && (
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-brand-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
              {totalUnread > 9 ? "9+" : totalUnread}
            </span>
          )}
        </button>
      )}

      {/* ─── Sidebar: Conversation List ────────────────────────────── */}
      <aside
        className={`
          ${selectedUser && !sidebarOpen ? "hidden lg:flex" : "flex"}
          flex-col w-full lg:w-[360px] xl:w-[400px] bg-white border-r border-gray-200 h-full
          ${sidebarOpen ? "fixed lg:relative inset-0 z-40 lg:z-auto" : ""}
        `}
      >
        {/* Sidebar Header */}
        <div className="bg-brand-600 text-white px-5 py-4 shadow-sm flex-shrink-0">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg bg-white/20 backdrop-blur-sm flex items-center justify-center">
                <FaComments className="text-lg" />
              </div>
              <div>
                <h2 className="text-lg font-bold leading-tight">Messages</h2>
                <p className="text-[11px] text-brand-100">{users.length} contacts</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {!isOnline && (
                <span className="flex items-center gap-1 text-[10px] bg-red-500 px-2 py-1 rounded-full font-semibold">
                  <FaCircle className="text-[8px]" /> Offline
                </span>
              )}
              {totalUnread > 0 && (
                <span className="bg-white/20 backdrop-blur-sm text-white text-xs font-bold rounded-full px-2.5 py-1 min-w-[24px] text-center">
                  {totalUnread}
                </span>
              )}
            </div>
          </div>

          {/* Search */}
          <div className="relative">
            <FaSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-brand-300 text-sm" />
            <input
              type="text"
              placeholder="Search conversations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-10 py-2.5 bg-white/15 backdrop-blur-md border border-white/20 rounded-lg text-white text-sm placeholder-brand-200 focus:outline-none focus:bg-white/25 focus:ring-2 focus:ring-white/40 transition-all"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery("")}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-brand-300 hover:text-white"
              >
                <FaTimes className="text-sm" />
              </button>
            )}
          </div>
        </div>

        {/* Role filter tabs */}
        <div className="flex items-center gap-1 px-3 py-2 border-b border-gray-100 bg-gray-50/50 flex-shrink-0">
          <FaFilter className="text-gray-400 text-xs mr-1" />
          {["all", "delivery", "shopper"].map((r) => (
            <button
              key={r}
              onClick={() => setRoleFilter(r)}
              className={`px-3 py-1.5 rounded-md text-xs font-semibold transition-all capitalize ${
                roleFilter === r
                  ? "bg-brand-500 text-white shadow-sm"
                  : "text-gray-500 hover:bg-gray-200"
              }`}
            >
              {r === "all" ? "All" : r === "delivery" ? "Delivery" : "Shoppers"}
            </button>
          ))}
        </div>

        {/* User list */}
        <div className="flex-1 overflow-y-auto chat-scroll">
          {error && (
            <div className="mx-4 mt-3 p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-xs flex items-start gap-2">
              <FaTimes className="mt-0.5 flex-shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {filteredUsers.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-gray-400">
              <FaInbox className="text-5xl mb-3 opacity-40" />
              <p className="text-sm font-medium">No conversations found</p>
              <p className="text-xs mt-1">Try a different search or filter</p>
            </div>
          ) : (
            filteredUsers.map((user) => {
              const isActive = selectedUser?.id === user.id
              const isUserOnline = userStatus[user.id] === "online"
              const unread = unreadCounts[user.id] || 0

              return (
                <button
                  key={user.id}
                  onClick={() => handleSelectUser(user)}
                  className={`w-full flex items-center gap-3 px-4 py-3.5 border-b border-gray-50 transition-all text-left ${
                    isActive
                      ? "bg-brand-50 border-l-4 border-l-brand-500"
                      : "hover:bg-gray-50 border-l-4 border-l-transparent"
                  }`}
                >
                  <Avatar user={user} size="md" showStatus={true} status={userStatus[user.id]} />

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <h4 className="text-sm font-semibold text-gray-900 truncate">{user.name}</h4>
                      {unread > 0 && (
                        <span className="bg-brand-500 text-white text-[10px] font-bold rounded-full min-w-[20px] h-5 px-1.5 flex items-center justify-center flex-shrink-0">
                          {unread}
                        </span>
                      )}
                    </div>

                    <div className="flex items-center gap-2 mt-0.5">
                      <RoleBadge role={user.role} />
                      <span className={`text-[11px] ${isUserOnline ? "text-green-600 font-medium" : "text-gray-400"}`}>
                        {isUserOnline ? "Online" : `last seen ${formatLastSeen(lastSeen[user.id])}`}
                      </span>
                    </div>

                    <p className="text-xs text-gray-400 truncate mt-0.5">{user.email}</p>
                  </div>
                </button>
              )
            })
          )}
        </div>
      </aside>

      {/* ─── Chat Area ─────────────────────────────────────────────── */}
      {selectedUser ? (
        <section className="flex flex-col flex-1 h-full bg-white relative">
          {/* Chat Header */}
          <div className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between flex-shrink-0 shadow-sm z-10">
            <div className="flex items-center gap-3 min-w-0 flex-1">
              <button
                onClick={() => { setSelectedUser(null); setSidebarOpen(false) }}
                className="lg:hidden p-2 -ml-2 text-gray-500 hover:bg-gray-100 rounded-md transition-colors flex-shrink-0"
              >
                <FaArrowLeft />
              </button>
              <Avatar user={selectedUser} size="md" showStatus={true} status={userStatus[selectedUser.id]} />
              <div className="min-w-0">
                <h3 className="text-sm font-bold text-gray-900 truncate">{selectedUser.name}</h3>
                <div className="flex items-center gap-2 mt-0.5">
                  <RoleBadge role={selectedUser.role} />
                  {typingUsers.has(selectedUser.id) ? (
                    <span className="text-[11px] text-brand-500 font-medium">typing...</span>
                  ) : userStatus[selectedUser.id] === "online" ? (
                    <span className="text-[11px] text-green-600 font-medium">Online</span>
                  ) : (
                    <span className="text-[11px] text-gray-400">
                      last seen {formatLastSeen(lastSeen[selectedUser.id])}
                    </span>
                  )}
                </div>
              </div>
            </div>

            <div className="flex items-center gap-1 flex-shrink-0">
              <button className="w-9 h-9 flex items-center justify-center text-gray-400 hover:text-brand-500 hover:bg-brand-50 rounded-md transition-colors">
                <FaPhone className="text-sm" />
              </button>
              <button className="w-9 h-9 flex items-center justify-center text-gray-400 hover:text-brand-500 hover:bg-brand-50 rounded-md transition-colors">
                <FaVideo className="text-sm" />
              </button>
              <button
                onClick={() => setShowMessageSearch(!showMessageSearch)}
                className={`w-9 h-9 flex items-center justify-center rounded-md transition-colors ${
                  showMessageSearch ? "text-brand-500 bg-brand-50" : "text-gray-400 hover:text-brand-500 hover:bg-brand-50"
                }`}
              >
                <FaSearch className="text-sm" />
              </button>
              <button className="w-9 h-9 flex items-center justify-center text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-md transition-colors">
                <FaEllipsisV className="text-sm" />
              </button>
            </div>
          </div>

          {/* Message search bar */}
          {showMessageSearch && (
            <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-200 flex items-center gap-2">
              <FaSearch className="text-gray-400 text-sm flex-shrink-0" />
              <input
                type="text"
                placeholder="Search in this conversation..."
                value={messageSearch}
                onChange={(e) => setMessageSearch(e.target.value)}
                className="flex-1 text-sm bg-transparent border-none outline-none placeholder-gray-400"
                autoFocus
              />
              {messageSearch && (
                <button onClick={() => setMessageSearch("")} className="text-gray-400 hover:text-gray-600">
                  <FaTimes className="text-sm" />
                </button>
              )}
              <button
                onClick={() => { setShowMessageSearch(false); setMessageSearch("") }}
                className="text-xs text-gray-500 hover:text-gray-700 font-medium px-2 py-1 rounded-md hover:bg-gray-200"
              >
                Cancel
              </button>
            </div>
          )}

          {/* Messages area */}
          <div
            ref={messagesContainerRef}
            className="flex-1 overflow-y-auto px-4 sm:px-6 py-4 bg-[#eef2f7] chat-scroll"
          >
            {filteredMessages.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-400">
                <div className="w-20 h-20 rounded-full bg-white shadow-sm flex items-center justify-center mb-4">
                  <FaComments className="text-3xl text-brand-300" />
                </div>
                <p className="text-base font-semibold text-gray-600">No messages yet</p>
                <p className="text-sm mt-1">Send a message to start the conversation</p>
              </div>
            ) : (
              <div className="space-y-1 max-w-4xl mx-auto">
                {groupedMessages.map((item) => {
                  if (item.type === "separator") {
                    return (
                      <div key={item.id} className="flex items-center justify-center my-4">
                        <span className="text-[11px] font-semibold text-gray-500 bg-white/80 backdrop-blur-sm px-3 py-1 rounded-full shadow-sm">
                          {item.date}
                        </span>
                      </div>
                    )
                  }

                  const msg = item.msg
                  const isSender = String(msg.sender_id) === String(adminId)
                  const idx = filteredMessages.indexOf(msg)
                  const prevMsg = filteredMessages[idx - 1]
                  const nextMsg = filteredMessages[idx + 1]
                  const isConsecutive = prevMsg && prevMsg.sender_id === msg.sender_id
                  const isLastInGroup = !nextMsg || nextMsg.sender_id !== msg.sender_id

                  return (
                    <div
                      key={msg.id}
                      className={`flex ${isSender ? "justify-end" : "justify-start"} ${isConsecutive ? "mt-0.5" : "mt-3"}`}
                    >
                      <div
                        className={`flex items-end gap-2 max-w-[80%] sm:max-w-[65%] md:max-w-[55%] ${
                          isSender ? "flex-row-reverse" : "flex-row"
                        }`}
                      >
                        {/* Avatar for received messages */}
                        <div className="w-7 h-7 flex-shrink-0">
                          {!isSender && isLastInGroup && <Avatar user={selectedUser} size="sm" showStatus={false} />}
                        </div>

                        {/* Message bubble */}
                        <div className={`flex flex-col ${isSender ? "items-end" : "items-start"}`}>
                          <div
                            className={`
                              relative px-3.5 py-2.5 shadow-sm max-w-full break-words text-sm leading-relaxed
                              ${
                                isSender
                                  ? "bg-brand-500 text-white rounded-lg rounded-br-md"
                                  : "bg-white border border-gray-100 text-gray-800 rounded-lg rounded-bl-md"
                              }
                              ${isConsecutive ? (isSender ? "rounded-br-md" : "rounded-bl-md") : ""}
                            `}
                          >
                            <p className="whitespace-pre-line">{msg.message}</p>

                            {/* Attachments */}
                            {msg.attachments && msg.attachments.length > 0 && (
                              <div className="mt-2 space-y-1.5">
                                {msg.attachments.map((attachment, i) => (
                                  <div
                                    key={i}
                                    className={`flex items-center gap-2 p-2 rounded-md ${
                                      isSender ? "bg-white/20" : "bg-gray-50 border border-gray-200"
                                    }`}
                                  >
                                    {attachment.type?.startsWith("image/") ? (
                                      <FaImage className="text-sm flex-shrink-0" />
                                    ) : (
                                      <FaFile className="text-sm flex-shrink-0" />
                                    )}
                                    <span className="text-xs truncate flex-1">{attachment.name}</span>
                                    <button className="text-xs hover:opacity-70 transition-opacity">
                                      <FaDownload />
                                    </button>
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>

                          {/* Time + status */}
                          {isLastInGroup && (
                            <div
                              className={`flex items-center gap-1 mt-1 text-[10px] text-gray-400 ${
                                isSender ? "flex-row-reverse" : "flex-row"
                              }`}
                            >
                              <span>{formatTime(msg.created_at)}</span>
                              {isSender && getMessageStatusIcon(msg.status)}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )
                })}

                {/* Typing indicator */}
                {typingUsers.has(selectedUser.id) && (
                  <div className="flex justify-start mt-2">
                    <div className="flex items-end gap-2">
                      <div className="w-7 h-7 flex-shrink-0">
                        <Avatar user={selectedUser} size="sm" showStatus={false} />
                      </div>
                      <TypingDots />
                    </div>
                  </div>
                )}

                <div ref={messagesEndRef} />
              </div>
            )}
          </div>

          {/* Message input bar */}
          <div className="bg-white border-t border-gray-200 px-3 sm:px-4 py-3 flex-shrink-0 relative">
            {/* Emoji picker */}
            {showEmojiPicker && (
              <div className="absolute bottom-16 right-2 sm:right-4 z-50 shadow-sm rounded-lg overflow-hidden">
                <EmojiPicker
                  onEmojiClick={onEmojiClick}
                  width={300}
                  height={360}
                  previewConfig={{ showPreview: false }}
                />
              </div>
            )}

            {/* Attachment menu */}
            {showAttachments && (
              <div className="absolute bottom-16 left-2 sm:left-4 bg-white rounded-lg shadow-sm border border-gray-100 p-2 z-50 w-44">
                <button
                  onClick={() => imageInputRef.current?.click()}
                  className="flex items-center gap-3 w-full p-2.5 hover:bg-brand-50 rounded-lg text-left transition-colors"
                >
                  <div className="w-8 h-8 rounded-md bg-green-100 text-green-600 flex items-center justify-center">
                    <FaImage className="text-sm" />
                  </div>
                  <span className="text-sm font-medium text-gray-700">Photo</span>
                </button>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="flex items-center gap-3 w-full p-2.5 hover:bg-brand-50 rounded-lg text-left transition-colors"
                >
                  <div className="w-8 h-8 rounded-md bg-brand-100 text-brand-600 flex items-center justify-center">
                    <FaFile className="text-sm" />
                  </div>
                  <span className="text-sm font-medium text-gray-700">Document</span>
                </button>
              </div>
            )}

            <form
              className="flex items-end gap-2"
              onSubmit={(e) => { e.preventDefault(); sendMessage() }}
            >
              {/* Attachment toggle */}
              <button
                type="button"
                onClick={() => { setShowAttachments(!showAttachments); setShowEmojiPicker(false) }}
                className={`w-10 h-10 flex items-center justify-center rounded-lg transition-colors flex-shrink-0 ${
                  showAttachments ? "text-brand-500 bg-brand-50" : "text-gray-400 hover:text-brand-500 hover:bg-brand-50"
                }`}
              >
                <FaPaperclip className="text-lg" />
              </button>

              {/* Text input */}
              <div className="flex-1 relative bg-gray-100 rounded-lg border border-transparent focus-within:border-brand-400 focus-within:bg-white transition-all">
                <textarea
                  ref={messageInputRef}
                  placeholder="Type a message..."
                  value={newMessage}
                  onChange={handleInputChange}
                  onKeyDown={handleInputKeyDown}
                  className="w-full px-4 py-3 pr-12 bg-transparent border-none outline-none resize-none max-h-32 min-h-[44px] text-sm rounded-lg placeholder-gray-400"
                  rows={1}
                  style={{ height: "auto" }}
                  onInput={(e) => {
                    e.target.style.height = "auto"
                    e.target.style.height = Math.min(e.target.scrollHeight, 128) + "px"
                  }}
                />
                <button
                  type="button"
                  onClick={() => { setShowEmojiPicker(!showEmojiPicker); setShowAttachments(false) }}
                  className={`absolute right-3 bottom-3 transition-colors ${
                    showEmojiPicker ? "text-brand-500" : "text-gray-400 hover:text-brand-500"
                  }`}
                >
                  <FaSmile className="text-lg" />
                </button>
              </div>

              {/* Send button */}
              <button
                type="submit"
                disabled={sending || !newMessage.trim()}
                className="w-10 h-10 flex items-center justify-center bg-brand-500 text-white rounded-lg shadow-sm transition-all disabled:opacity-40 disabled:cursor-not-allowed hover:bg-brand-600 hover:scale-105 active:scale-95 flex-shrink-0"
              >
                {sending ? (
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : (
                  <FaPaperPlane className="text-sm" />
                )}
              </button>
            </form>

            {/* Hidden file inputs */}
            <input
              ref={fileInputRef}
              type="file"
              className="hidden"
              onChange={(e) => handleFileUpload(e, "file")}
              accept=".pdf,.doc,.docx,.txt,.zip"
            />
            <input
              ref={imageInputRef}
              type="file"
              className="hidden"
              onChange={(e) => handleFileUpload(e, "image")}
              accept="image/*"
            />
          </div>
        </section>
      ) : (
        /* ─── Empty state (desktop) ──────────────────────────────── */
        <section className="hidden lg:flex flex-col flex-1 h-full bg-gray-50 items-center justify-center">
          <div className="text-center max-w-md px-8">
            <div className="w-24 h-24 mx-auto rounded-lg bg-brand-50 flex items-center justify-center mb-6 shadow-sm">
              <FaComments className="text-4xl text-brand-500" />
            </div>
            <h2 className="text-2xl font-bold text-gray-800 mb-2">Welcome to Admin Chat</h2>
            <p className="text-gray-500 text-sm leading-relaxed">
              Select a conversation from the sidebar to start messaging with delivery boys and shoppers.
              You can search, filter by role, and send attachments.
            </p>
            <div className="flex items-center justify-center gap-4 mt-6 text-xs text-gray-400">
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 bg-green-500 rounded-full" />
                Online
              </div>
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 bg-gray-400 rounded-full" />
                Offline
              </div>
              <div className="flex items-center gap-1.5">
                <FaCircle className="text-[6px] text-brand-500" />
                Unread
              </div>
            </div>
          </div>
        </section>
      )}

      {/* ─── Click-outside overlay for popovers ────────────────────── */}
      {(showEmojiPicker || showAttachments) && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => { setShowEmojiPicker(false); setShowAttachments(false) }}
        />
      )}

      {/* ─── Mobile sidebar backdrop ──────────────────────────────── */}
      {sidebarOpen && (
        <div
          className="lg:hidden fixed inset-0 bg-black/30 z-30"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* ─── Custom scrollbar styles ──────────────────────────────── */}
      <style>{`
        .chat-scroll::-webkit-scrollbar { width: 5px; }
        .chat-scroll::-webkit-scrollbar-track { background: transparent; }
        .chat-scroll::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.12); border-radius: 10px; }
        .chat-scroll::-webkit-scrollbar-thumb:hover { background: rgba(0,0,0,0.2); }
      `}</style>
    </div>
  )
}

export default Chat
