"use client"

import { useState, useEffect } from "react"
import { FaBox, FaPlus, FaTimes, FaImage } from "react-icons/fa"
import apiClient from '../config/api'
import AdminLayout from '../components/AdminLayout'
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  FileInput,
  TextArea,
  Alert,
} from '../components/ui'

const AddProduct = () => {
  const [productData, setProductData] = useState({
    title: "",
    brand: "",
    price: "",
    description: "",
    catItems: "",
    subcat: "",
    productfor: "for_user",
    stock: "in_stock",
    location_name: "Addis Ababa",
    location_radius: 10,
    product_type: "retail",
    seller_level: "reseller",
    origin_country: "",
    destination_country: "",
  })

  const [generalImages, setGeneralImages] = useState([])
  const [generalImagePreviews, setGeneralImagePreviews] = useState([])
  const [colorOptions, setColorOptions] = useState([])
  const [variations, setVariations] = useState([])
  const [categories, setCategories] = useState([])
  const [subcategories, setSubcategories] = useState([])
  const [loading, setLoading] = useState(false)
  const [activeTab, setActiveTab] = useState("basic")
  const [error, setError] = useState("")
  const [success, setSuccess] = useState("")

  // Auto-dismiss success message
  useEffect(() => {
    if (success) {
      const t = setTimeout(() => setSuccess(""), 5000)
      return () => clearTimeout(t)
    }
  }, [success])

  const stockOptions = [
    { value: "in_stock", label: "In Stock" },
    { value: "out_of_stock", label: "Out of Stock" },
    { value: "limited_stock", label: "Limited Stock" },
  ]
  const productfor = [
    { value: "for_user", label: "For User" },
    { value: "for_seller", label: "For Seller" },
  ]

  const productTypeOptions = [
    { value: "retail", label: "Retail" },
    { value: "wholesale", label: "Wholesale" },
    { value: "import", label: "Import" },
    { value: "export", label: "Export" },
  ]

  const sellerLevelOptions = [
    { value: "importer", label: "Importer" },
    { value: "exporter", label: "Exporter" },
    { value: "reseller", label: "Reseller" },
  ]

  const variationTypes = [
    { value: "size", label: "Size", options: ["XS", "S", "M", "L", "XL", "XXL", "One Size"] },
    { value: "weight", label: "Weight", options: ["0.5 lb", "1 lb", "2 lb", "5 lb", "10 lb", "1 kg", "2 kg", "5 kg"] },
    {
      value: "level",
      label: "Level",
      options: ["Level 1", "Level 2", "Level 3", "Level 4", "Level 5", "Basic", "Premium", "Pro"],
    },
    { value: "volume", label: "Volume", options: ["250ml", "500ml", "750ml", "1L", "2L", "500g", "1kg"] },
    {
      value: "quantity",
      label: "Quantity",
      options: ["Single", "Pack of 6", "Pack of 12", "Pack of 24", "Dozen", "Half Dozen"],
    },
    { value: "custom", label: "Custom", options: [] },
  ]

  const tabs = [
    { id: "basic", label: "Basic Info" },
    { id: "images", label: "Images" },
    { id: "colors", label: "Colors" },
    { id: "variations", label: "Variations" },
  ]

  // Fetch categories and subcategories
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [categoriesRes, subcategoriesRes] = await Promise.all([
          apiClient.get('/api/catitem'),
          apiClient.get('/api/subcat'),
        ])
        setCategories(categoriesRes.data)
        setSubcategories(subcategoriesRes.data)
      } catch (error) {
        console.error("Error fetching data:", error)
        setError("Failed to load categories")
      }
    }
    fetchData()
  }, [])

  const handleChange = (name, value) => {
    setProductData({ ...productData, [name]: value })
  }

  const handleGeneralImageChange = (e) => {
    const files = Array.from(e.target.files || [])
    setGeneralImages(files)

    // Create previews
    const previewUrls = files.map((file) => URL.createObjectURL(file))
    setGeneralImagePreviews(previewUrls)
  }

  const addColorOption = () => {
    setColorOptions([...colorOptions, { color_name: "", images: [], image_count: 0 }])
  }

  const updateColorOption = (index, field, value) => {
    const updated = [...colorOptions]
    updated[index] = { ...updated[index], [field]: value }
    setColorOptions(updated)
  }

  const removeColorOption = (index) => {
    setColorOptions(colorOptions.filter((_, i) => i !== index))
  }

  const handleColorImageChange = (colorIndex, e) => {
    const files = Array.from(e.target.files || [])
    updateColorOption(colorIndex, "images", files)
    updateColorOption(colorIndex, "image_count", files.length)
  }

  const addVariation = () => {
    setVariations([
      ...variations,
      {
        variation_type: "size",
        variation_value: "",
        color: "",
        price: 0,
        stock: "in_stock",
      },
    ])
  }

  const updateVariation = (index, field, value) => {
    const updated = [...variations]
    updated[index] = { ...updated[index], [field]: value }

    // Reset variation_value when variation_type changes
    if (field === "variation_type") {
      updated[index].variation_value = ""
    }

    setVariations(updated)
  }

  const removeVariation = (index) => {
    setVariations(variations.filter((_, i) => i !== index))
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError("")
    setSuccess("")

    if (!productData.title || !productData.price || !productData.description) {
      setError("Please fill in all required fields")
      return
    }

    const formData = new FormData()

    // Add basic product data
    Object.keys(productData).forEach((key) => {
      formData.append(key, productData[key].toString())
    })

    const processedVariations = variations.map((variation) => ({
      [variation.variation_type]: variation.variation_value,
      color: variation.color,
      price: variation.price,
      stock: variation.stock,
    }))
    formData.append("variations", JSON.stringify(processedVariations))

    // Add color options as JSON string (without the actual files)
    const colorOptionsForBackend = colorOptions.map((option) => ({
      color_name: option.color_name,
      image_count: option.image_count,
    }))
    formData.append("color_options", JSON.stringify(colorOptionsForBackend))

    // Add general image count
    formData.append("general_image_count", generalImages.length.toString())

    // Add all images in the correct order: general images first, then color images
    generalImages.forEach((image) => {
      formData.append("images", image)
    })

    colorOptions.forEach((colorOption) => {
      colorOption.images.forEach((image) => {
        formData.append("images", image)
      })
    })

    setLoading(true)
    try {
      await apiClient.post('/api/prod', formData, {
        headers: { "Content-Type": "multipart/form-data" },
      })

      setSuccess("Product added successfully!")

      // Reset form
      setProductData({
        title: "",
        brand: "",
        price: "",
        description: "",
        catItems: "",
        subcat: "",
        productfor: "for_user",
        stock: "in_stock",
        location_name: "Addis Ababa",
        location_radius: 10,
        product_type: "retail",
        seller_level: "reseller",
        origin_country: "",
        destination_country: "",
      })
      setGeneralImages([])
      setGeneralImagePreviews([])
      setColorOptions([])
      setVariations([])
    } catch (error) {
      console.error(error)
      const errorMessage = error.response?.data?.message || "Error adding product. Please try again."
      setError(errorMessage)
    } finally {
      setLoading(false)
    }
  }

  return (
    <AdminLayout>
      <div className="max-w-3xl mx-auto">
        <PageHeader
          icon={<FaBox />}
          title="Add New Product"
          subtitle="Create a comprehensive product listing with variations and images"
        />

        {error && (
          <div className="mb-5">
            <Alert type="error" onClose={() => setError("")}>
              {error}
            </Alert>
          </div>
        )}

        {success && (
          <div className="mb-5">
            <Alert type="success" onClose={() => setSuccess("")}>
              {success}
            </Alert>
          </div>
        )}

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Tab Navigation */}
            <div className="flex gap-2 p-1 bg-gray-50 rounded-lg overflow-x-auto">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActiveTab(tab.id)}
                  className={`px-4 sm:px-6 py-2.5 font-medium text-sm rounded-lg transition-all duration-200 cursor-pointer whitespace-nowrap ${
                    activeTab === tab.id
                      ? "bg-brand-500 text-white shadow-sm"
                      : "bg-white text-gray-700 border border-gray-200 hover:bg-gray-50"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Basic Info Tab */}
            {activeTab === "basic" && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  <Input
                    label="Product Title"
                    type="text"
                    value={productData.title}
                    onChange={(e) => handleChange("title", e.target.value)}
                    placeholder="Enter product title"
                    required
                  />

                  <Input
                    label="Brand"
                    type="text"
                    value={productData.brand}
                    onChange={(e) => handleChange("brand", e.target.value)}
                    placeholder="Enter brand name"
                  />

                  <Input
                    label="Base Price"
                    type="number"
                    step="0.01"
                    value={productData.price}
                    onChange={(e) => handleChange("price", e.target.value)}
                    placeholder="0.00"
                    required
                  />

                  <Select
                    label="Product For"
                    value={productData.productfor}
                    onChange={(e) => handleChange("productfor", e.target.value)}
                    options={productfor}
                    placeholder=""
                  />

                  <Select
                    label="Stock Status"
                    value={productData.stock}
                    onChange={(e) => handleChange("stock", e.target.value)}
                    options={stockOptions}
                    placeholder=""
                  />

                  <Select
                    label="Category"
                    value={productData.catItems}
                    onChange={(e) => handleChange("catItems", e.target.value)}
                    options={categories.map((cat) => ({ value: cat.id, label: cat.name }))}
                    placeholder="Select category"
                    required
                  />

                  <Select
                    label="Subcategory"
                    value={productData.subcat}
                    onChange={(e) => handleChange("subcat", e.target.value)}
                    options={subcategories.map((subcat) => ({ value: subcat.id, label: subcat.name }))}
                    placeholder="Select subcategory"
                    required
                  />

                  <Select
                    label="Product Type"
                    value={productData.product_type}
                    onChange={(e) => handleChange("product_type", e.target.value)}
                    options={productTypeOptions}
                    placeholder=""
                  />

                  <Select
                    label="Seller Level"
                    value={productData.seller_level}
                    onChange={(e) => handleChange("seller_level", e.target.value)}
                    options={sellerLevelOptions}
                    placeholder=""
                  />

                  {productData.product_type === "import" && (
                    <Input
                      label="Origin Country"
                      type="text"
                      value={productData.origin_country}
                      onChange={(e) => handleChange("origin_country", e.target.value)}
                      placeholder="e.g., China, USA"
                    />
                  )}

                  {productData.product_type === "export" && (
                    <Input
                      label="Destination Country"
                      type="text"
                      value={productData.destination_country}
                      onChange={(e) => handleChange("destination_country", e.target.value)}
                      placeholder="e.g., Kenya, UAE"
                    />
                  )}
                </div>

                <TextArea
                  label="Description"
                  value={productData.description}
                  onChange={(e) => handleChange("description", e.target.value)}
                  placeholder="Enter product description"
                  rows={4}
                  required
                />
              </div>
            )}

            {/* Images Tab */}
            {activeTab === "images" && (
              <div className="space-y-4">
                <FileInput
                  label="General Product Images"
                  accept="image/*"
                  onChange={handleGeneralImageChange}
                  multiple
                  hint="Upload one or more images for the product gallery"
                />
                {generalImagePreviews.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
                    {generalImagePreviews.map((src, index) => (
                      <div key={index} className="relative">
                        <img
                          src={src || "/placeholder.svg"}
                          alt={`Preview ${index}`}
                          className="w-full h-24 object-cover rounded-lg border-2 border-gray-200"
                        />
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Colors Tab */}
            {activeTab === "colors" && (
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-semibold text-gray-900">Color Options</h3>
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    icon={<FaPlus />}
                    onClick={addColorOption}
                  >
                    Add Color
                  </Button>
                </div>

                {colorOptions.map((colorOption, index) => (
                  <Card key={index} padding="md" className="bg-gray-50 border-gray-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">Color Option {index + 1}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeColorOption(index)}
                      >
                        Remove
                      </Button>
                    </div>

                    <div className="space-y-4">
                      <Input
                        label="Color Name"
                        type="text"
                        value={colorOption.color_name}
                        onChange={(e) => updateColorOption(index, "color_name", e.target.value)}
                        placeholder="e.g., Red, Blue, Black"
                      />

                      <FileInput
                        label="Images for this color"
                        accept="image/*"
                        onChange={(e) => handleColorImageChange(index, e)}
                        multiple
                      />
                      {colorOption.images.length > 0 && (
                        <div className="flex items-center gap-2 text-gray-500">
                          <FaImage className="text-sm" />
                          <span className="text-sm">{colorOption.images.length} image(s) selected</span>
                        </div>
                      )}
                    </div>
                  </Card>
                ))}
              </div>
            )}

            {/* Variations Tab */}
            {activeTab === "variations" && (
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-semibold text-gray-900">Product Variations</h3>
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    icon={<FaPlus />}
                    onClick={addVariation}
                  >
                    Add Variation
                  </Button>
                </div>

                {variations.map((variation, index) => (
                  <Card key={index} padding="md" className="bg-gray-50 border-gray-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">Variation {index + 1}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeVariation(index)}
                      >
                        Remove
                      </Button>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
                      <Select
                        label="Variation Type"
                        value={variation.variation_type}
                        onChange={(e) => updateVariation(index, "variation_type", e.target.value)}
                        options={variationTypes}
                        placeholder=""
                      />

                      <div>
                        {variation.variation_type === "custom" ? (
                          <Input
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            type="text"
                            value={variation.variation_value}
                            onChange={(e) => updateVariation(index, "variation_value", e.target.value)}
                            placeholder="Enter custom value"
                          />
                        ) : (
                          <Select
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            value={variation.variation_value}
                            onChange={(e) => updateVariation(index, "variation_value", e.target.value)}
                            options={variationTypes.find((t) => t.value === variation.variation_type)?.options || []}
                            placeholder="Select value"
                          />
                        )}
                      </div>

                      <Input
                        label="Color"
                        type="text"
                        value={variation.color}
                        onChange={(e) => updateVariation(index, "color", e.target.value)}
                        placeholder="Color name"
                      />

                      <Input
                        label="Price"
                        type="number"
                        step="0.01"
                        value={variation.price}
                        onChange={(e) => updateVariation(index, "price", Number.parseFloat(e.target.value) || 0)}
                        placeholder="0.00"
                      />

                      <Select
                        label="Stock"
                        value={variation.stock}
                        onChange={(e) => updateVariation(index, "stock", e.target.value)}
                        options={stockOptions}
                        placeholder=""
                      />
                    </div>
                  </Card>
                ))}
              </div>
            )}

            {/* Submit Button */}
            <div className="flex justify-end pt-6 border-t border-gray-200">
              <Button
                type="submit"
                variant="primary"
                size="lg"
                loading={loading}
                icon={<FaPlus />}
              >
                {loading ? "Adding Product..." : "Add Product"}
              </Button>
            </div>
          </form>
        </Card>
      </div>
    </AdminLayout>
  )
}

export default AddProduct
