import React from 'react';
import { FaExclamationCircle, FaCheckCircle, FaInfoCircle, FaExclamationTriangle, FaTimes } from 'react-icons/fa';

const variants = {
  error: {
    bg: 'bg-red-50 border-red-200',
    icon: <FaExclamationCircle className="text-red-500" />,
    title: 'text-red-800',
    body: 'text-red-600',
  },
  success: {
    bg: 'bg-green-50 border-green-200',
    icon: <FaCheckCircle className="text-green-500" />,
    title: 'text-green-800',
    body: 'text-green-600',
  },
  info: {
    bg: 'bg-brand-50 border-brand-200',
    icon: <FaInfoCircle className="text-brand-500" />,
    title: 'text-brand-800',
    body: 'text-brand-600',
  },
  warning: {
    bg: 'bg-amber-50 border-amber-200',
    icon: <FaExclamationTriangle className="text-amber-500" />,
    title: 'text-amber-800',
    body: 'text-amber-600',
  },
};

const Alert = ({ type = 'info', title = null, children, onClose = null, className = '' }) => {
  const v = variants[type] || variants.info;

  return (
    <div className={`flex items-start gap-3 p-4 rounded-md border ${v.bg} ${className}`}>
      <span className="flex-shrink-0 mt-0.5 text-base">{v.icon}</span>
      <div className="flex-1">
        {title && <p className={`text-sm font-semibold ${v.title}`}>{title}</p>}
        {children && <p className={`text-xs ${v.body} ${title ? 'mt-0.5' : ''}`}>{children}</p>}
      </div>
      {onClose && (
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 flex-shrink-0">
          <FaTimes className="text-sm" />
        </button>
      )}
    </div>
  );
};

export default Alert;
