/**
 * User Management — Gebya Net Admin
 * View all users (buyers + sellers), filter by role and seller_level
 */

import React, { useState, useEffect, useCallback } from 'react';
import apiClient from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  statusVariant,
  Spinner,
  EmptyState,
  SearchBar,
  Table,
  Modal,
} from '../components/ui';
import { FaUsers, FaEye } from 'react-icons/fa';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRole, setFilterRole] = useState('all');
  const [filterSellerLevel, setFilterSellerLevel] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  const [selectedUser, setSelectedUser] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 12;

  const fetchUsers = useCallback(async () => {
    try {
      setLoading(true);
      const params = {};
      if (filterRole !== 'all') params.role = filterRole;
      if (filterSellerLevel !== 'all') params.seller_level = filterSellerLevel;
      if (filterStatus !== 'all') params.status = filterStatus;
      if (searchTerm) params.search = searchTerm;

      const response = await apiClient.get('/api/user', { params });
      const data = response.data.users || response.data || [];
      setUsers(data);
    } catch (err) {
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  }, [filterRole, filterSellerLevel, filterStatus, searchTerm]);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  const openModal = (user) => {
    setSelectedUser(user);
    setShowModal(true);
  };

  const handleStatusChange = async (userId, newStatus) => {
    try {
      await apiClient.put(`/api/user/update/${userId}`, { status: newStatus });
      toast.success(`User ${newStatus} successfully`);
      fetchUsers();
      setShowModal(false);
    } catch (err) {
      toast.error('Failed to update user status');
    }
  };

  const roleVariant = (role) => {
    if (role === 'seller') return 'purple';
    if (role === 'admin') return 'red';
    return 'default';
  };

  const sellerLevelVariant = (level) => {
    if (level === 'importer') return 'green';
    if (level === 'exporter') return 'indigo';
    if (level === 'reseller') return 'blue';
    return 'default';
  };

  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = users.slice(indexOfFirstUser, indexOfLastUser);
  const totalPages = Math.ceil(users.length / usersPerPage);

  if (loading && users.length === 0) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading users..." />
        </div>
      </AdminLayout>
    );
  }

  const columns = [
    {
      header: 'Name',
      key: 'full_name',
      render: (u) => (
        <div>
          <p className="font-medium text-sm">{u.full_name}</p>
          {u.referral_code && (
            <p className="text-xs text-brand-500 font-mono">Ref: {u.referral_code}</p>
          )}
        </div>
      ),
    },
    {
      header: 'Email',
      key: 'email',
      render: (u) => <span className="text-gray-600">{u.email}</span>,
    },
    {
      header: 'Role',
      key: 'role',
      render: (u) => (
        <Badge variant={roleVariant(u.role)} size="sm">{u.role}</Badge>
      ),
    },
    {
      header: 'Seller Level',
      key: 'seller_level',
      render: (u) =>
        u.seller_level ? (
          <Badge variant={sellerLevelVariant(u.seller_level)} size="sm">{u.seller_level}</Badge>
        ) : (
          <span className="text-xs text-gray-400">-</span>
        ),
    },
    {
      header: 'Status',
      key: 'status',
      render: (u) => (
        <Badge variant={statusVariant(u.status || 'active')} size="sm">
          {u.status || 'active'}
        </Badge>
      ),
    },
    {
      header: 'Wallet',
      key: 'wallet_balance',
      className: 'text-right',
      render: (u) => (
        <span className="font-bold text-brand-500">
          {Number(u.wallet_balance || 0).toFixed(2)} ETB
        </span>
      ),
    },
    {
      header: 'Actions',
      key: 'actions',
      className: 'text-center',
      render: (u) => (
        <Button size="sm" variant="primary" icon={<FaEye />} onClick={() => openModal(u)}>
          View
        </Button>
      ),
    },
  ];

  const modalFooter = (
    <div className="flex flex-col sm:flex-row gap-3">
      {selectedUser?.status === 'pending' && (
        <Button
          variant="success"
          fullWidth
          onClick={() => handleStatusChange(selectedUser.id, 'active')}
        >
          Activate User
        </Button>
      )}
      {selectedUser?.status === 'active' && (
        <Button
          variant="danger"
          fullWidth
          onClick={() => handleStatusChange(selectedUser.id, 'suspended')}
        >
          Suspend User
        </Button>
      )}
      {selectedUser?.status === 'suspended' && (
        <Button
          variant="success"
          fullWidth
          onClick={() => handleStatusChange(selectedUser.id, 'active')}
        >
          Reactivate User
        </Button>
      )}
      <Button variant="secondary" fullWidth onClick={() => setShowModal(false)}>
        Close
      </Button>
    </div>
  );

  return (
    <AdminLayout>
      <div>
        <PageHeader
          icon={<FaUsers />}
          title="User Management"
          subtitle={`${users.length} total users`}
        />

        {/* Filters */}
        <Card padding="md" className="mb-6">
          <div className="flex flex-col gap-3">
            <SearchBar
              value={searchTerm}
              onChange={setSearchTerm}
              placeholder="Search by name or email..."
              className="max-w-md"
            />
            <div className="flex flex-wrap gap-2">
              <Select
                value={filterRole}
                onChange={(e) => setFilterRole(e.target.value)}
                placeholder=""
                options={[
                  { value: 'all', label: 'All Roles' },
                  { value: 'buyer', label: 'Buyers' },
                  { value: 'seller', label: 'Sellers' },
                ]}
                className="flex-1 sm:flex-none sm:w-44"
              />
              <Select
                value={filterSellerLevel}
                onChange={(e) => setFilterSellerLevel(e.target.value)}
                placeholder=""
                options={[
                  { value: 'all', label: 'All Seller Levels' },
                  { value: 'importer', label: 'Importer' },
                  { value: 'exporter', label: 'Exporter' },
                  { value: 'reseller', label: 'Reseller' },
                ]}
                className="flex-1 sm:flex-none sm:w-44"
              />
              <Select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                placeholder=""
                options={[
                  { value: 'all', label: 'All Status' },
                  { value: 'active', label: 'Active' },
                  { value: 'pending', label: 'Pending' },
                  { value: 'suspended', label: 'Suspended' },
                ]}
                className="flex-1 sm:flex-none sm:w-44"
              />
            </div>
          </div>
        </Card>

        {/* Users */}
        {currentUsers.length === 0 ? (
          <Card padding="none">
            <EmptyState
              icon={<FaUsers />}
              title="No users found"
              description="Try adjusting your filters or search terms."
            />
          </Card>
        ) : (
          <Table columns={columns} data={currentUsers} onRowClick={openModal} />
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex justify-center items-center mt-6 flex-wrap gap-1">
            <Button
              variant="outline"
              size="sm"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
            >
              ← Prev
            </Button>
            <span className="mx-2 text-sm text-gray-600">
              {currentPage} / {totalPages}
            </span>
            <Button
              variant="outline"
              size="sm"
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
            >
              Next →
            </Button>
          </div>
        )}

        {/* User Detail Modal */}
        <Modal
          open={showModal && !!selectedUser}
          onClose={() => setShowModal(false)}
          title="User Details"
          footer={modalFooter}
          size="md"
        >
          {selectedUser && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Full Name</p>
                  <p className="font-medium text-sm">{selectedUser.full_name}</p>
                </div>
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Email</p>
                  <p className="font-medium text-sm">{selectedUser.email}</p>
                </div>
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Phone</p>
                  <p className="font-medium text-sm">{selectedUser.phone || '-'}</p>
                </div>
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500 mb-1">Role</p>
                  <Badge variant={roleVariant(selectedUser.role)} size="sm">
                    {selectedUser.role}
                  </Badge>
                </div>
                {selectedUser.seller_level && (
                  <div className="bg-gray-50 p-3 rounded-lg">
                    <p className="text-xs text-gray-500 mb-1">Seller Level</p>
                    <Badge variant={sellerLevelVariant(selectedUser.seller_level)} size="sm">
                      {selectedUser.seller_level}
                    </Badge>
                  </div>
                )}
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500 mb-1">Status</p>
                  <Badge variant={statusVariant(selectedUser.status)} size="sm">
                    {selectedUser.status || 'active'}
                  </Badge>
                </div>
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Referral Code</p>
                  <p className="font-mono font-bold text-sm text-brand-500">{selectedUser.referral_code || '-'}</p>
                </div>
                {selectedUser.referred_by && (
                  <div className="bg-gray-50 p-3 rounded-lg">
                    <p className="text-xs text-gray-500">Referred By</p>
                    <p className="font-mono text-sm">{selectedUser.referred_by}</p>
                  </div>
                )}
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Wallet Balance</p>
                  <p className="font-bold text-sm text-brand-500">{Number(selectedUser.wallet_balance || 0).toFixed(2)} ETB</p>
                </div>
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500">Referral Earnings</p>
                  <p className="font-bold text-sm text-yellow-600">{Number(selectedUser.referral_earnings || 0).toFixed(2)} ETB</p>
                </div>
              </div>

              {selectedUser.license_file && (
                <div className="bg-gray-50 p-3 rounded-lg">
                  <p className="text-xs text-gray-500 mb-2">Business License</p>
                  <a
                    href={`${apiClient.defaults.baseURL}/${selectedUser.license_file}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-brand-500 text-sm underline"
                  >
                    View License File
                  </a>
                </div>
              )}
            </div>
          )}
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default UserManagement;
