import React, { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import {
  FaTachometerAlt, FaBox, FaProductHunt, FaCheck, FaUser, FaUsers,
  FaStore, FaCommentDots, FaMapMarkerAlt, FaGift, FaWallet, FaCar,
  FaFileAlt, FaTools, FaTimes, FaBars, FaChevronDown,
  FaSearch, FaBell, FaCog, FaSignOutAlt, FaAngleDown,
} from "react-icons/fa";
import BottomNav from "./BottomNav";

// Grouped navigation — TailAdmin style
const navGroups = [
  {
    title: "Main",
    items: [
      { name: "Dashboard", path: "/dashboard", icon: <FaTachometerAlt /> },
      { name: "All Orders", path: "/", icon: <FaBox /> },
    ],
  },
  {
    title: "Orders",
    items: [
      { name: "Approve Orders", path: "/Approveorders", icon: <FaCheck /> },
      { name: "Assigned Orders", path: "/assigned", icon: <FaFileAlt /> },
      { name: "Nearby Delivery", path: "/nearby-delivery", icon: <FaMapMarkerAlt /> },
    ],
  },
  {
    title: "Products",
    items: [
      { name: "Add Product", path: "/addproduct", icon: <FaBox /> },
      { name: "Product List", path: "/productlist", icon: <FaProductHunt /> },
      { name: "Approvals", path: "/product-approvals", icon: <FaCheck /> },
      { name: "Seller Products", path: "/sellerproduct", icon: <FaProductHunt /> },
      { name: "Product + UOM", path: "/combined", icon: <FaTools /> },
      { name: "UOM", path: "/uom", icon: <FaTools /> },
    ],
  },
  {
    title: "Users & Sellers",
    items: [
      { name: "Sellers", path: "/sellers", icon: <FaUser /> },
      { name: "User Management", path: "/users", icon: <FaUsers /> },
      { name: "Register Seller", path: "/shopper", icon: <FaUsers /> },
      { name: "Shop Locations", path: "/shop", icon: <FaStore /> },
      { name: "Delivery Boy", path: "/deliveryboy", icon: <FaUsers /> },
    ],
  },
  {
    title: "Finance",
    items: [
      { name: "Referral Dashboard", path: "/referrals", icon: <FaGift /> },
      { name: "Wallet Management", path: "/wallet", icon: <FaWallet /> },
    ],
  },
  {
    title: "Categories",
    items: [
      { name: "Add Category", path: "/addcategories", icon: <FaStore /> },
      { name: "Add Subcategory", path: "/subcat", icon: <FaTools /> },
      { name: "Update Category", path: "/update", icon: <FaTools /> },
      { name: "Update Subcategory", path: "/updatesubcat", icon: <FaTools /> },
    ],
  },
  {
    title: "Other",
    items: [
      { name: "Telalaki", path: "/telalaki", icon: <FaCar /> },
      { name: "Chat", path: "/chat", icon: <FaCommentDots /> },
    ],
  },
];

export default function AdminLayout({ children }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [expandedGroups, setExpandedGroups] = useState(() => {
    return navGroups.reduce((acc, g, i) => ({ ...acc, [i]: true }), {});
  });
  const location = useLocation();
  const navigate = useNavigate();

  const isActive = (path) => location.pathname === path;

  const toggleGroup = (index) => {
    setExpandedGroups((prev) => ({ ...prev, [index]: !prev[index] }));
  };

  React.useEffect(() => {
    navGroups.forEach((group, i) => {
      if (group.items.some((item) => isActive(item.path))) {
        setExpandedGroups((prev) => (prev[i] ? prev : { ...prev, [i]: true }));
      }
    });
  }, [location.pathname]);

  // Close profile dropdown on click outside
  React.useEffect(() => {
    const handler = () => setProfileOpen(false);
    if (profileOpen) {
      window.addEventListener("click", handler);
      return () => window.removeEventListener("click", handler);
    }
  }, [profileOpen]);

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/login");
  };

  // Get page title from route
  const currentPage = navGroups
    .flatMap((g) => g.items)
    .find((item) => isActive(item.path));

  return (
    <div className="min-h-screen bg-[#f1f5f9]">
      {/* ═══════════════════════════════════════════════════════════════
          Sidebar — TailAdmin dark slate
      ═══════════════════════════════════════════════════════════════ */}
      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside
        className={`fixed top-0 left-0 h-full w-[260px] bg-[#1e293b] text-gray-300 flex flex-col z-50 transition-transform duration-300 lg:translate-x-0 ${
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        {/* Logo / Brand */}
        <div className="h-16 flex items-center gap-3 px-5 border-b border-slate-700/50 flex-shrink-0">
          <div className="w-9 h-9 rounded-lg bg-brand-500 flex items-center justify-center font-bold text-white text-lg">
            G
          </div>
          <div>
            <span className="font-bold text-white text-base leading-tight block">
              Gebya<span className="text-brand-400">Net</span>
            </span>
            <span className="text-[11px] text-gray-500">Admin Panel</span>
          </div>
          <button
            className="lg:hidden ml-auto text-gray-400 hover:text-white p-1"
            onClick={() => setSidebarOpen(false)}
          >
            <FaTimes />
          </button>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-3 py-4 sidebar-scroll">
          {navGroups.map((group, gi) => (
            <div key={gi} className="mb-3">
              {/* Group title */}
              <button
                onClick={() => toggleGroup(gi)}
                className="w-full flex items-center justify-between px-3 py-2 text-[11px] font-semibold text-gray-500 uppercase tracking-wider hover:text-gray-300 transition-colors"
              >
                <span>{group.title}</span>
                <FaChevronDown
                  className={`text-[10px] transition-transform ${expandedGroups[gi] ? "rotate-180" : ""}`}
                />
              </button>

              {/* Group items */}
              {expandedGroups[gi] && (
                <div className="mt-1 space-y-0.5">
                  {group.items.map((link) => {
                    const active = isActive(link.path);
                    return (
                      <Link
                        key={link.path}
                        to={link.path}
                        className={`flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all ${
                          active
                            ? "bg-brand-500 text-white"
                            : "text-gray-400 hover:bg-slate-700/50 hover:text-white"
                        }`}
                        onClick={() => setSidebarOpen(false)}
                      >
                        <span className="text-sm w-4 flex-shrink-0 text-center">{link.icon}</span>
                        <span className="truncate">{link.name}</span>
                      </Link>
                    );
                  })}
                </div>
              )}
            </div>
          ))}
        </nav>

        {/* Sidebar footer */}
        <div className="p-4 border-t border-slate-700/50 flex-shrink-0">
          <button
            onClick={handleLogout}
            className="flex items-center gap-2 w-full px-3 py-2.5 text-sm font-medium text-gray-400 hover:bg-slate-700/50 hover:text-white rounded-md transition-colors"
          >
            <FaSignOutAlt className="text-sm" />
            <span>Logout</span>
          </button>
        </div>
      </aside>

      {/* ═══════════════════════════════════════════════════════════════
          Main content
      ═══════════════════════════════════════════════════════════════ */}
      <div className="lg:ml-[260px] flex flex-col min-h-screen">
        {/* Top header bar — TailAdmin style */}
        <header className="sticky top-0 z-30 h-16 bg-white border-b border-gray-200 flex items-center px-4 lg:px-6 shadow-sm">
          {/* Mobile menu toggle */}
          <button
            className="lg:hidden text-gray-600 p-2 hover:bg-gray-100 rounded-lg mr-2"
            onClick={() => setSidebarOpen(true)}
          >
            <FaBars className="text-lg" />
          </button>

          {/* Page title */}
          <h1 className="text-base font-semibold text-gray-800 hidden sm:block">
            {currentPage?.name || "Dashboard"}
          </h1>

          {/* Search bar (desktop) */}
          <div className="hidden md:flex items-center ml-6 flex-1 max-w-md">
            <div className="relative w-full">
              <FaSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-sm" />
              <input
                type="text"
                placeholder="Search..."
                className="w-full pl-9 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-md text-sm text-gray-700 placeholder-gray-400 focus:outline-none focus:border-brand-500 focus:bg-white transition-colors"
              />
            </div>
          </div>

          {/* Right actions */}
          <div className="flex items-center gap-2 ml-auto">
            {/* Notifications */}
            <button className="relative w-9 h-9 flex items-center justify-center text-gray-500 hover:bg-gray-100 hover:text-gray-700 rounded-lg transition-colors">
              <FaBell className="text-sm" />
              <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full" />
            </button>

            {/* Settings */}
            <button className="hidden sm:flex w-9 h-9 items-center justify-center text-gray-500 hover:bg-gray-100 hover:text-gray-700 rounded-lg transition-colors">
              <FaCog className="text-sm" />
            </button>

            {/* Divider */}
            <div className="hidden sm:block w-px h-6 bg-gray-200 mx-1" />

            {/* Profile dropdown */}
            <div className="relative" onClick={(e) => e.stopPropagation()}>
              <button
                onClick={() => setProfileOpen(!profileOpen)}
                className="flex items-center gap-2 p-1.5 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <div className="w-8 h-8 rounded-full bg-brand-500 flex items-center justify-center text-white font-bold text-sm">
                  A
                </div>
                <div className="hidden sm:block text-left">
                  <p className="text-xs font-semibold text-gray-800 leading-tight">Admin</p>
                  <p className="text-[10px] text-gray-500">Administrator</p>
                </div>
                <FaAngleDown className="hidden sm:block text-gray-400 text-xs" />
              </button>

              {/* Dropdown menu */}
              {profileOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-lg shadow-md border border-gray-200 py-1.5 z-50">
                  <div className="px-4 py-2 border-b border-gray-100">
                    <p className="text-sm font-semibold text-gray-800">Admin User</p>
                    <p className="text-xs text-gray-500">admin@gebyanet.com</p>
                  </div>
                  <button className="flex items-center gap-2 w-full px-4 py-2 text-sm text-gray-600 hover:bg-gray-50 transition-colors">
                    <FaCog className="text-xs" />
                    Settings
                  </button>
                  <button
                    onClick={handleLogout}
                    className="flex items-center gap-2 w-full px-4 py-2 text-sm text-red-600 hover:bg-red-50 transition-colors"
                  >
                    <FaSignOutAlt className="text-xs" />
                    Logout
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 p-4 sm:p-6 lg:p-8 pb-24 lg:pb-8">
          {children}
        </main>
      </div>

      {/* Mobile bottom navigation */}
      <BottomNav />

      {/* Custom scrollbar styling */}
      <style>{`
        .sidebar-scroll::-webkit-scrollbar { width: 4px; }
        .sidebar-scroll::-webkit-scrollbar-track { background: transparent; }
        .sidebar-scroll::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 4px; }
        .sidebar-scroll::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }
      `}</style>
    </div>
  );
}
