import React, { useState, useEffect } from 'react';
import { FaLayerGroup, FaPlus } from 'react-icons/fa';
import apiClient from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  FileInput,
  Alert,
} from '../components/ui';

const SubCategoryForm = () => {
  const [name, setName] = useState('');
  const [image, setImage] = useState(null); // To store the selected image
  const [message, setMessage] = useState(''); // Generic message text
  const [messageType, setMessageType] = useState('info'); // 'success' | 'error' | 'info'
  const [isLoading, setIsLoading] = useState(false); // To manage loading state

  // Auto-dismiss messages after a few seconds
  useEffect(() => {
    if (message) {
      const t = setTimeout(() => setMessage(''), 5000);
      return () => clearTimeout(t);
    }
  }, [message]);

  // Handle the image change event
  const handleImageChange = (e) => {
    setImage(e.target.files[0]);
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!name.trim() || !image) {
      setMessageType('error');
      setMessage('Please fill out all fields.');
      return;
    }

    const formData = new FormData();
    formData.append('name', name.trim());
    formData.append('image', image);

    setIsLoading(true); // Show loading spinner
    setMessage('');

    try {
      // Make a POST request to the backend to create the subcategory
      const response = await apiClient.post('/api/subcat/Create', formData, {
        headers: {
          'Content-Type': 'multipart/form-data', // Necessary for image upload
        },
      });
      setMessageType('success');
      setMessage(response.data?.message || 'Subcategory created successfully!');
      setName('');
      setImage(null);
      // Reset the file input via the DOM so the FileInput clears visually
      const fileInput = document.getElementById('subcategory-image');
      if (fileInput) fileInput.value = '';
    } catch (error) {
      console.error('Error creating subcategory:', error);
      setMessageType('error');
      setMessage('Error creating subcategory. Please try again.');
    } finally {
      setIsLoading(false); // Hide loading spinner
    }
  };

  return (
    <AdminLayout>
      <div className="max-w-2xl mx-auto">
        <PageHeader
          icon={<FaLayerGroup />}
          title="Create Subcategory"
          subtitle="Add a new subcategory that can be linked to product categories"
        />

        {message && (
          <div className="mb-5">
            <Alert type={messageType} onClose={() => setMessage('')}>
              {message}
            </Alert>
          </div>
        )}

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Subcategory Name */}
            <Input
              label="Subcategory Name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter subcategory name"
              required
            />

            {/* Subcategory Image */}
            <FileInput
              id="subcategory-image"
              label="Subcategory Image"
              onChange={handleImageChange}
              accept="image/*"
              required
              hint="Upload a representative image for this subcategory"
            />

            {/* Submit Button */}
            <Button
              type="submit"
              variant="primary"
              size="lg"
              loading={isLoading}
              fullWidth
              icon={<FaPlus />}
            >
              {isLoading ? 'Creating...' : 'Create Subcategory'}
            </Button>
          </form>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default SubCategoryForm;
