/**
 * Centralized API Configuration — Gebya Net Admin
 * All pages should import { apiClient, API_BASE_URL } from here
 *
 * In development, Vite proxies /api and /uploads to the backend (see vite.config.js),
 * so API_BASE_URL is empty (same-origin requests).
 * In production, set VITE_API_BASE_URL to the deployed backend URL.
 */

import axios from 'axios';

// Use Vite env var if provided, otherwise empty string (relies on Vite dev proxy)
export const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || '';

// Create a shared axios instance with interceptors
const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor — attach admin token to every request
apiClient.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('adminToken');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Response interceptor — handle 401 globally
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response && error.response.status === 401) {
      // Token expired or invalid — clear and redirect
      localStorage.removeItem('adminToken');
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

export default apiClient;
