import React, { useState } from "react";
import apiClient, { API_BASE_URL } from '../config/api';
import locationsData from "./addisAbabaLocations.json"; // Import the JSON file
import { FaMotorcycle, FaUserPlus } from "react-icons/fa";
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  Alert,
} from '../components/ui';

const RegisterDeliveryBoy = () => {
  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    location: {
      subcity: "",
      kebele: "",
    },
    password: "",
  });

  const [kebeles, setKebeles] = useState([]);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("error");

  const handleInputChange = (e) => {
    const { name, value } = e.target;

    if (name === "subcity") {
      // Update subcity and filter kebeles based on the selected subcity
      setFormData({
        ...formData,
        location: {
          ...formData.location,
          subcity: value,
          kebele: "", // Reset kebele when subcity changes
        },
      });

      // Find kebeles based on the selected subcity
      const selectedSubcity = locationsData.locations.find(
        (location) => location.name === value
      );
      setKebeles(selectedSubcity ? selectedSubcity.kebeles : []);
    } else if (name === "kebele") {
      setFormData({
        ...formData,
        location: {
          ...formData.location,
          kebele: value,
        },
      });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Concatenate subcity and kebele into a single string for the 'location' field
    const locationString = `${formData.location.subcity} - ${formData.location.kebele}`;

    // Create a new object with the location as a string
    const dataToSubmit = {
      full_name: formData.full_name,
      email: formData.email,
      location: locationString, // Use concatenated string for location
      password: formData.password,
    };

    console.log(dataToSubmit); // Inspect the data being sent

    try {
      const response = await apiClient.post('/api/deliveryboy', dataToSubmit);
      setMessage(response.data.message || "Delivery boy registered successfully.");
      setMessageType("success");
      setFormData({
        full_name: "",
        email: "",
        location: { subcity: "", kebele: "" },
        password: "",
      });
      setKebeles([]);
    } catch (error) {
      console.error("Error:", error);
      setMessage("An error occurred. Please try again.");
      setMessageType("error");
    }
  };

  // Convert locationsData to options format for the subcity Select
  const subcityOptions = locationsData.locations.map((location) => ({
    value: location.name,
    label: location.name,
  }));

  // Convert kebeles to options format for the kebele Select
  const kebeleOptions = kebeles.map((kebele) => ({
    value: kebele,
    label: kebele,
  }));

  return (
    <AdminLayout>
      <div className="max-w-2xl mx-auto">
        <PageHeader
          icon={<FaMotorcycle />}
          title="Register Delivery Boy"
          subtitle="Add a new delivery boy account with their subcity and kebele"
        />

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-5">
            <Input
              label="Full Name"
              id="full_name"
              name="full_name"
              type="text"
              value={formData.full_name}
              onChange={handleInputChange}
              placeholder="Enter delivery boy's full name"
              required
            />

            <Input
              label="Email"
              id="email"
              name="email"
              type="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Enter delivery boy's email address"
              required
            />

            <div className="flex flex-col sm:flex-row gap-4">
              <Select
                label="Subcity"
                id="subcity"
                name="subcity"
                value={formData.location.subcity}
                onChange={handleInputChange}
                options={subcityOptions}
                placeholder="Select Subcity"
                required
                className="flex-1"
              />
              <Select
                label="Kebele"
                id="kebele"
                name="kebele"
                value={formData.location.kebele}
                onChange={handleInputChange}
                options={kebeleOptions}
                placeholder="Select Kebele"
                required
                disabled={!kebeles.length}
                className="flex-1"
              />
            </div>

            <Input
              label="Password"
              id="password"
              name="password"
              type="password"
              value={formData.password}
              onChange={handleInputChange}
              placeholder="Enter a secure password"
              required
            />

            <Button
              type="submit"
              variant="primary"
              size="lg"
              fullWidth
              icon={<FaUserPlus />}
            >
              Register Delivery Boy
            </Button>
          </form>

          {message && (
            <div className="mt-5">
              <Alert
                type={messageType}
                onClose={() => setMessage("")}
              >
                {message}
              </Alert>
            </div>
          )}
        </Card>
      </div>
    </AdminLayout>
  );
};

export default RegisterDeliveryBoy;
