"use client"

import { useState, useEffect } from "react"
import { FaEdit, FaPlus, FaTimes, FaImage, FaArrowLeft } from "react-icons/fa"
import apiClient, { API_BASE_URL } from '../config/api'
import { useParams, useNavigate } from "react-router-dom"
import AdminLayout from '../components/AdminLayout'
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  FileInput,
  TextArea,
  Alert,
  Spinner,
} from '../components/ui'

const EditProduct = () => {
  const [productData, setProductData] = useState({
    title: "",
    brand: "",
    price: "",
    description: "",
    catItems: "",
    subcat: "",
    productfor: "for_user",
    stock: "in_stock",
    location_name: "Addis Ababa",
    location_radius: 10,
    product_type: "retail",
    seller_level: "reseller",
    origin_country: "",
    destination_country: "",
  })

  const [existingGeneralImages, setExistingGeneralImages] = useState([])
  const [newGeneralImages, setNewGeneralImages] = useState([])
  const [newGeneralImagePreviews, setNewGeneralImagePreviews] = useState([])

  const [existingColorOptions, setExistingColorOptions] = useState([])
  const [newColorOptions, setNewColorOptions] = useState([])
  const [existingVariations, setExistingVariations] = useState([])
  const [newVariations, setNewVariations] = useState([])

  const [categories, setCategories] = useState([])
  const [subcategories, setSubcategories] = useState([])
  const [loading, setLoading] = useState(false)
  const [updating, setUpdating] = useState(false)
  const [activeTab, setActiveTab] = useState("basic")
  const [error, setError] = useState("")
  const [success, setSuccess] = useState("")

  const { id } = useParams()
  const navigate = useNavigate()

  const stockOptions = [
    { value: "in_stock", label: "In Stock" },
    { value: "out_of_stock", label: "Out of Stock" },
    { value: "limited_stock", label: "Limited Stock" },
  ]

  const productTypeOptions = [
    { value: "retail", label: "Retail" },
    { value: "wholesale", label: "Wholesale" },
    { value: "import", label: "Import" },
    { value: "export", label: "Export" },
  ]

  const sellerLevelOptions = [
    { value: "importer", label: "Importer" },
    { value: "exporter", label: "Exporter" },
    { value: "reseller", label: "Reseller" },
  ]

  const variationTypes = [
    { value: "size", label: "Size", options: ["XS", "S", "M", "L", "XL", "XXL", "One Size"] },
    { value: "weight", label: "Weight", options: ["0.5 lb", "1 lb", "2 lb", "5 lb", "10 lb", "1 kg", "2 kg", "5 kg"] },
    {
      value: "level",
      label: "Level",
      options: ["Level 1", "Level 2", "Level 3", "Level 4", "Level 5", "Basic", "Premium", "Pro"],
    },
    { value: "volume", label: "Volume", options: ["250ml", "500ml", "750ml", "1L", "2L", "500g", "1kg"] },
    {
      value: "quantity",
      label: "Quantity",
      options: ["Single", "Pack of 6", "Pack of 12", "Pack of 24", "Dozen", "Half Dozen"],
    },
    { value: "custom", label: "Custom", options: [] },
  ]

  const tabs = [
    { id: "basic", label: "Basic Info" },
    { id: "images", label: "Images" },
    { id: "colors", label: "Colors" },
    { id: "variations", label: "Variations" },
  ]

  // Fetch product data
  useEffect(() => {
    const fetchProduct = async () => {
      setLoading(true)
      try {
        const response = await apiClient.get(`/api/prod/${id}`)
        const product = response.data

        setProductData({
          title: product.title || "",
          brand: product.brand || "",
          price: product.price || "",
          description: product.description || "",
          catItems: product.catItems || "",
          subcat: product.subcat || "",
          productfor: product.productfor || "for_user",
          stock: product.stock || "in_stock",
          location_name: product.location_name || "Addis Ababa",
          location_radius: product.location_radius || 10,
          product_type: product.product_type || "retail",
          seller_level: product.seller_level || "reseller",
          origin_country: product.origin_country || "",
          destination_country: product.destination_country || "",
        })

        // Ensure image is an array
        const imageArray = Array.isArray(product.image) ? product.image : []
        setExistingGeneralImages(imageArray)

        // Ensure color_options is an array
        const colorOptionsArray = Array.isArray(product.color_options) ? product.color_options : []
        setExistingColorOptions(colorOptionsArray)

        // Handle existing variations - convert backend format to frontend format
        const variationsArray = Array.isArray(product.variations) ? product.variations : []
        const convertedVariations = variationsArray.map((variation) => {
          // Find the variation type (size, weight, level, etc.)
          const variationType =
            Object.keys(variation).find((key) => key !== "color" && key !== "price" && key !== "stock") || "size"

          return {
            variation_type: variationType,
            variation_value: variation[variationType] || "",
            color: variation.color || "",
            price: variation.price || 0,
            stock: variation.stock || "in_stock",
          }
        })
        setExistingVariations(convertedVariations)
      } catch (error) {
        console.error("Error fetching product:", error)
        setError("Failed to fetch product")
      } finally {
        setLoading(false)
      }
    }

    fetchProduct()
  }, [id])

  // Fetch categories and subcategories
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [categoriesRes, subcategoriesRes] = await Promise.all([
          apiClient.get(`/api/catitem`),
          apiClient.get(`/api/subcat`),
        ])
        setCategories(categoriesRes.data)
        setSubcategories(subcategoriesRes.data)
      } catch (error) {
        console.error("Error fetching data:", error)
        setError("Failed to load categories")
      }
    }
    fetchData()
  }, [])

  const handleChange = (name, value) => {
    setProductData({ ...productData, [name]: value })
  }

  const handleNewGeneralImageChange = (e) => {
    const files = Array.from(e.target.files || [])
    setNewGeneralImages(files)

    // Create previews
    const previewUrls = files.map((file) => URL.createObjectURL(file))
    setNewGeneralImagePreviews(previewUrls)
  }

  const removeExistingGeneralImage = (index) => {
    setExistingGeneralImages(existingGeneralImages.filter((_, i) => i !== index))
  }

  const addNewColorOption = () => {
    setNewColorOptions([...newColorOptions, { color_name: "", images: [], image_count: 0 }])
  }

  const updateNewColorOption = (index, field, value) => {
    const updated = [...newColorOptions]
    updated[index] = { ...updated[index], [field]: value }
    setNewColorOptions(updated)
  }

  const removeNewColorOption = (index) => {
    setNewColorOptions(newColorOptions.filter((_, i) => i !== index))
  }

  const removeExistingColorOption = (index) => {
    setExistingColorOptions(existingColorOptions.filter((_, i) => i !== index))
  }

  const handleNewColorImageChange = (colorIndex, e) => {
    const files = Array.from(e.target.files || [])
    updateNewColorOption(colorIndex, "images", files)
    updateNewColorOption(colorIndex, "image_count", files.length)
  }

  const addNewVariation = () => {
    setNewVariations([
      ...newVariations,
      {
        variation_type: "size",
        variation_value: "",
        color: "",
        price: 0,
        stock: "in_stock",
      },
    ])
  }

  const updateNewVariation = (index, field, value) => {
    const updated = [...newVariations]
    updated[index] = { ...updated[index], [field]: value }

    if (field === "variation_type") {
      updated[index].variation_value = ""
    }

    setNewVariations(updated)
  }

  const updateExistingVariation = (index, field, value) => {
    const updated = [...existingVariations]
    updated[index] = { ...updated[index], [field]: value }

    if (field === "variation_type") {
      updated[index].variation_value = ""
    }

    setExistingVariations(updated)
  }

  const removeNewVariation = (index) => {
    setNewVariations(newVariations.filter((_, i) => i !== index))
  }

  const removeExistingVariation = (index) => {
    setExistingVariations(existingVariations.filter((_, i) => i !== index))
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError("")
    setSuccess("")

    if (!productData.title || !productData.price || !productData.description) {
      setError("Please fill in all required fields")
      return
    }

    const formData = new FormData()

    // Add basic product data
    Object.keys(productData).forEach((key) => {
      formData.append(key, productData[key].toString())
    })

    // Combine existing and new variations, convert to backend format
    const allVariations = [...existingVariations, ...newVariations]
    const processedVariations = allVariations.map((variation) => ({
      [variation.variation_type]: variation.variation_value,
      color: variation.color,
      price: variation.price,
      stock: variation.stock,
    }))
    formData.append("variations", JSON.stringify(processedVariations))

    // Handle existing images to keep
    formData.append("existingImages", JSON.stringify(existingGeneralImages))

    // Combine existing and new color options
    const allColorOptions = [...existingColorOptions, ...newColorOptions]
    const colorOptionsForBackend = allColorOptions.map((option) => ({
      color_name: option.color_name,
      image_count: option.image_count || 0,
      images: option.images || [], // Ensure images is always an array
    }))
    formData.append("color_options", JSON.stringify(colorOptionsForBackend))

    // Add general image count for new images
    formData.append("general_image_count", newGeneralImages.length.toString())

    // Add new images
    newGeneralImages.forEach((image) => {
      formData.append("images", image)
    })

    newColorOptions.forEach((colorOption) => {
      if (Array.isArray(colorOption.images)) {
        colorOption.images.forEach((image) => {
          formData.append("images", image)
        })
      }
    })

    setUpdating(true)
    try {
      await apiClient.put(`/api/prod/${id}`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      })

      setSuccess("Product updated successfully!")
      setTimeout(() => navigate("/productlist"), 1200)
    } catch (error) {
      console.error(error)
      const errorMessage = error.response?.data?.message || "Error updating product. Please try again."
      setError(errorMessage)
    } finally {
      setUpdating(false)
    }
  }

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex items-center justify-center py-24">
          <Spinner size="lg" label="Loading product..." />
        </div>
      </AdminLayout>
    )
  }

  return (
    <AdminLayout>
      <div className="max-w-3xl mx-auto">
        <PageHeader
          icon={<FaEdit />}
          title="Edit Product"
          subtitle="Update your product information, variations, and images"
          actions={
            <Button
              variant="outline"
              size="md"
              icon={<FaArrowLeft />}
              onClick={() => navigate("/productlist")}
            >
              Back to List
            </Button>
          }
        />

        {error && (
          <div className="mb-5">
            <Alert type="error" onClose={() => setError("")}>
              {error}
            </Alert>
          </div>
        )}

        {success && (
          <div className="mb-5">
            <Alert type="success" onClose={() => setSuccess("")}>
              {success}
            </Alert>
          </div>
        )}

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Tab Navigation */}
            <div className="flex flex-wrap gap-2 p-1 bg-gray-50 rounded-lg">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActiveTab(tab.id)}
                  className={`px-4 sm:px-6 py-2.5 font-medium text-sm rounded-lg transition-all duration-200 cursor-pointer whitespace-nowrap ${
                    activeTab === tab.id
                      ? "bg-brand-500 text-white shadow-sm"
                      : "bg-white text-gray-700 border border-gray-200 hover:bg-gray-50"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Basic Info Tab */}
            {activeTab === "basic" && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <Input
                    label="Product Title"
                    type="text"
                    value={productData.title}
                    onChange={(e) => handleChange("title", e.target.value)}
                    placeholder="Enter product title"
                    required
                  />

                  <Input
                    label="Brand"
                    type="text"
                    value={productData.brand}
                    onChange={(e) => handleChange("brand", e.target.value)}
                    placeholder="Enter brand name"
                  />

                  <Input
                    label="Base Price"
                    type="number"
                    step="0.01"
                    value={productData.price}
                    onChange={(e) => handleChange("price", e.target.value)}
                    placeholder="0.00"
                    required
                  />

                  <Select
                    label="Stock Status"
                    value={productData.stock}
                    onChange={(e) => handleChange("stock", e.target.value)}
                    options={stockOptions}
                    placeholder=""
                  />

                  <Select
                    label="Category"
                    value={productData.catItems}
                    onChange={(e) => handleChange("catItems", e.target.value)}
                    options={categories.map((cat) => ({ value: cat.id, label: cat.name }))}
                    placeholder="Select category"
                    required
                  />

                  <Select
                    label="Subcategory"
                    value={productData.subcat}
                    onChange={(e) => handleChange("subcat", e.target.value)}
                    options={subcategories.map((subcat) => ({ value: subcat.id, label: subcat.name }))}
                    placeholder="Select subcategory"
                    required
                  />

                  <Select
                    label="Product Type"
                    value={productData.product_type}
                    onChange={(e) => handleChange("product_type", e.target.value)}
                    options={productTypeOptions}
                    placeholder=""
                  />

                  <Select
                    label="Seller Level"
                    value={productData.seller_level}
                    onChange={(e) => handleChange("seller_level", e.target.value)}
                    options={sellerLevelOptions}
                    placeholder=""
                  />

                  {productData.product_type === "import" && (
                    <Input
                      label="Origin Country"
                      type="text"
                      value={productData.origin_country}
                      onChange={(e) => handleChange("origin_country", e.target.value)}
                      placeholder="e.g., China, USA, Germany"
                    />
                  )}

                  {productData.product_type === "export" && (
                    <Input
                      label="Destination Country"
                      type="text"
                      value={productData.destination_country}
                      onChange={(e) => handleChange("destination_country", e.target.value)}
                      placeholder="e.g., Kenya, UAE, France"
                    />
                  )}
                </div>

                <TextArea
                  label="Description"
                  value={productData.description}
                  onChange={(e) => handleChange("description", e.target.value)}
                  placeholder="Enter product description"
                  rows={4}
                  required
                />
              </div>
            )}

            {/* Images Tab */}
            {activeTab === "images" && (
              <div className="space-y-6">
                {/* Existing Images */}
                {existingGeneralImages.length > 0 && (
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                      Current Images
                    </label>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 sm:gap-4">
                      {existingGeneralImages.map((src, index) => (
                        <div key={index} className="relative">
                          <img
                            src={`${API_BASE_URL}${src}`}
                            alt={`Current ${index}`}
                            className="w-full h-20 sm:h-24 object-cover rounded-lg border-2 border-gray-200"
                          />
                          <button
                            type="button"
                            onClick={() => removeExistingGeneralImage(index)}
                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-sm hover:bg-red-600"
                          >
                            <FaTimes className="text-xs" />
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* New Images */}
                <FileInput
                  label="Add New Images"
                  accept="image/*"
                  onChange={handleNewGeneralImageChange}
                  multiple
                  hint="Upload one or more new images to add to the product gallery"
                />
                {newGeneralImagePreviews.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 sm:gap-4">
                    {newGeneralImagePreviews.map((src, index) => (
                      <div key={index} className="relative">
                        <img
                          src={src || "/placeholder.svg"}
                          alt={`New Preview ${index}`}
                          className="w-full h-20 sm:h-24 object-cover rounded-lg border-2 border-gray-200"
                        />
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Colors Tab */}
            {activeTab === "colors" && (
              <div className="space-y-4">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                  <h3 className="text-lg font-semibold text-gray-900">Color Options</h3>
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    icon={<FaPlus />}
                    onClick={addNewColorOption}
                  >
                    Add New Color
                  </Button>
                </div>

                {/* Existing Color Options */}
                {existingColorOptions.map((colorOption, index) => (
                  <Card key={`existing-${index}`} padding="md" className="bg-gray-50 border-gray-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">Existing Color: {colorOption.color_name}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeExistingColorOption(index)}
                      >
                        Remove
                      </Button>
                    </div>
                    <div className="text-sm text-gray-500">
                      {colorOption.images?.length || 0} image(s) for this color
                    </div>
                  </Card>
                ))}

                {/* New Color Options */}
                {newColorOptions.map((colorOption, index) => (
                  <Card key={`new-${index}`} padding="md" className="bg-amber-50 border-amber-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">New Color Option {index + 1}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeNewColorOption(index)}
                      >
                        Remove
                      </Button>
                    </div>

                    <div className="space-y-4">
                      <Input
                        label="Color Name"
                        type="text"
                        value={colorOption.color_name}
                        onChange={(e) => updateNewColorOption(index, "color_name", e.target.value)}
                        placeholder="e.g., Red, Blue, Black"
                      />

                      <FileInput
                        label="Images for this color"
                        accept="image/*"
                        onChange={(e) => handleNewColorImageChange(index, e)}
                        multiple
                      />
                      {colorOption.images.length > 0 && (
                        <div className="flex items-center gap-2 text-gray-500">
                          <FaImage className="text-sm" />
                          <span className="text-sm">{colorOption.images.length} image(s) selected</span>
                        </div>
                      )}
                    </div>
                  </Card>
                ))}
              </div>
            )}

            {/* Variations Tab */}
            {activeTab === "variations" && (
              <div className="space-y-4">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                  <h3 className="text-lg font-semibold text-gray-900">Product Variations</h3>
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    icon={<FaPlus />}
                    onClick={addNewVariation}
                  >
                    Add New Variation
                  </Button>
                </div>

                {/* Existing Variations */}
                {existingVariations.map((variation, index) => (
                  <Card key={`existing-${index}`} padding="md" className="bg-gray-50 border-gray-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">Existing Variation {index + 1}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeExistingVariation(index)}
                      >
                        Remove
                      </Button>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                      <Select
                        label="Variation Type"
                        value={variation.variation_type}
                        onChange={(e) => updateExistingVariation(index, "variation_type", e.target.value)}
                        options={variationTypes}
                        placeholder=""
                      />

                      <div>
                        {variation.variation_type === "custom" ? (
                          <Input
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            type="text"
                            value={variation.variation_value}
                            onChange={(e) => updateExistingVariation(index, "variation_value", e.target.value)}
                            placeholder="Enter custom value"
                          />
                        ) : (
                          <Select
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            value={variation.variation_value}
                            onChange={(e) => updateExistingVariation(index, "variation_value", e.target.value)}
                            options={variationTypes.find((t) => t.value === variation.variation_type)?.options || []}
                            placeholder="Select value"
                          />
                        )}
                      </div>

                      <Input
                        label="Color"
                        type="text"
                        value={variation.color}
                        onChange={(e) => updateExistingVariation(index, "color", e.target.value)}
                        placeholder="Color name"
                      />

                      <Input
                        label="Price"
                        type="number"
                        step="0.01"
                        value={variation.price}
                        onChange={(e) =>
                          updateExistingVariation(index, "price", Number.parseFloat(e.target.value) || 0)
                        }
                        placeholder="0.00"
                      />

                      <Select
                        label="Stock"
                        value={variation.stock}
                        onChange={(e) => updateExistingVariation(index, "stock", e.target.value)}
                        options={stockOptions}
                        placeholder=""
                      />
                    </div>
                  </Card>
                ))}

                {/* New Variations */}
                {newVariations.map((variation, index) => (
                  <Card key={`new-${index}`} padding="md" className="bg-amber-50 border-amber-200">
                    <div className="flex justify-between items-start mb-4">
                      <h4 className="font-medium text-gray-900">New Variation {index + 1}</h4>
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        icon={<FaTimes />}
                        onClick={() => removeNewVariation(index)}
                      >
                        Remove
                      </Button>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                      <Select
                        label="Variation Type"
                        value={variation.variation_type}
                        onChange={(e) => updateNewVariation(index, "variation_type", e.target.value)}
                        options={variationTypes}
                        placeholder=""
                      />

                      <div>
                        {variation.variation_type === "custom" ? (
                          <Input
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            type="text"
                            value={variation.variation_value}
                            onChange={(e) => updateNewVariation(index, "variation_value", e.target.value)}
                            placeholder="Enter custom value"
                          />
                        ) : (
                          <Select
                            label={variationTypes.find((t) => t.value === variation.variation_type)?.label || "Value"}
                            value={variation.variation_value}
                            onChange={(e) => updateNewVariation(index, "variation_value", e.target.value)}
                            options={variationTypes.find((t) => t.value === variation.variation_type)?.options || []}
                            placeholder="Select value"
                          />
                        )}
                      </div>

                      <Input
                        label="Color"
                        type="text"
                        value={variation.color}
                        onChange={(e) => updateNewVariation(index, "color", e.target.value)}
                        placeholder="Color name"
                      />

                      <Input
                        label="Price"
                        type="number"
                        step="0.01"
                        value={variation.price}
                        onChange={(e) => updateNewVariation(index, "price", Number.parseFloat(e.target.value) || 0)}
                        placeholder="0.00"
                      />

                      <Select
                        label="Stock"
                        value={variation.stock}
                        onChange={(e) => updateNewVariation(index, "stock", e.target.value)}
                        options={stockOptions}
                        placeholder=""
                      />
                    </div>
                  </Card>
                ))}
              </div>
            )}

            {/* Submit Buttons */}
            <div className="flex flex-col sm:flex-row justify-end gap-3 pt-6 border-t border-gray-200">
              <Button
                type="button"
                variant="secondary"
                size="lg"
                onClick={() => navigate("/productlist")}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="primary"
                size="lg"
                loading={updating}
                icon={<FaEdit />}
              >
                {updating ? "Updating Product..." : "Update Product"}
              </Button>
            </div>
          </form>
        </Card>
      </div>
    </AdminLayout>
  )
}

export default EditProduct
