import React from 'react';

const Checkbox = ({
  label,
  checked,
  onChange,
  id,
  className = '',
}) => {
  const inputId = id || `cb-${Math.random().toString(36).substr(2, 9)}`;

  return (
    <label htmlFor={inputId} className={`flex items-center gap-2 cursor-pointer group ${className}`}>
      <div className="relative">
        <input
          id={inputId}
          type="checkbox"
          checked={checked}
          onChange={onChange}
          className="peer sr-only"
        />
        <div className="w-5 h-5 border-2 border-gray-300 rounded-md peer-checked:bg-brand-500 peer-checked:border-brand-500 transition-all flex items-center justify-center">
          {checked && (
            <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          )}
        </div>
      </div>
      <span className="text-sm text-gray-600 group-hover:text-gray-800 transition-colors">{label}</span>
    </label>
  );
};

export default Checkbox;
