import React, { useState, useEffect } from "react";
import apiClient, { API_BASE_URL } from "../config/api";
import AdminLayout from "../components/AdminLayout";
import {
  PageHeader,
  Card,
  Button,
  Input,
  FileInput,
  Alert,
  Modal,
  Spinner,
  EmptyState,
} from "../components/ui";
import { FaLayerGroup, FaEdit, FaFolderOpen } from "react-icons/fa";

const SubCategoryList = () => {
  const [subcategories, setSubcategories] = useState([]);
  const [selectedSubcat, setSelectedSubcat] = useState(null);
  const [name, setName] = useState("");
  const [image, setImage] = useState(null);
  const [preview, setPreview] = useState(null); // For image preview
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info"); // success | error | info
  const [isLoading, setIsLoading] = useState(false);
  const [loadingList, setLoadingList] = useState(true);

  // Fetch subcategories from API
  useEffect(() => {
    const fetchSubcategories = async () => {
      try {
        const response = await apiClient.get("/api/subcat/");
        setSubcategories(response.data);
      } catch (error) {
        console.error("Error fetching subcategories:", error);
        setMessage("Error fetching subcategories.");
        setMessageType("error");
      } finally {
        setLoadingList(false);
      }
    };

    fetchSubcategories();
  }, []);

  // Handle selecting a subcategory to edit
  const handleEditClick = (subcat) => {
    setSelectedSubcat(subcat);
    setName(subcat.name);
    setPreview(`${API_BASE_URL}/${subcat.image}`); // Set current image preview
    setImage(null);
    setMessage("");
  };

  // Close the modal
  const closeModal = () => {
    setSelectedSubcat(null);
    setName("");
    setImage(null);
    setPreview(null); // Clear image preview
    setMessage("");
  };

  // Handle image change
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImage(file);
      setPreview(URL.createObjectURL(file)); // Temporary preview URL
    }
  };

  // Handle form submission for updating a subcategory
  const handleUpdate = async (e) => {
    e.preventDefault();

    if (!name) {
      setMessage("Name is required.");
      setMessageType("error");
      return;
    }

    const formData = new FormData();
    formData.append("name", name);
    if (image) {
      formData.append("image", image);
    }

    setIsLoading(true);

    try {
      const response = await apiClient.put(
        `/api/subcat/${selectedSubcat.id}`,
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      setMessage("Subcategory updated successfully!");
      setMessageType("success");
      closeModal();

      // Update the local subcategories list
      setSubcategories((prev) =>
        prev.map((subcat) =>
          subcat.id === selectedSubcat.id
            ? { ...subcat, name, image: response.data.image }
            : subcat
        )
      );
    } catch (error) {
      console.error("Error updating subcategory:", error);
      setMessage(
        `Error updating subcategory: ${
          error.response?.data?.message || "Please try again later."
        }`
      );
      setMessageType("error");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaLayerGroup />}
          title="Subcategories"
          subtitle="View and update subcategory items"
        />

        {/* Success or Error Message */}
        {message && (
          <div className="mb-5">
            <Alert type={messageType} onClose={() => setMessage("")}>
              {message}
            </Alert>
          </div>
        )}

        {/* Subcategory List */}
        <Card padding="md">
          {loadingList ? (
            <Spinner label="Loading subcategories..." className="py-16" />
          ) : subcategories.length === 0 ? (
            <EmptyState
              icon={<FaFolderOpen />}
              title="No subcategories yet"
              description="Subcategories will appear here once they are created."
            />
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {subcategories.map((subcat) => (
                <Card
                  key={subcat.id}
                  padding="sm"
                  hover
                  className="flex flex-col sm:flex-row items-center justify-between gap-3"
                >
                  <div className="flex items-center space-x-4 mb-3 sm:mb-0">
                    <img
                      src={`${API_BASE_URL}/${subcat.image}`}
                      alt={subcat.name}
                      className="w-12 h-12 sm:w-14 sm:h-14 object-cover rounded-lg"
                    />
                    <span className="text-base sm:text-lg font-medium text-gray-900 text-center sm:text-left">
                      {subcat.name}
                    </span>
                  </div>
                  <Button
                    variant="primary"
                    size="sm"
                    icon={<FaEdit />}
                    onClick={() => handleEditClick(subcat)}
                    className="w-full sm:w-auto"
                  >
                    Edit
                  </Button>
                </Card>
              ))}
            </div>
          )}
        </Card>

        {/* Modal for Editing Subcategory */}
        <Modal
          open={!!selectedSubcat}
          onClose={closeModal}
          title={`Edit Subcategory: ${selectedSubcat?.name || ""}`}
          size="md"
          footer={
            <div className="flex flex-col sm:flex-row justify-center gap-3">
              <Button
                variant="primary"
                size="lg"
                onClick={handleUpdate}
                loading={isLoading}
                disabled={isLoading}
                fullWidth
              >
                Update Subcategory
              </Button>
              <Button
                variant="secondary"
                size="lg"
                onClick={closeModal}
                fullWidth
              >
                Cancel
              </Button>
            </div>
          }
        >
          <form onSubmit={handleUpdate} className="space-y-5">
            {/* Name */}
            <Input
              label="Subcategory Name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />

            {/* Current or Preview Image */}
            {preview && (
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Current / Preview Image
                </label>
                <img
                  src={preview}
                  alt="Preview"
                  className="w-24 h-24 sm:w-32 sm:h-32 object-cover rounded-lg"
                />
              </div>
            )}

            {/* Update Image */}
            <FileInput
              label="Update Image (optional)"
              onChange={handleImageChange}
              accept="image/*"
              hint="Choose a new image to replace the current one"
            />
          </form>
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default SubCategoryList;
