import React, { useEffect, useState, useCallback } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { FaBox, FaEye } from 'react-icons/fa';
import { AiOutlineUser, AiOutlineDollar } from 'react-icons/ai';
import AdminLayout from '../components/AdminLayout';
import { PageHeader, Card, Button, Badge, statusVariant, Modal, Spinner, EmptyState, SearchBar, Select } from '../components/ui';

const AdminOrders = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [sortBy, setSortBy] = useState('newest');
  const [currentPage, setCurrentPage] = useState(1);
  const ordersPerPage = 9;

  const fetchOrders = useCallback(async () => {
    try {
      setLoading(true);
      const response = await apiClient.get('/api/payments/orders');
      let filteredOrders = response.data.orders || [];
      if (filterStatus !== 'all') {
        filteredOrders = filteredOrders.filter((o) => o.payment_status?.toLowerCase() === filterStatus.toLowerCase());
      }
      if (searchTerm) {
        filteredOrders = filteredOrders.filter((o) =>
          o.customer_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
          o.id.toString().includes(searchTerm)
        );
      }
      filteredOrders.sort((a, b) => {
        switch (sortBy) {
          case 'newest': return new Date(b.created_at) - new Date(a.created_at);
          case 'oldest': return new Date(a.created_at) - new Date(b.created_at);
          case 'highestPrice': return b.total_price - a.total_price;
          case 'lowestPrice': return a.total_price - b.total_price;
          default: return 0;
        }
      });
      setOrders(filteredOrders);
      setError(null);
    } catch {
      setError('Failed to fetch orders');
    } finally {
      setLoading(false);
    }
  }, [searchTerm, filterStatus, sortBy]);

  useEffect(() => { fetchOrders(); }, [fetchOrders]);

  const openModal = (order) => { setSelectedOrder(order); setShowModal(true); };

  const handleStatusChange = async (paymentId, newStatus) => {
    try {
      await apiClient.put(`/api/payments/update-status/${paymentId}`, { payment_status: newStatus });
      fetchOrders();
      setShowModal(false);
    } catch {
      setError('Failed to update order status');
    }
  };

  const indexOfLastOrder = currentPage * ordersPerPage;
  const indexOfFirstOrder = indexOfLastOrder - ordersPerPage;
  const currentOrders = orders.slice(indexOfFirstOrder, indexOfLastOrder);
  const totalPages = Math.ceil(orders.length / ordersPerPage);

  if (loading && orders.length === 0) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading orders..." />
        </div>
      </AdminLayout>
    );
  }

  if (error && orders.length === 0) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <div className="text-red-500 text-sm font-medium">{error}</div>
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="">
        <PageHeader
          icon={<FaBox />}
          title="Orders"
          subtitle={`${orders.length} total orders`}
        />

        {/* Filters */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-6">
          <SearchBar value={searchTerm} onChange={setSearchTerm} placeholder="Search by name or ID..." className="max-w-md" />
          <div className="flex flex-wrap gap-2">
            <Select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              options={[
                { value: 'all', label: 'All Status' },
                { value: 'pending', label: 'Pending' },
                { value: 'approved', label: 'Approved' },
                { value: 'declined', label: 'Declined' },
              ]}
              placeholder=""
              className="w-40"
            />
            <Select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              options={[
                { value: 'newest', label: 'Newest First' },
                { value: 'oldest', label: 'Oldest First' },
                { value: 'highestPrice', label: 'Highest Price' },
                { value: 'lowestPrice', label: 'Lowest Price' },
              ]}
              placeholder=""
              className="w-44"
            />
          </div>
        </div>

        {/* Orders Grid */}
        {currentOrders.length === 0 ? (
          <EmptyState icon={<FaBox />} title="No orders found" description="Try adjusting your search or filters." />
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {currentOrders.map((order) => (
              <Card key={order.id} hover padding="md" className="flex flex-col justify-between">
                <div>
                  <div className="flex justify-between items-start mb-3">
                    <span className="text-sm font-medium text-gray-500">#{order.id}</span>
                    <Badge variant={statusVariant(order.payment_status)} size="sm">
                      {order.payment_status}
                    </Badge>
                  </div>
                  <h3 className="font-semibold text-gray-900 truncate">{order.customer_name}</h3>
                  <p className="text-sm text-gray-500 truncate">{order.customer_email}</p>
                  <p className="text-lg font-bold text-brand-500 mt-2">
                    {Number(order.total_price).toFixed(2)} ETB
                  </p>
                </div>
                <Button
                  onClick={() => openModal(order)}
                  icon={<FaEye />}
                  fullWidth
                  className="mt-3"
                >
                  View Details
                </Button>
              </Card>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex justify-center items-center mt-6 mb-4 flex-wrap gap-1">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
              disabled={currentPage === 1}
            >
              ← Previous
            </Button>
            <div className="hidden sm:flex gap-1">
              {Array.from({ length: totalPages }, (_, i) => (
                <button
                  key={i}
                  onClick={() => setCurrentPage(i + 1)}
                  className={`w-9 h-9 rounded-lg flex items-center justify-center text-sm font-semibold transition-all ${
                    currentPage === i + 1 ? 'bg-brand-500 text-white shadow-sm' : 'bg-white text-gray-700 hover:bg-gray-100 border border-gray-200'
                  }`}
                >
                  {i + 1}
                </button>
              ))}
            </div>
            <div className="mx-2 text-sm text-gray-500">
              <span className="font-semibold text-gray-700">{currentPage}</span>
              <span className="mx-1">/</span>
              <span>{totalPages}</span>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
              disabled={currentPage === totalPages}
            >
              Next →
            </Button>
          </div>
        )}

        {/* Order Details Modal */}
        <Modal
          open={showModal && !!selectedOrder}
          onClose={() => setShowModal(false)}
          title="Order Details"
          size="lg"
          footer={
            <div className="flex flex-col sm:flex-row gap-3">
              <Button variant="success" fullWidth onClick={() => handleStatusChange(selectedOrder.id, 'Approved')}>
                Approve Order
              </Button>
              <Button variant="danger" fullWidth onClick={() => handleStatusChange(selectedOrder.id, 'Declined')}>
                Decline Order
              </Button>
            </div>
          }
        >
          {selectedOrder && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-gray-50 p-4 rounded-lg">
                  <div className="flex items-center gap-2 mb-2 text-gray-600">
                    <AiOutlineUser />
                    <span className="font-semibold text-sm">Customer Info</span>
                  </div>
                  <p className="text-sm text-gray-900">{selectedOrder.customer_name}</p>
                  <p className="text-sm text-gray-500">{selectedOrder.customer_email}</p>
                </div>
                <div className="bg-gray-50 p-4 rounded-lg">
                  <div className="flex items-center gap-2 mb-2 text-gray-600">
                    <AiOutlineDollar />
                    <span className="font-semibold text-sm">Payment Details</span>
                  </div>
                  <p className="text-sm text-gray-900">Method: {selectedOrder.payment_method}</p>
                  <p className="text-sm text-gray-500">Delivery Fee: {Number(selectedOrder.delivery_fee || 0).toFixed(2)} ETB</p>
                  <p className="text-sm text-gray-500">Service Fee: {Number(selectedOrder.service_fee || 0).toFixed(2)} ETB</p>
                  <p className="text-sm font-bold text-brand-500 mt-1">
                    Total: {Number(selectedOrder.total_price).toFixed(2)} ETB
                  </p>
                </div>
              </div>

              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="font-semibold text-sm text-gray-700 mb-3">Cart Items</h3>
                <div className="space-y-2">
                  {(() => {
                    try {
                      const items = typeof selectedOrder.cart_items === 'string'
                        ? JSON.parse(selectedOrder.cart_items)
                        : selectedOrder.cart_items;
                      return Array.isArray(items) ? items.map((item, index) => (
                        <div key={index} className="bg-white p-3 rounded-lg border border-gray-100">
                          <p className="font-medium text-sm text-gray-900">{item.title}</p>
                          <div className="flex justify-between text-sm text-gray-500 mt-1">
                            <span>Qty: {item.quantity}</span>
                            <span>{Number(item.price).toFixed(2)} ETB</span>
                          </div>
                          {item.product_type && (
                            <Badge variant="blue" size="sm" className="mt-1">{item.product_type}</Badge>
                          )}
                        </div>
                      )) : <p className="text-sm text-gray-400">No items</p>;
                    } catch {
                      return <p className="text-sm text-gray-400">Unable to parse cart items</p>;
                    }
                  })()}
                </div>
              </div>

              {selectedOrder.payment_screenshot && (
                <div className="bg-gray-50 p-4 rounded-lg">
                  <h3 className="font-semibold text-sm text-gray-700 mb-3">Payment Screenshot</h3>
                  <img
                    src={`${API_BASE_URL}/${selectedOrder.payment_screenshot}`}
                    alt="Payment Screenshot"
                    className="w-full rounded-lg"
                  />
                </div>
              )}
            </div>
          )}
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default AdminOrders;
