import React, { useState, useEffect } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { MapContainer, Marker, Popup, TileLayer } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Spinner,
  EmptyState,
} from '../components/ui';
import { FaMapMarkedAlt, FaStore, FaListUl, FaMap } from 'react-icons/fa';

const NearbyShoppers = () => {
  const [shoppers, setShoppers] = useState([]); // To store shoppers
  const [currentLocation, setCurrentLocation] = useState({ lat: 9.031215294958846, lng: 38.84177289518192 }); // Default location (Ethiopia)
  const [loading, setLoading] = useState(false);
  const [showList, setShowList] = useState(false); // Toggle for mobile list view

  // Get user's current location using geolocation
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setCurrentLocation({ lat: latitude, lng: longitude });
          fetchShoppers(latitude, longitude); // Fetch nearby shoppers based on user's location
        },
        (error) => {
          console.error(error);
          // Fetch with default location if geolocation fails
          fetchShoppers(currentLocation.lat, currentLocation.lng);
        }
      );
    } else {
      // Geolocation not supported, fetch with default location
      fetchShoppers(currentLocation.lat, currentLocation.lng);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Fetch shoppers from the backend using unified API system
  const fetchShoppers = async (latitude, longitude) => {
    setLoading(true);
    try {
      const response = await apiClient.get('/api/user', {
        params: { role: 'seller', nearby: true, latitude, longitude }
      });
      // Handle both response.data (array) and response.data.users (array) formats
      if (response.data && Array.isArray(response.data)) {
        setShoppers(response.data);
      } else if (response.data && Array.isArray(response.data.users)) {
        setShoppers(response.data.users);
      } else {
        setShoppers([]); // Set to empty array if no shoppers found
      }
    } catch (error) {
      console.error('Error fetching shoppers:', error);
      setShoppers([]);
    } finally {
      setLoading(false);
    }
  };

  // Helper to extract lat/lng from a shopper (support multiple field names)
  const getShopperCoords = (shopper) => {
    const lat = shopper.location_lat || shopper.latitude || shopper.lat;
    const lng = shopper.location_lng || shopper.location_lng || shopper.longitude || shopper.lng;
    if (lat && lng) return { lat, lng };
    return null;
  };

  // Helper to extract display name
  const getShopperName = (shopper) => shopper.full_name || shopper.name || shopper.username || 'Unknown Seller';

  // Helper to extract email/phone
  const getShopperContact = (shopper) => shopper.email || shopper.phone || 'No contact';

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaMapMarkedAlt />}
          title="Nearby Shoppers"
          subtitle="Discover nearby sellers on the map"
          actions={
            <Button
              variant="outline"
              size="sm"
              icon={showList ? <FaMap /> : <FaListUl />}
              onClick={() => setShowList(!showList)}
              className="sm:hidden"
            >
              {showList ? 'Show Map' : 'Show List'}
            </Button>
          }
        />

        {/* Location info */}
        <Card padding="sm" className="mb-5">
          <p className="text-sm text-gray-700 font-semibold">Your Location:</p>
          <p className="text-sm text-gray-600">Latitude: {currentLocation.lat}</p>
          <p className="text-sm text-gray-600">Longitude: {currentLocation.lng}</p>
        </Card>

        <div className="flex flex-col sm:flex-row gap-4 sm:gap-6">
          {/* Map container */}
          <Card padding="none" className={`w-full h-[400px] sm:h-[500px] overflow-hidden ${showList ? 'hidden sm:block' : 'block'}`}>
            <MapContainer
              center={[currentLocation.lat, currentLocation.lng]}
              zoom={13}
              style={{ height: '100%', width: '100%' }}
            >
              <TileLayer
                url={`https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png`}
              />

              {/* Render markers for each shopper, if any */}
              {shoppers.length > 0 ? (
                shoppers.map((shopper) => {
                  const coords = getShopperCoords(shopper);
                  if (coords) {
                    return (
                      <Marker
                        key={shopper.id || shopper._id}
                        position={[coords.lat, coords.lng]}
                        icon={new L.Icon({ iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png', iconSize: [20, 40] })}
                      >
                        <Popup>
                          <strong>{getShopperName(shopper)}</strong>
                          <br />
                          {getShopperContact(shopper)}
                          <br />
                          {coords.lat}, {coords.lng}
                        </Popup>
                      </Marker>
                    );
                  }
                  return null;
                })
              ) : null}
            </MapContainer>
          </Card>

          {/* Shopper List - sidebar on desktop, toggle on mobile */}
          <div className={`w-full sm:w-80 lg:w-96 ${showList ? 'block' : 'hidden sm:block'}`}>
            <Card padding="md">
              <div className="flex items-center gap-2 mb-3">
                <FaStore className="text-brand-500" />
                <h2 className="text-lg font-bold text-gray-900">Shopper List</h2>
              </div>
              {loading ? (
                <Spinner label="Loading nearby shoppers..." className="py-10" />
              ) : shoppers.length > 0 ? (
                <ul className="space-y-3 max-h-[400px] sm:max-h-[500px] overflow-y-auto pr-2">
                  {shoppers.map((shopper) => {
                    const coords = getShopperCoords(shopper);
                    return (
                      <li key={shopper.id || shopper._id} className="text-sm border border-gray-100 rounded-lg p-3 bg-gray-50">
                        <strong className="text-brand-500">{getShopperName(shopper)}</strong>
                        <br />
                        <span className="text-gray-700">{getShopperContact(shopper)}</span>
                        {coords && (
                          <>
                            <br />
                            <span className="text-xs text-gray-500">
                              Latitude: {coords.lat}, Longitude: {coords.lng}
                            </span>
                          </>
                        )}
                      </li>
                    );
                  })}
                </ul>
              ) : (
                <EmptyState
                  icon={<FaStore />}
                  title="No shoppers available"
                  description="No shoppers found in your area."
                />
              )}
            </Card>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
};

export default NearbyShoppers;
