import React, { useEffect, useState } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import AdminLayout from '../components/AdminLayout';
import { FaCar, FaSearch } from 'react-icons/fa';
import { PageHeader, Card, Button, Badge, Spinner, EmptyState, SearchBar } from '../components/ui';

export default function Telalaki() {
  const [deliveries, setDeliveries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expandedDelivery, setExpandedDelivery] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  useEffect(() => {
    const fetchDeliveries = async () => {
      try {
        const res = await apiClient.get('/api/telalaki/admin/deliveries');
        const raw = res.data.data;

        const updated = await Promise.all(raw.map(async (d) => {
          const pickup = await fetchLocationName(d.pickup_lat, d.pickup_lng);
          const dropoff = await fetchLocationName(d.dropoff_lat, d.dropoff_lng);
          return {
            ...d,
            pickup_location: pickup,
            dropoff_location: dropoff,
            formattedDate: new Date(d.createdAt).toLocaleDateString('en-US', {
              year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
            }),
          };
        }));

        setDeliveries(updated);
        setLoading(false);
      } catch (error) {
        console.error('Failed to fetch deliveries:', error);
        setLoading(false);
      }
    };
    fetchDeliveries();
  }, []);

  const fetchLocationName = async (lat, lon) => {
    if (!lat || !lon) return null;
    try {
      const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json`);
      const data = await res.json();
      return data.display_name || `${lat}, ${lon}`;
    } catch {
      return `${lat}, ${lon}`;
    }
  };

  const buildImageUrl = (filename) => (filename ? `${API_BASE_URL}/uploads/payment_proofs/${filename}` : null);

  const toggleExpandDelivery = (id) => setExpandedDelivery(expandedDelivery === id ? null : id);

  const filteredDeliveries = deliveries.filter((delivery) => {
    const matchesSearch =
      delivery.sender?.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      delivery.receiver_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      delivery.receiver_phone?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus =
      filterStatus === 'all' ||
      (filterStatus === 'paid' && delivery.payment_proof_image) ||
      (filterStatus === 'unpaid' && !delivery.payment_proof_image);
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading deliveries..." />
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="">
        <PageHeader
          icon={<FaCar />}
          title="Delivery Requests"
          subtitle={`${filteredDeliveries.length} deliveries`}
        />

        {/* Search and Filter */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-6">
          <SearchBar value={searchTerm} onChange={setSearchTerm} placeholder="Search deliveries..." />
          <div className="flex flex-row space-x-2">
            {['all', 'paid', 'unpaid'].map((f) => (
              <button
                key={f}
                onClick={() => setFilterStatus(f)}
                className={`px-4 py-2.5 rounded-lg text-sm font-semibold whitespace-nowrap transition-all ${
                  filterStatus === f
                    ? f === 'unpaid' ? 'bg-red-600 text-white' : 'bg-brand-500 text-white'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                {f === 'all' ? 'All' : f.charAt(0).toUpperCase() + f.slice(1)}
              </button>
            ))}
          </div>
        </div>

        {/* Delivery List */}
        {filteredDeliveries.length === 0 ? (
          <EmptyState
            icon={<FaCar />}
            title="No deliveries found"
            description={searchTerm ? 'Try a different search term' : 'No deliveries available at the moment'}
          />
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredDeliveries.map((delivery) => (
              <Card key={delivery.id} padding="none" className="overflow-hidden">
                <div
                  className="p-5 flex justify-between items-center cursor-pointer"
                  onClick={() => toggleExpandDelivery(delivery.id)}
                >
                  <div className="min-w-0">
                    <div className="flex items-center space-x-2">
                      <span className={`inline-block h-3 w-3 rounded-full flex-shrink-0 ${delivery.payment_proof_image ? 'bg-brand-500' : 'bg-red-500'}`} />
                      <h3 className="font-semibold text-gray-900 text-sm truncate">{delivery.sender?.full_name || 'Unknown Sender'}</h3>
                    </div>
                    <p className="text-xs text-gray-500 mt-1">{delivery.formattedDate}</p>
                  </div>
                  <div className="text-right flex-shrink-0 ml-2">
                    <p className="font-bold text-gray-900 text-sm">{delivery.price} ETB</p>
                    <p className="text-xs text-gray-500">{delivery.size} • {delivery.quantity} item(s)</p>
                  </div>
                </div>

                {expandedDelivery === delivery.id && (
                  <div className="px-5 pb-5 space-y-4 border-t border-gray-100">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
                      <div>
                        <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Sender</h4>
                        <p className="mt-1 text-sm text-gray-900">{delivery.sender?.full_name || 'N/A'}</p>
                      </div>
                      <div>
                        <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Receiver</h4>
                        <p className="mt-1 text-sm text-gray-900">{delivery.receiver_name || 'N/A'}</p>
                        <p className="text-xs text-gray-500">{delivery.receiver_phone}</p>
                      </div>
                    </div>

                    <div>
                      <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Pickup</h4>
                      <p className="mt-1 text-sm text-gray-900 break-words">{delivery.pickup_location || `${delivery.pickup_lat}, ${delivery.pickup_lng}`}</p>
                    </div>
                    <div>
                      <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Dropoff</h4>
                      <p className="mt-1 text-sm text-gray-900 break-words">{delivery.dropoff_location || `${delivery.dropoff_lat}, ${delivery.dropoff_lng}`}</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Payment</h4>
                        <p className="mt-1 text-sm text-gray-900">{delivery.payment_method || 'N/A'}</p>
                      </div>
                      <div>
                        <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Status</h4>
                        <div className="mt-1">
                          <Badge variant={delivery.payment_proof_image ? 'green' : 'red'} size="sm">
                            {delivery.payment_proof_image ? 'Paid' : 'Unpaid'}
                          </Badge>
                        </div>
                      </div>
                    </div>

                    {delivery.payment_proof_image && (
                      <div>
                        <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">Payment Proof</h4>
                        <a href={buildImageUrl(delivery.payment_proof_image)} target="_blank" rel="noopener noreferrer" className="block">
                          <img
                            src={buildImageUrl(delivery.payment_proof_image)}
                            alt="Payment Proof"
                            className="h-32 w-full object-contain rounded-lg border border-gray-200"
                          />
                        </a>
                      </div>
                    )}

                    <div className="flex flex-col sm:flex-row gap-2 pt-2">
                      <Button variant="primary" fullWidth>Approve</Button>
                      <Button variant="secondary" fullWidth>Contact</Button>
                    </div>
                  </div>
                )}
              </Card>
            ))}
          </div>
        )}
      </div>
    </AdminLayout>
  );
}
