import React from 'react';
import { FaChevronDown } from 'react-icons/fa';

const Select = ({
  label,
  id,
  value,
  onChange,
  options = [],
  required = false,
  disabled = false,
  placeholder = 'Select...',
  className = '',
  ...props
}) => {
  const selectId = id || `select-${Math.random().toString(36).substr(2, 9)}`;

  return (
    <div className={className}>
      {label && (
        <label htmlFor={selectId} className="block text-sm font-medium text-gray-700 mb-1.5">
          {label}
          {required && <span className="text-red-500 ml-1">*</span>}
        </label>
      )}
      <div className="relative">
        <select
          id={selectId}
          value={value}
          onChange={onChange}
          required={required}
          disabled={disabled}
          className={`
            w-full pl-3.5 pr-10 py-2.5 appearance-none bg-white border border-gray-300
            rounded-md text-sm text-gray-900
            focus:outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500
            transition-colors disabled:bg-gray-100 disabled:cursor-not-allowed
          `}
          {...props}
        >
          {placeholder && <option value="">{placeholder}</option>}
          {options.map((opt) => (
            <option key={opt.value ?? opt} value={opt.value ?? opt}>
              {opt.label ?? opt}
            </option>
          ))}
        </select>
        <FaChevronDown className="absolute right-3.5 top-1/2 -translate-y-1/2 text-gray-400 text-xs pointer-events-none" />
      </div>
    </div>
  );
};

export default Select;
