import React, { useState, useEffect } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import AdminLayout from '../components/AdminLayout';
import { FaCheckCircle, FaTimesCircle, FaUndoAlt, FaBoxOpen, FaTags } from 'react-icons/fa';
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  Spinner,
  EmptyState,
  statusVariant,
} from '../components/ui';

const ProductApprovals = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('pending');
  const [updatingProducts, setUpdatingProducts] = useState(new Set());

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/api/prod?status=${statusFilter}`);

      // Handle both response.data (array) and response.data.products (array)
      const data = Array.isArray(response.data)
        ? response.data
        : response.data.products || [];

      setProducts(data);
    } catch (error) {
      toast.error('Error fetching products. Please try again later.');
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, [statusFilter]);

  const updateProductStatus = async (productId, newStatus) => {
    if (updatingProducts.has(productId)) return;

    setUpdatingProducts(prev => new Set(prev).add(productId));

    try {
      await apiClient.put(`/api/prod/${productId}/status`, {
        status: newStatus
      });

      toast.success(`Product ${newStatus} successfully!`);
      fetchProducts(); // Refresh the list
    } catch (error) {
      toast.error(`Error ${newStatus === 'approved' ? 'approving' : 'rejecting'} product. Please try again.`);
      console.error('Error updating product status:', error);
    } finally {
      setUpdatingProducts(prev => {
        const newSet = new Set(prev);
        newSet.delete(productId);
        return newSet;
      });
    }
  };

  const formatPrice = (price) => {
    return new Intl.NumberFormat('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(price);
  };

  // Helper to build image URL from path
  const buildImageUrl = (img) => {
    if (!img) return '/placeholder-image.png';
    if (img.startsWith('http')) return img;
    return `${API_BASE_URL}${img}`;
  };

  const filterOptions = [
    { value: 'pending', label: 'Pending' },
    { value: 'approved', label: 'Approved' },
    { value: 'rejected', label: 'Rejected' },
  ];

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaCheckCircle />}
          title="Product Approvals"
          subtitle="Review and approve or reject seller-submitted products"
          actions={
            <Select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              options={filterOptions}
              placeholder=""
              className="w-full sm:w-48"
            />
          }
        />

        {loading ? (
          <Card padding="lg">
            <Spinner size="lg" label="Loading products..." />
          </Card>
        ) : products.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {products.map((product) => {
              // Parse product.image if it's a string, otherwise use it as is
              let imageArray = [];
              try {
                if (typeof product.image === 'string') {
                  imageArray = JSON.parse(product.image);
                } else if (Array.isArray(product.image)) {
                  imageArray = product.image;
                }
              } catch (e) {
                console.error('Error parsing product images:', e);
                imageArray = [];
              }

              return (
                <Card key={product.id} padding="md" className="flex flex-col">
                  {/* Product Images */}
                  <div className="mb-3">
                    {imageArray && imageArray.length > 0 ? (
                      <div className="grid grid-cols-2 gap-2">
                        {imageArray.slice(0, 4).map((img, index) => (
                          <img
                            key={index}
                            src={buildImageUrl(img)}
                            alt={`${product.title} - ${index + 1}`}
                            className="w-full h-40 sm:h-48 object-cover rounded-lg border border-gray-200"
                            onError={(e) => {
                              e.target.src = '/placeholder-image.png';
                            }}
                          />
                        ))}
                        {imageArray.length > 4 && (
                          <div className="w-full h-40 sm:h-48 bg-gray-100 rounded-lg flex items-center justify-center text-gray-500 text-sm">
                            +{imageArray.length - 4} more
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="w-full h-40 sm:h-48 bg-gray-100 rounded-lg flex items-center justify-center text-gray-400">
                        <FaBoxOpen className="text-3xl" />
                      </div>
                    )}
                  </div>

                  {/* Product Details */}
                  <div className="space-y-2 flex-grow">
                    <div className="flex items-start gap-2 flex-wrap">
                      <h3 className="text-lg font-semibold text-gray-900">{product.title}</h3>
                      <Badge variant={statusVariant(product.status)} size="sm">
                        {product.status.charAt(0).toUpperCase() + product.status.slice(1)}
                      </Badge>
                    </div>

                    {/* Badges: product_type & seller_level */}
                    <div className="flex flex-wrap gap-2">
                      {product.product_type && (
                        <Badge variant="indigo" size="sm">{product.product_type}</Badge>
                      )}
                      {product.seller_level && (
                        <Badge variant="purple" size="sm">{product.seller_level}</Badge>
                      )}
                    </div>

                    <p className="text-gray-600 text-sm"><span className="font-semibold">Price:</span> ${formatPrice(product.price)}</p>
                    <p className="text-gray-600 text-sm"><span className="font-semibold">Brand:</span> {product.brand || 'N/A'}</p>
                    <p className="text-gray-600 text-sm"><span className="font-semibold">Category:</span> {product.catItems}</p>
                    <p className="text-gray-600 text-sm"><span className="font-semibold">Subcategory:</span> {product.subcat}</p>
                    <p className="text-gray-600 text-sm"><span className="font-semibold">Stock:</span> {product.stock}</p>

                    {product.seller && (
                      <div className="bg-gray-50 p-2 rounded-lg border border-gray-100">
                        <p className="text-gray-700 text-sm"><span className="font-semibold">Seller:</span> {product.seller.full_name}</p>
                        <p className="text-gray-500 text-sm">{product.seller.email}</p>
                      </div>
                    )}

                    {product.description && (
                      <p className="text-gray-500 text-sm mt-2">
                        <span className="font-semibold">Description:</span> {product.description.substring(0, 150)}
                        {product.description.length > 150 && '...'}
                      </p>
                    )}
                  </div>

                  {/* Action Buttons */}
                  <div className="mt-3 pt-3 border-t border-gray-100">
                    <p className="text-sm text-gray-400 mb-2">
                      Created: {new Date(product.createdAt).toLocaleDateString()}
                    </p>

                    {product.status === 'pending' && (
                      <div className="flex flex-col gap-2">
                        <Button
                          onClick={() => updateProductStatus(product.id, 'approved')}
                          loading={updatingProducts.has(product.id)}
                          disabled={updatingProducts.has(product.id)}
                          variant="success"
                          icon={<FaCheckCircle />}
                          fullWidth
                        >
                          Approve
                        </Button>
                        <Button
                          onClick={() => updateProductStatus(product.id, 'rejected')}
                          loading={updatingProducts.has(product.id)}
                          disabled={updatingProducts.has(product.id)}
                          variant="danger"
                          icon={<FaTimesCircle />}
                          fullWidth
                        >
                          Reject
                        </Button>
                      </div>
                    )}

                    {product.status !== 'pending' && (
                      <Button
                        onClick={() => updateProductStatus(product.id, 'pending')}
                        loading={updatingProducts.has(product.id)}
                        disabled={updatingProducts.has(product.id)}
                        variant="warning"
                        icon={<FaUndoAlt />}
                        fullWidth
                      >
                        Reset to Pending
                      </Button>
                    )}
                  </div>
                </Card>
              );
            })}
          </div>
        ) : (
          <Card padding="lg">
            <EmptyState
              icon={<FaTags />}
              title={`No ${statusFilter} products found`}
              description="There are currently no products matching the selected status filter."
            />
          </Card>
        )}

        <ToastContainer />
      </div>
    </AdminLayout>
  );
};

export default ProductApprovals;
