import React, { useState, useCallback } from "react";
import apiClient, { API_BASE_URL } from '../config/api';
import { motion } from "framer-motion";
import { FaUser, FaEye, FaCheck, FaSyncAlt, FaUsers } from "react-icons/fa";
import useSWRInfinite from "swr/infinite";
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Badge,
  statusVariant,
  Alert,
  Modal,
  Spinner,
  EmptyState,
  SearchBar,
  Select,
} from '../components/ui';

const fetcher = (url) => apiClient.get(url).then((res) => res.data);

const levelVariant = (level) => {
  switch (level) {
    case "importer":
      return "green";
    case "exporter":
      return "purple";
    case "reseller":
      return "blue";
    default:
      return "default";
  }
};

const Seller = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [selectedSeller, setSelectedSeller] = useState(null);
  const [modalIsOpen, setModalIsOpen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState(null);

  const getKey = (pageIndex, previousPageData) => {
    if (previousPageData && !previousPageData.nextPage) return null;
    const params = new URLSearchParams({
      role: 'seller',
      page: pageIndex + 1,
      status: filterStatus,
      search: searchTerm,
    });
    return `/api/user?${params.toString()}`;
  };

  const { data, size, setSize, isValidating, mutate } = useSWRInfinite(getKey, fetcher);

  const sellers = data
    ? data.flatMap((page) => page.users || page.data || [])
    : [];
  const totalCount = data && data[0] ? data[0].totalCount || data[0].total || sellers.length : sellers.length;

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await mutate();
    setIsRefreshing(false);
  };

  const handleScroll = useCallback((e) => {
    const bottom = e.target.scrollHeight - e.target.scrollTop === e.target.clientHeight;
    if (bottom) {
      setSize(size + 1);
    }
  }, [setSize, size]);

  const updateSellerStatus = async (id, status) => {
    try {
      await apiClient.put(`/api/user/update/${id}`, {
        status: status,
      });
      mutate();
      setModalIsOpen(false);
      setError(null);
    } catch (err) {
      setError("Failed to update seller status. Please try again.");
    }
  };

  const statusOptions = [
    { value: "all", label: "All Status" },
    { value: "Verified", label: "Verified" },
    { value: "Unverified", label: "Unverified" },
  ];

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaUser />}
          title="Seller Management"
          subtitle={`${totalCount} seller${totalCount === 1 ? "" : "s"} total`}
          actions={
            <Button
              variant="outline"
              size="md"
              icon={<FaSyncAlt className={isRefreshing ? "animate-spin" : ""} />}
              onClick={handleRefresh}
              disabled={isRefreshing}
            >
              Refresh
            </Button>
          }
        />

        {error && (
          <div className="mb-4">
            <Alert type="error" title="Error" onClose={() => setError(null)}>
              {error}
            </Alert>
          </div>
        )}

        {/* Filters */}
        <Card padding="md" className="mb-6">
          <div className="flex flex-col sm:flex-row gap-3">
            <SearchBar
              value={searchTerm}
              onChange={setSearchTerm}
              placeholder="Search sellers..."
            />
            <div className="sm:w-56">
              <Select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                options={statusOptions}
                placeholder={null}
              />
            </div>
          </div>
        </Card>

        {/* Loading state */}
        {!data && isValidating && (
          <div className="py-16">
            <Spinner size="lg" label="Loading sellers..." />
          </div>
        )}

        {/* Empty state */}
        {data && sellers.length === 0 && !isValidating && (
          <Card padding="lg">
            <EmptyState
              icon={<FaUsers />}
              title="No sellers found"
              description="Try adjusting your search or filters to find sellers."
            />
          </Card>
        )}

        {/* Seller grid */}
        {sellers.length > 0 && (
          <div className="flex-1 overflow-y-auto" onScroll={handleScroll}>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {sellers.map((seller) => (
                <motion.div
                  key={seller.id}
                  layout
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                >
                  <Card padding="md" hover>
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center space-x-3">
                        {seller.image && (
                          <img
                            src={`${API_BASE_URL}/${seller.image}`}
                            alt={seller.name}
                            className="w-11 h-11 rounded-full object-cover"
                          />
                        )}
                        <div>
                          <h3 className="font-semibold text-gray-900">{seller.name}</h3>
                          <p className="text-sm text-gray-500">{seller.email}</p>
                        </div>
                      </div>
                      <Badge variant={statusVariant(seller.status)} size="sm">
                        {seller.status}
                      </Badge>
                    </div>

                    <div className="flex flex-wrap gap-2 mt-2">
                      {seller.seller_level && (
                        <Badge variant={levelVariant(seller.seller_level)} size="sm">
                          {seller.seller_level}
                        </Badge>
                      )}
                      {seller.referral_code && (
                        <Badge variant="default" size="sm">
                          Ref: {seller.referral_code}
                        </Badge>
                      )}
                    </div>

                    <div className="flex flex-col sm:flex-row justify-end gap-2 mt-4">
                      <Button
                        variant="primary"
                        size="sm"
                        icon={<FaEye />}
                        onClick={() => {
                          setSelectedSeller(seller);
                          setModalIsOpen(true);
                        }}
                      >
                        Details
                      </Button>
                      {seller.status === "Unverified" && (
                        <Button
                          variant="success"
                          size="sm"
                          icon={<FaCheck />}
                          onClick={() => updateSellerStatus(seller.id, "Approved")}
                        >
                          Approve
                        </Button>
                      )}
                    </div>
                  </Card>
                </motion.div>
              ))}
            </div>

            {isValidating && data && (
              <div className="py-8">
                <Spinner size="md" label="Loading more..." />
              </div>
            )}
          </div>
        )}
      </div>

      {/* Seller details modal */}
      <Modal
        open={modalIsOpen}
        onClose={() => setModalIsOpen(false)}
        title="Seller Details"
        size="lg"
        footer={
          <div className="flex flex-col sm:flex-row justify-end gap-2">
            <Button
              variant="success"
              size="md"
              icon={<FaCheck />}
              onClick={() => updateSellerStatus(selectedSeller?.id, "Approved")}
            >
              Approve
            </Button>
            <Button
              variant="danger"
              size="md"
              onClick={() => updateSellerStatus(selectedSeller?.id, "Declined")}
            >
              Decline
            </Button>
            <Button
              variant="secondary"
              size="md"
              onClick={() => setModalIsOpen(false)}
            >
              Close
            </Button>
          </div>
        }
      >
        {selectedSeller && (
          <div className="space-y-4">
            {selectedSeller.image && (
              <div className="flex justify-center">
                <img
                  src={`${API_BASE_URL}/${selectedSeller.image}`}
                  alt={selectedSeller.name}
                  className="w-24 h-24 rounded-full object-cover"
                />
              </div>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Name</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.name}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Email</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.email}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Status</p>
                <div className="mt-1">
                  <Badge variant={statusVariant(selectedSeller.status)} size="sm">
                    {selectedSeller.status}
                  </Badge>
                </div>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Phone</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.phone || "N/A"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Address</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.address || "N/A"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Bank</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.bank || "N/A"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Account Number</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.account_number || "N/A"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Seller Level</p>
                <div className="mt-1">
                  {selectedSeller.seller_level ? (
                    <Badge variant={levelVariant(selectedSeller.seller_level)} size="sm">
                      {selectedSeller.seller_level}
                    </Badge>
                  ) : (
                    <p className="text-sm text-gray-900 font-medium">N/A</p>
                  )}
                </div>
              </div>
              <div>
                <p className="text-xs text-gray-400 font-semibold uppercase">Referral Code</p>
                <p className="text-sm text-gray-900 font-medium">{selectedSeller.referral_code || selectedSeller.code || "N/A"}</p>
              </div>
              <div className="sm:col-span-2">
                <p className="text-xs text-gray-400 font-semibold uppercase">License File</p>
                {selectedSeller.license_file ? (
                  <a
                    href={`${API_BASE_URL}/${selectedSeller.license_file}`}
                    download
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm text-brand-500 underline hover:text-brand-600"
                  >
                    Download PDF
                  </a>
                ) : (
                  <p className="text-sm text-gray-900 font-medium">N/A</p>
                )}
              </div>
            </div>
          </div>
        )}
      </Modal>
    </AdminLayout>
  );
};

export default Seller;
