import React, { useState, useEffect } from 'react';
import apiClient, { API_BASE_URL } from '../config/api';
import { useNavigate } from 'react-router-dom';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  Select,
  FileInput,
  Badge,
  Alert,
  Modal,
  Spinner,
  EmptyState,
} from '../components/ui';
import { FaTags, FaEdit, FaTimes, FaFolderOpen } from 'react-icons/fa';

const UpdateCatItem = () => {
  const navigate = useNavigate();

  const [catItems, setCatItems] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [currentCatItem, setCurrentCatItem] = useState(null);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [currentImage, setCurrentImage] = useState(null);
  const [subcategories, setSubcategories] = useState([]);
  const [selectedSubcategories, setSelectedSubcategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingList, setLoadingList] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedSubcat, setSelectedSubcat] = useState('');

  // Fetch all CatItems and available subcategories
  useEffect(() => {
    const fetchCatItems = async () => {
      try {
        const response = await apiClient.get('/api/catitem');
        setCatItems(response.data);
      } catch (error) {
        setError('Failed to fetch categories.');
      } finally {
        setLoadingList(false);
      }
    };

    const fetchSubcategories = async () => {
      try {
        const response = await apiClient.get('/api/subcat');
        setSubcategories(response.data);
      } catch (error) {
        setError('Failed to fetch subcategories.');
      }
    };

    fetchCatItems();
    fetchSubcategories();
  }, []);

  // Open the modal with the details of the selected CatItem
  const openModal = (catItem) => {
    setCurrentCatItem(catItem);
    setName(catItem.name);
    setCurrentImage(catItem.image);
    setSelectedSubcategories(catItem.subcats.map((sub) => sub.id));
    setModalOpen(true);
  };

  // Close the modal
  const closeModal = () => {
    setModalOpen(false);
    setName('');
    setImage(null);
    setSelectedSubcategories([]);
    setSelectedSubcat('');
    setError('');
    setSuccess('');
  };

  // Handle form submission to update CatItem
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    const trimmedName = name.trim();
    if (!trimmedName) {
      setError('Category name is required.');
      setLoading(false);
      return;
    }

    const formData = new FormData();
    formData.append('name', trimmedName);
    if (image) formData.append('image', image);
    selectedSubcategories.forEach((subcatId) => {
      formData.append('subcatIds[]', subcatId);
    });

    try {
      const response = await apiClient.put(
        `/api/catitem/update/${currentCatItem.id}`,
        formData,
        {
          headers: { 'Content-Type': 'multipart/form-data' },
        }
      );

      setSuccess(response.data.message || 'Category updated successfully!');
      closeModal(); // Close the modal after update

      // Refresh the list after a successful update
      const refresh = await apiClient.get('/api/catitem');
      setCatItems(refresh.data);
    } catch (error) {
      setError('Failed to update category.');
    } finally {
      setLoading(false);
    }
  };

  // Add or remove subcategories
  const handleAddSubcategory = (id) => {
    if (id && !selectedSubcategories.includes(id)) {
      setSelectedSubcategories([...selectedSubcategories, id]);
    }
    setSelectedSubcat('');
  };

  const handleRemoveSubcategory = (id) => {
    setSelectedSubcategories(selectedSubcategories.filter((subcatId) => subcatId !== id));
  };

  const subcatOptions = subcategories.map((subcat) => ({
    value: subcat.id,
    label: subcat.name,
  }));

  return (
    <AdminLayout>
      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaTags />}
          title="Categories"
          subtitle="View and update category items"
        />

        {/* Error Alert */}
        {error && (
          <div className="mb-5">
            <Alert type="error" onClose={() => setError('')}>{error}</Alert>
          </div>
        )}

        {/* Success Alert */}
        {success && (
          <div className="mb-5">
            <Alert type="success" onClose={() => setSuccess('')}>{success}</Alert>
          </div>
        )}

        {/* List of CatItems */}
        <Card padding="md">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-gray-900">Category List</h3>
            <Badge variant="blue" size="md">{catItems.length} items</Badge>
          </div>

          {loadingList ? (
            <Spinner label="Loading categories..." className="py-16" />
          ) : catItems.length === 0 ? (
            <EmptyState
              icon={<FaFolderOpen />}
              title="No categories yet"
              description="Categories will appear here once they are created."
            />
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {catItems.map((catItem) => (
                <Card key={catItem.id} padding="sm" hover className="flex flex-col sm:flex-row items-center justify-between gap-3">
                  <div className="flex items-center gap-3 w-full">
                    {catItem.image && (
                      <img
                        src={`${API_BASE_URL}${catItem.image}`}
                        alt={catItem.name}
                        className="h-20 sm:h-24 w-20 sm:w-24 object-cover rounded-lg flex-shrink-0"
                      />
                    )}
                    <span className="text-base sm:text-lg font-semibold text-gray-900 break-words">
                      {catItem.name}
                    </span>
                  </div>
                  <Button
                    variant="primary"
                    size="sm"
                    icon={<FaEdit />}
                    onClick={() => openModal(catItem)}
                    className="w-full sm:w-auto"
                  >
                    Edit
                  </Button>
                </Card>
              ))}
            </div>
          )}
        </Card>

        {/* Modal for editing the category */}
        <Modal
          open={modalOpen}
          onClose={closeModal}
          title="Edit Category"
          size="md"
          footer={
            <div className="flex flex-col sm:flex-row gap-3">
              <Button
                variant="primary"
                size="lg"
                fullWidth
                onClick={handleSubmit}
                loading={loading}
                disabled={loading}
              >
                Update Category
              </Button>
              <Button
                variant="secondary"
                size="lg"
                fullWidth
                onClick={closeModal}
              >
                Close
              </Button>
            </div>
          }
        >
          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Category Name */}
            <Input
              label="Category Name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter category name"
              required
            />

            {/* Current Category Image */}
            {currentImage && (
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Current Image</label>
                <img
                  src={`${API_BASE_URL}${currentImage}`}
                  alt="Current Category"
                  className="h-20 sm:h-24 w-20 sm:w-24 object-cover rounded-lg"
                />
              </div>
            )}

            {/* Category Image */}
            <FileInput
              label="Update Image (optional)"
              onChange={(e) => setImage(e.target.files[0])}
              accept="image/*"
              hint="Choose a new image to replace the current one"
            />

            {/* Subcategories */}
            <div>
              <Select
                label="Subcategories"
                value={selectedSubcat}
                onChange={(e) => handleAddSubcategory(Number(e.target.value))}
                options={subcatOptions}
                placeholder="Select a Subcategory"
              />

              {/* Selected Subcategories */}
              <div className="mt-4 flex flex-wrap gap-2">
                {selectedSubcategories.map((id) => {
                  const subcat = subcategories.find((sub) => sub.id === id);
                  return (
                    <Badge key={id} variant="blue" size="md" className="flex items-center gap-1">
                      {subcat?.name}
                      <button
                        type="button"
                        onClick={() => handleRemoveSubcategory(id)}
                        className="ml-1 text-red-500 hover:text-red-700 focus:outline-none"
                      >
                        <FaTimes className="text-xs" />
                      </button>
                    </Badge>
                  );
                })}
              </div>
            </div>
          </form>
        </Modal>
      </div>
    </AdminLayout>
  );
};

export default UpdateCatItem;
