/**
 * Dashboard — Gebya Net Admin (Advanced)
 * Overview with KPI stat cards, recent orders, pending approvals,
 * pending withdrawals, recent users, and quick actions.
 * Responsive: grid cards on desktop, stacked on mobile.
 *
 * Refactored to use the shared UI component library for visual consistency.
 */

import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import apiClient, { API_BASE_URL } from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Badge,
  statusVariant,
  Spinner,
  EmptyState,
} from '../components/ui';
import {
  FaBox, FaUsers, FaStore, FaCoins, FaArrowUp, FaArrowDown,
  FaClock, FaCheckCircle, FaTimesCircle, FaGift, FaWallet,
  FaExclamationTriangle, FaChartLine, FaEye, FaUserCircle,
} from 'react-icons/fa';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const Dashboard = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalOrders: 0,
    pendingOrders: 0,
    approvedOrders: 0,
    totalUsers: 0,
    totalSellers: 0,
    totalProducts: 0,
    pendingProducts: 0,
    totalWalletBalance: 0,
    pendingWithdrawals: 0,
    pendingWithdrawalCount: 0,
    totalReferralEarnings: 0,
  });
  const [recentOrders, setRecentOrders] = useState([]);
  const [pendingProductsList, setPendingProductsList] = useState([]);
  const [pendingWithdrawalsList, setPendingWithdrawalsList] = useState([]);
  const [recentUsers, setRecentUsers] = useState([]);

  const fetchDashboardData = useCallback(async () => {
    try {
      setLoading(true);

      // Fetch all data in parallel — each is non-blocking (Promise.allSettled)
      const [ordersRes, usersRes, productsRes, pendingProductsRes, withdrawRes] = await Promise.allSettled([
        apiClient.get('/api/payments/orders'),
        apiClient.get('/api/user', { params: { limit: 100 } }),
        apiClient.get('/api/prod', { params: { status: 'approved' } }),
        apiClient.get('/api/prod', { params: { status: 'pending' } }),
        apiClient.get('/api/withdraw'),
      ]);

      // Orders
      let orders = [];
      if (ordersRes.status === 'fulfilled') {
        orders = ordersRes.value.data.orders || ordersRes.value.data || [];
        setRecentOrders(orders.slice(0, 5));
      }
      const pendingOrders = orders.filter((o) => {
        const s = (o.payment_status || '').toLowerCase();
        return s === 'pending' || s === 'pending delivery' || s === 'pending delivery confirmation';
      }).length;
      const approvedOrders = orders.filter((o) => (o.payment_status || '').toLowerCase() === 'approved').length;

      // Users
      let users = [];
      if (usersRes.status === 'fulfilled') {
        users = usersRes.value.data.users || usersRes.value.data || [];
        setRecentUsers(users.slice(0, 5));
      }
      const sellers = users.filter((u) => u.role === 'seller').length;
      const totalWallet = users.reduce((sum, u) => sum + parseFloat(u.wallet_balance || 0), 0);
      const totalReferral = users.reduce((sum, u) => sum + parseFloat(u.referral_earnings || 0), 0);

      // Products
      let approvedProducts = [];
      if (productsRes.status === 'fulfilled') {
        approvedProducts = productsRes.value.data.products || productsRes.value.data || [];
      }
      let pendingProds = [];
      if (pendingProductsRes.status === 'fulfilled') {
        pendingProds = pendingProductsRes.value.data.products || pendingProductsRes.value.data || [];
        setPendingProductsList(pendingProds.slice(0, 4));
      }

      // Withdrawals
      let pendingWd = [];
      let pendingWdAmount = 0;
      if (withdrawRes.status === 'fulfilled') {
        const allWd = withdrawRes.value.data.withdrawals || [];
        pendingWd = allWd.filter((w) => w.status === 'Pending');
        pendingWdAmount = pendingWd.reduce((sum, w) => sum + parseFloat(w.amount || 0), 0);
        setPendingWithdrawalsList(pendingWd.slice(0, 4));
      }

      setStats({
        totalOrders: orders.length,
        pendingOrders,
        approvedOrders,
        totalUsers: users.length,
        totalSellers: sellers,
        totalProducts: approvedProducts.length,
        pendingProducts: pendingProds.length,
        totalWalletBalance: totalWallet,
        pendingWithdrawals: pendingWdAmount,
        pendingWithdrawalCount: pendingWd.length,
        totalReferralEarnings: totalReferral,
      });
    } catch (err) {
      toast.error('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  const formatETB = (amount) =>
    Number(amount).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 }) + ' ETB';

  // ===== Stat Card Component =====
  // Uses Card with hover for consistent styling. The icon sits in a colored
  // rounded square, the value is large/bold, and the label is small/gray.
  const StatCard = ({ icon, label, value, sublabel, color, link, alert }) => (
    <Link to={link || '#'} className="block">
      <Card padding="md" hover className="h-full">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div className={`w-11 h-11 sm:w-12 sm:h-12 rounded-lg flex items-center justify-center ${color} shadow-sm`}>
              {icon}
            </div>
            <div>
              <p className="text-xs sm:text-sm text-gray-500 font-medium">{label}</p>
              <p className="text-xl sm:text-2xl font-bold text-gray-800">{value}</p>
              {sublabel && <p className="text-xs text-gray-400 mt-0.5">{sublabel}</p>}
            </div>
          </div>
          {alert > 0 && (
            <Badge variant="yellow" size="sm" className="flex items-center gap-1">
              <FaExclamationTriangle /> {alert}
            </Badge>
          )}
        </div>
      </Card>
    </Link>
  );

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading dashboard..." />
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="">
        {/* Header */}
        <PageHeader
          icon={<FaChartLine />}
          title="Dashboard"
          subtitle="Overview of your platform"
        />

        {/* KPI Stat Cards */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-6">
          <StatCard
            icon={<FaBox className="text-white text-lg" />}
            label="Total Orders"
            value={stats.totalOrders}
            sublabel={`${stats.pendingOrders} pending`}
            color="bg-brand-500"
            link="/"
            alert={stats.pendingOrders}
          />
          <StatCard
            icon={<FaUsers className="text-white text-lg" />}
            label="Total Users"
            value={stats.totalUsers}
            sublabel={`${stats.totalSellers} sellers`}
            color="bg-indigo-500"
            link="/users"
          />
          <StatCard
            icon={<FaStore className="text-white text-lg" />}
            label="Products"
            value={stats.totalProducts}
            sublabel={`${stats.pendingProducts} pending approval`}
            color="bg-green-500"
            link="/product-approvals"
            alert={stats.pendingProducts}
          />
          <StatCard
            icon={<FaWallet className="text-white text-lg" />}
            label="Wallet Balance"
            value={formatETB(stats.totalWalletBalance)}
            sublabel={`${stats.pendingWithdrawalCount} withdrawal requests`}
            color="bg-amber-500"
            link="/wallet"
            alert={stats.pendingWithdrawalCount}
          />
        </div>

        {/* Secondary stats row */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-6">
          <StatCard
            icon={<FaCheckCircle className="text-white text-lg" />}
            label="Approved Orders"
            value={stats.approvedOrders}
            color="bg-emerald-500"
            link="/"
          />
          <StatCard
            icon={<FaClock className="text-white text-lg" />}
            label="Pending Withdrawals"
            value={formatETB(stats.pendingWithdrawals)}
            sublabel={`${stats.pendingWithdrawalCount} requests`}
            color="bg-orange-500"
            link="/wallet"
          />
          <StatCard
            icon={<FaGift className="text-white text-lg" />}
            label="Referral Earnings"
            value={formatETB(stats.totalReferralEarnings)}
            sublabel="Platform-wide"
            color="bg-purple-500"
            link="/referrals"
          />
          <StatCard
            icon={<FaUserCircle className="text-white text-lg" />}
            label="Sellers"
            value={stats.totalSellers}
            sublabel="Active seller accounts"
            color="bg-cyan-500"
            link="/sellers"
          />
        </div>

        {/* Quick Actions */}
        <Card padding="md" className="mb-6">
          <h2 className="text-sm font-bold text-gray-700 mb-3 flex items-center gap-2">
            <FaChartLine className="text-brand-500" /> Quick Actions
          </h2>
          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-2 sm:gap-3">
            <Link to="/product-approvals" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-700 transition">
              <FaClock /> <span className="text-xs font-medium">Approve Products</span>
            </Link>
            <Link to="/wallet" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-orange-50 hover:bg-orange-100 text-orange-700 transition">
              <FaArrowDown /> <span className="text-xs font-medium">Withdrawals</span>
            </Link>
            <Link to="/users" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-brand-50 hover:bg-brand-100 text-brand-600 transition">
              <FaUsers /> <span className="text-xs font-medium">Users</span>
            </Link>
            <Link to="/referrals" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-purple-50 hover:bg-purple-100 text-purple-700 transition">
              <FaGift /> <span className="text-xs font-medium">Referrals</span>
            </Link>
            <Link to="/addproduct" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-emerald-50 hover:bg-emerald-100 text-emerald-700 transition">
              <FaStore /> <span className="text-xs font-medium">Add Product</span>
            </Link>
            <Link to="/chat" className="flex flex-col items-center gap-1 p-3 rounded-lg bg-cyan-50 hover:bg-cyan-100 text-cyan-700 transition">
              <FaBox /> <span className="text-xs font-medium">Chat</span>
            </Link>
          </div>
        </Card>

        {/* Two-column layout: Recent Orders + Pending Withdrawals */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6 mb-6">
          {/* Recent Orders */}
          <Card padding="none" className="overflow-hidden">
            <div className="p-4 sm:p-5 border-b border-gray-100 flex justify-between items-center">
              <h2 className="text-sm font-bold text-gray-700 flex items-center gap-2">
                <FaBox className="text-brand-500" /> Recent Orders
              </h2>
              <Link to="/" className="text-xs text-brand-500 font-medium hover:underline flex items-center gap-1">
                View all <FaEye />
              </Link>
            </div>
            <div className="divide-y divide-gray-50">
              {recentOrders.length === 0 ? (
                <EmptyState
                  icon={<FaBox />}
                  title="No orders yet"
                  description="Orders will appear here once customers start purchasing."
                />
              ) : (
                recentOrders.map((order) => (
                  <div key={order.id} className="p-4 hover:bg-gray-50 transition flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-10 h-10 rounded-lg bg-brand-50 flex items-center justify-center flex-shrink-0">
                        <FaBox className="text-brand-500 text-sm" />
                      </div>
                      <div className="min-w-0">
                        <p className="font-medium text-sm text-gray-800 truncate">Order #{order.id}</p>
                        <p className="text-xs text-gray-500 truncate">
                          {order.customer_name || order.customer_email || 'Guest'} • {order.payment_method}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <Badge variant={statusVariant(order.payment_status)} size="sm">
                        {order.payment_status}
                      </Badge>
                      <p className="text-sm font-bold text-gray-800 hidden sm:block">
                        {Number(order.total_price || 0).toLocaleString()} ETB
                      </p>
                    </div>
                  </div>
                ))
              )}
            </div>
          </Card>

          {/* Pending Withdrawals */}
          <Card padding="none" className="overflow-hidden">
            <div className="p-4 sm:p-5 border-b border-gray-100 flex justify-between items-center">
              <h2 className="text-sm font-bold text-gray-700 flex items-center gap-2">
                <FaArrowDown className="text-orange-500" /> Pending Withdrawals
              </h2>
              <Link to="/wallet" className="text-xs text-brand-500 font-medium hover:underline flex items-center gap-1">
                View all <FaEye />
              </Link>
            </div>
            <div className="divide-y divide-gray-50">
              {pendingWithdrawalsList.length === 0 ? (
                <EmptyState
                  icon={<FaCheckCircle />}
                  title="No pending withdrawals"
                  description="All withdrawal requests have been processed."
                />
              ) : (
                pendingWithdrawalsList.map((w) => (
                  <div key={w.id} className="p-4 hover:bg-gray-50 transition flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-10 h-10 rounded-lg bg-orange-100 flex items-center justify-center flex-shrink-0">
                        <FaUserCircle className="text-orange-600 text-lg" />
                      </div>
                      <div className="min-w-0">
                        <p className="font-medium text-sm text-gray-800 truncate">
                          {w.user?.full_name || 'Unknown User'}
                        </p>
                        <p className="text-xs text-gray-500 truncate">
                          {new Date(w.createdAt).toLocaleDateString('en-ET', { month: 'short', day: 'numeric' })}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <p className="text-sm font-bold text-orange-600">
                        {Number(w.amount).toLocaleString()} ETB
                      </p>
                      <Link to="/wallet">
                        <Button variant="success" size="sm">Review</Button>
                      </Link>
                    </div>
                  </div>
                ))
              )}
            </div>
          </Card>
        </div>

        {/* Pending Product Approvals + Recent Users */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6">
          {/* Pending Products */}
          <Card padding="none" className="overflow-hidden">
            <div className="p-4 sm:p-5 border-b border-gray-100 flex justify-between items-center">
              <h2 className="text-sm font-bold text-gray-700 flex items-center gap-2">
                <FaStore className="text-amber-500" /> Pending Product Approvals
              </h2>
              <Link to="/product-approvals" className="text-xs text-brand-500 font-medium hover:underline flex items-center gap-1">
                View all <FaEye />
              </Link>
            </div>
            <div className="divide-y divide-gray-50">
              {pendingProductsList.length === 0 ? (
                <EmptyState
                  icon={<FaCheckCircle />}
                  title="No products pending approval"
                  description="All product submissions have been reviewed."
                />
              ) : (
                pendingProductsList.map((p) => {
                  let img = null;
                  try {
                    const imgs = typeof p.image === 'string' ? JSON.parse(p.image) : (Array.isArray(p.image) ? p.image : []);
                    img = imgs[0];
                  } catch {}
                  return (
                    <div key={p.id} className="p-4 hover:bg-gray-50 transition flex items-center gap-3">
                      <div className="w-12 h-12 rounded-lg bg-gray-100 flex-shrink-0 overflow-hidden">
                        {img ? (
                          <img
                            src={img.startsWith('http') ? img : `${API_BASE_URL}${img}`}
                            alt={p.title}
                            className="w-full h-full object-cover"
                            onError={(e) => { e.target.style.display = 'none'; }}
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center">
                            <FaStore className="text-gray-300" />
                          </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-medium text-sm text-gray-800 truncate">{p.title}</p>
                        <p className="text-xs text-gray-500">
                          {Number(p.price).toLocaleString()} ETB • {p.subcat || 'N/A'}
                        </p>
                      </div>
                      <Link to="/product-approvals" className="flex-shrink-0">
                        <Button variant="warning" size="sm">Review</Button>
                      </Link>
                    </div>
                  );
                })
              )}
            </div>
          </Card>

          {/* Recent Users */}
          <Card padding="none" className="overflow-hidden">
            <div className="p-4 sm:p-5 border-b border-gray-100 flex justify-between items-center">
              <h2 className="text-sm font-bold text-gray-700 flex items-center gap-2">
                <FaUsers className="text-indigo-500" /> Recent Users
              </h2>
              <Link to="/users" className="text-xs text-brand-500 font-medium hover:underline flex items-center gap-1">
                View all <FaEye />
              </Link>
            </div>
            <div className="divide-y divide-gray-50">
              {recentUsers.length === 0 ? (
                <EmptyState
                  icon={<FaUsers />}
                  title="No users yet"
                  description="Newly registered users will show up here."
                />
              ) : (
                recentUsers.map((u) => (
                  <div key={u.id} className="p-4 hover:bg-gray-50 transition flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0">
                      <FaUserCircle className="text-gray-300 text-2xl flex-shrink-0" />
                      <div className="min-w-0">
                        <p className="font-medium text-sm text-gray-800 truncate">{u.full_name}</p>
                        <p className="text-xs text-gray-500 truncate">{u.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      <Badge variant={u.role === 'seller' ? 'purple' : 'default'} size="sm">
                        {u.role}
                      </Badge>
                      {u.wallet_balance > 0 && (
                        <span className="text-xs font-semibold text-brand-500">
                          {Number(u.wallet_balance).toLocaleString(undefined, { minimumFractionDigits: 0 })} ETB
                        </span>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </Card>
        </div>
      </div>
    </AdminLayout>
  );
};

export default Dashboard;
