import React, { useEffect, useState } from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  useNavigate,
  useLocation,
} from 'react-router-dom';
import Orders from './pages/Orders';
import AddProduct from './pages/AddProduct';
import ShopperPage from './pages/Shop';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import AdminOrders from './pages/Orders';
import CategoryForm from './pages/Addcategories';
import SubCategoryForm from './pages/SubCat';
import ProductList from './pages/productlist';
import RegisterShopper from './pages/shopper';
import AssignOrderForm from './pages/Approveorders';
import RegisterDeliveryBoy from './pages/deliveryboy';
import UpdateCatItem from './pages/updateCatItem';
import AssignedOrders from './pages/assignedOrders';
import SubCategoryList from './pages/updatesubcat';
import EditProduct from './pages/edit-product';
import Chat from './pages/chat';
import Telalaki from './pages/telalaki';
import Sellers from './pages/sellers';
import SellerProductManagement from './pages/sellerproduct';
import CombinedProductUOM from './pages/combined';
import { jwtDecode } from 'jwt-decode';
import UOMCreate from './pages/uom';
import NearbyDeliveryAssignment from './pages/NearbyDeliveryAssignment';
import ProductApprovals from './pages/ProductApprovals';
import ReferralDashboard from './pages/ReferralDashboard';
import WalletManagement from './pages/WalletManagement';
import UserManagement from './pages/UserManagement';

// Utility function to get the token from localStorage
export const getTokenFromLocalStorage = () => {
  return localStorage.getItem('adminToken');
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();

  // Function to check if user is authenticated
  const checkAuthentication = () => {
    const token = getTokenFromLocalStorage();

    if (!token) {
      setIsAuthenticated(false);
      return;
    }

    try {
      const decodedToken = jwtDecode(token);
      // Check token expiration
      if (decodedToken.exp && decodedToken.exp * 1000 < Date.now()) {
        localStorage.removeItem('adminToken');
        setIsAuthenticated(false);
        return;
      }
      setIsAuthenticated(true);
    } catch (error) {
      console.error('Invalid token:', error);
      localStorage.removeItem('adminToken');
      setIsAuthenticated(false);
    }
  };

  useEffect(() => {
    checkAuthentication();
  }, []);

  useEffect(() => {
    if (isAuthenticated === false && location.pathname !== '/login') {
      navigate('/login');
    } else if (isAuthenticated === true && location.pathname === '/login') {
      navigate('/dashboard');
    }
  }, [isAuthenticated, navigate, location.pathname]);

  useEffect(() => {
    const handleStorageChange = () => {
      checkAuthentication();
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  if (isAuthenticated === null) {
    return (
      <div className="flex justify-center items-center min-h-screen bg-gray-100">
        <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <Routes>
      {/* Dashboard */}
      <Route path="/dashboard" element={<Dashboard />} />

        {/* Orders */}
        <Route path="/" element={<AdminOrders />} />
        <Route path="/Approveorders" element={<AssignOrderForm />} />
        <Route path="/assigned" element={<AssignedOrders />} />
        <Route path="/nearby-delivery" element={<NearbyDeliveryAssignment />} />

        {/* Products */}
        <Route path="/addproduct" element={<AddProduct />} />
        <Route path="/productlist" element={<ProductList />} />
        <Route path="/edit-product/:id" element={<EditProduct />} />
        <Route path="/combined" element={<CombinedProductUOM />} />
        <Route path="/uom" element={<UOMCreate />} />
        <Route path="/product-approvals" element={<ProductApprovals />} />
        <Route path="/sellerproduct" element={<SellerProductManagement />} />

        {/* Users */}
        <Route path="/sellers" element={<Sellers />} />
        <Route path="/users" element={<UserManagement />} />
        <Route path="/shopper" element={<RegisterShopper />} />
        <Route path="/shop" element={<ShopperPage />} />
        <Route path="/deliveryboy" element={<RegisterDeliveryBoy />} />

        {/* Referral & Wallet */}
        <Route path="/referrals" element={<ReferralDashboard />} />
        <Route path="/wallet" element={<WalletManagement />} />

        {/* Categories */}
        <Route path="/addcategories" element={<CategoryForm />} />
        <Route path="/subcat" element={<SubCategoryForm />} />
        <Route path="/update" element={<UpdateCatItem />} />
        <Route path="/updatesubcat" element={<SubCategoryList />} />

        {/* Other */}
        <Route path="/telalaki" element={<Telalaki />} />
        <Route path="/chat" element={<Chat />} />
        <Route path="/login" element={<Login />} />
    </Routes>
  );
};

// Render the app into the root element
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <Router>
      <App />
    </Router>
  </React.StrictMode>
);
