/**
 * Referral Dashboard — Gebya Net Admin
 * Shows platform-wide referral statistics, top referrers, and referral payouts
 */

import React, { useState, useEffect, useCallback } from 'react';
import apiClient from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Select,
  Badge,
  Spinner,
  SearchBar,
  Table,
} from '../components/ui';
import { FaGift, FaUsers, FaCoins, FaChartBar } from 'react-icons/fa';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const ReferralDashboard = () => {
  const [stats, setStats] = useState({
    total_referrers: 0,
    total_referred_users: 0,
    total_referral_orders: 0,
    total_payouts: 0,
    pending_payouts: 0,
  });
  const [referrers, setReferrers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('referrals');

  const fetchStats = useCallback(async () => {
    try {
      setLoading(true);
      // Fetch referral stats from the unified endpoint
      const response = await apiClient.get('/api/user/referral/admin-stats');
      if (response.data) {
        setStats(response.data.stats || response.data);
        setReferrers(response.data.referrers || []);
      }
    } catch (err) {
      // Fallback: compute from user list
      try {
        const userResponse = await apiClient.get('/api/user', {
          params: { is_referrer: true, limit: 100 },
        });
        const users = userResponse.data.users || userResponse.data || [];
        const referrersList = users
          .filter((u) => u.referral_code)
          .map((u) => ({
            id: u.id,
            full_name: u.full_name,
            email: u.email,
            referral_code: u.referral_code,
            referred_count: u.referred_count || 0,
            referral_earnings: parseFloat(u.referral_earnings || 0),
            wallet_balance: parseFloat(u.wallet_balance || 0),
            role: u.role,
            seller_level: u.seller_level,
          }));
        setReferrers(referrersList);
        setStats({
          total_referrers: referrersList.length,
          total_referred_users: referrersList.reduce((sum, r) => sum + (r.referred_count || 0), 0),
          total_referral_orders: 0,
          total_payouts: referrersList.reduce((sum, r) => sum + r.referral_earnings, 0),
          pending_payouts: 0,
        });
      } catch (err2) {
        toast.error('Failed to load referral data');
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  const filteredReferrers = referrers
    .filter(
      (r) =>
        r.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.referral_code?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      switch (sortBy) {
        case 'referrals':
          return (b.referred_count || 0) - (a.referred_count || 0);
        case 'earnings':
          return (b.referral_earnings || 0) - (a.referral_earnings || 0);
        case 'name':
          return (a.full_name || '').localeCompare(b.full_name || '');
        default:
          return 0;
      }
    });

  const StatCard = ({ icon, label, value, color }) => (
    <Card padding="md" hover className="flex items-center gap-3">
      <div className={`w-11 h-11 sm:w-12 sm:h-12 rounded-lg flex items-center justify-center ${color} shadow-sm`}>
        {icon}
      </div>
      <div>
        <p className="text-xs sm:text-sm text-gray-500 font-medium">{label}</p>
        <p className="text-xl sm:text-2xl font-bold text-gray-800">{value}</p>
      </div>
    </Card>
  );

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading referral data..." />
        </div>
      </AdminLayout>
    );
  }

  const columns = [
    {
      header: 'User',
      key: 'full_name',
      render: (r) => (
        <div>
          <p className="font-medium text-sm text-gray-800">{r.full_name}</p>
          <p className="text-xs text-gray-500">{r.email}</p>
        </div>
      ),
    },
    {
      header: 'Referral Code',
      key: 'referral_code',
      render: (r) => (
        <Badge variant="blue" size="sm" className="font-mono font-bold">
          {r.referral_code}
        </Badge>
      ),
    },
    {
      header: 'Role',
      key: 'role',
      render: (r) => (
        <Badge variant={r.role === 'seller' ? 'purple' : 'default'} size="sm">
          {r.role}
          {r.seller_level ? ` (${r.seller_level})` : ''}
        </Badge>
      ),
    },
    {
      header: 'Referred',
      key: 'referred_count',
      className: 'text-center',
      render: (r) => <span className="font-medium">{r.referred_count || 0}</span>,
    },
    {
      header: 'Earnings',
      key: 'referral_earnings',
      className: 'text-right',
      render: (r) => (
        <span className="font-bold text-brand-500">
          {Number(r.referral_earnings || 0).toFixed(2)} ETB
        </span>
      ),
    },
    {
      header: 'Wallet',
      key: 'wallet_balance',
      className: 'text-right',
      render: (r) => (
        <span className="font-medium text-yellow-600">
          {Number(r.wallet_balance || 0).toFixed(2)} ETB
        </span>
      ),
    },
  ];

  return (
    <AdminLayout>
      <div>
        <PageHeader
          icon={<FaGift />}
          title="Referral Dashboard"
          subtitle="Platform-wide referral statistics and top referrers"
        />

        {/* Stats Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <StatCard
            icon={<FaUsers className="text-white text-lg sm:text-xl" />}
            label="Total Referrers"
            value={stats.total_referrers}
            color="bg-brand-500"
          />
          <StatCard
            icon={<FaUsers className="text-white text-lg sm:text-xl" />}
            label="Referred Users"
            value={stats.total_referred_users}
            color="bg-indigo-600"
          />
          <StatCard
            icon={<FaChartBar className="text-white text-lg sm:text-xl" />}
            label="Referral Orders"
            value={stats.total_referral_orders}
            color="bg-purple-600"
          />
          <StatCard
            icon={<FaCoins className="text-white text-lg sm:text-xl" />}
            label="Total Payouts"
            value={`${Number(stats.total_payouts || 0).toFixed(2)} ETB`}
            color="bg-yellow-500"
          />
        </div>

        {/* Filters */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-4">
          <SearchBar
            value={searchTerm}
            onChange={setSearchTerm}
            placeholder="Search by name, email, or code..."
            className="max-w-md"
          />
          <Select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            placeholder=""
            options={[
              { value: 'referrals', label: 'Sort by Referrals' },
              { value: 'earnings', label: 'Sort by Earnings' },
              { value: 'name', label: 'Sort by Name' },
            ]}
            className="sm:w-56"
          />
        </div>

        {/* Referrers Table */}
        <Table
          columns={columns}
          data={filteredReferrers}
          emptyMessage="No referrers found"
        />
      </div>
    </AdminLayout>
  );
};

export default ReferralDashboard;
