"use client"

import { useState, useEffect } from "react"
import { FaBoxOpen, FaPlus, FaFilter, FaThLarge, FaList, FaEdit, FaTrashAlt } from "react-icons/fa"
import apiClient from '../config/api'
import { ToastContainer, toast } from "react-toastify"
import "react-toastify/dist/ReactToastify.css"
import AdminLayout from '../components/AdminLayout'
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  Alert,
  Modal,
  Spinner,
  EmptyState,
  SearchBar,
  Table,
} from '../components/ui'

const stockOptions = [
  { value: "in_stock", label: "In Stock" },
  { value: "out_of_stock", label: "Out of Stock" },
  { value: "limited_stock", label: "Limited Stock" },
]

const productTypeOptions = [
  { value: "retail", label: "Retail" },
  { value: "wholesale", label: "Wholesale" },
  { value: "import", label: "Import" },
  { value: "export", label: "Export" },
]

const sortByOptions = [
  { value: "title", label: "Name" },
  { value: "price", label: "Price" },
  { value: "created_at", label: "Date" },
  { value: "stock", label: "Stock" },
]

// Map stock status to Badge variant
const stockBadgeVariant = (stock) => {
  switch (stock) {
    case "in_stock":
      return "green"
    case "out_of_stock":
      return "red"
    case "limited_stock":
      return "yellow"
    default:
      return "default"
  }
}

// Map product_type to Badge variant
const productTypeBadgeVariant = (productType) => {
  switch ((productType || "").toLowerCase()) {
    case "retail":
      return "blue"
    case "wholesale":
      return "yellow"
    case "import":
      return "green"
    case "export":
      return "purple"
    default:
      return "default"
  }
}

// Map seller_level to Badge variant
const sellerLevelBadgeVariant = (sellerLevel) => {
  const level = (sellerLevel || "").toString().toLowerCase()
  if (level.includes("importer")) return "green"
  if (level.includes("exporter")) return "purple"
  if (level.includes("reseller")) return "blue"
  return "default"
}

const ProductList = () => {
  const [products, setProducts] = useState([])
  const [filteredProducts, setFilteredProducts] = useState([])
  const [loading, setLoading] = useState(false)
  const [searchTerm, setSearchTerm] = useState("")
  const [filterCategory, setFilterCategory] = useState("")
  const [filterStock, setFilterStock] = useState("")
  const [filterProductType, setFilterProductType] = useState("")
  const [sortBy, setSortBy] = useState("title")
  const [sortOrder, setSortOrder] = useState("asc")
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage] = useState(10)
  const [categories, setCategories] = useState([])
  const [viewMode, setViewMode] = useState("cards") // 'cards' or 'table'
  const [showFilters, setShowFilters] = useState(false)
  const [productToDelete, setProductToDelete] = useState(null)
  const [deleting, setDeleting] = useState(false)

  // Fetch all products and categories
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      try {
        const [productsRes, categoriesRes] = await Promise.all([
          apiClient.get('/api/prod'),
          apiClient.get('/api/catitem'),
        ])
        setProducts(productsRes.data)
        setFilteredProducts(productsRes.data)
        setCategories(categoriesRes.data)
      } catch (error) {
        console.error("Error fetching data:", error)
        toast.error("Failed to fetch products.")
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  // Filter and search products
  useEffect(() => {
    let filtered = [...products]

    // Search by ID, title, or brand
    if (searchTerm) {
      filtered = filtered.filter(
        (product) =>
          product.id.toString().includes(searchTerm.toLowerCase()) ||
          product.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          (product.brand && product.brand.toLowerCase().includes(searchTerm.toLowerCase())),
      )
    }

    // Filter by category
    if (filterCategory) {
      filtered = filtered.filter((product) => product.catItems === filterCategory)
    }

    // Filter by stock status
    if (filterStock) {
      filtered = filtered.filter((product) => product.stock === filterStock)
    }

    // Filter by product_type
    if (filterProductType) {
      filtered = filtered.filter(
        (product) =>
          (product.product_type || "").toLowerCase() === filterProductType.toLowerCase(),
      )
    }

    // Sort products
    filtered.sort((a, b) => {
      let aValue = a[sortBy]
      let bValue = b[sortBy]

      // Handle different data types
      if (sortBy === "price") {
        aValue = Number.parseFloat(aValue) || 0
        bValue = Number.parseFloat(bValue) || 0
      } else if (sortBy === "created_at") {
        aValue = new Date(aValue)
        bValue = new Date(bValue)
      } else {
        aValue = aValue?.toString().toLowerCase() || ""
        bValue = bValue?.toString().toLowerCase() || ""
      }

      if (sortOrder === "asc") {
        return aValue > bValue ? 1 : -1
      } else {
        return aValue < bValue ? 1 : -1
      }
    })

    setFilteredProducts(filtered)
    setCurrentPage(1) // Reset to first page when filtering
  }, [products, searchTerm, filterCategory, filterStock, filterProductType, sortBy, sortOrder])

  // Delete product
  const handleDelete = async () => {
    if (!productToDelete) return
    setDeleting(true)
    try {
      await apiClient.delete(`/api/prod/${productToDelete.id}`)
      setProducts(products.filter((product) => product.id !== productToDelete.id))
      toast.success("Product deleted successfully.")
      setProductToDelete(null)
    } catch (error) {
      console.error("Error deleting product:", error)
      toast.error("Failed to delete product.")
    } finally {
      setDeleting(false)
    }
  }

  // Get current page products
  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const currentProducts = filteredProducts.slice(indexOfFirstItem, indexOfLastItem)
  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage)

  // Change page
  const paginate = (pageNumber) => setCurrentPage(pageNumber)

  // Get category name
  const getCategoryName = (categoryId) => {
    const category = categories.find((cat) => cat.id === categoryId)
    return category ? category.name : "Unknown"
  }

  // Format date
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    })
  }

  const categoryOptions = categories.map((category) => ({
    value: category.id,
    label: category.name,
  }))

  // Table columns for table view
  const tableColumns = [
    {
      header: "Product",
      key: "title",
      render: (product) => (
        <div>
          <div className="font-medium text-gray-900 truncate max-w-32">{product.title}</div>
          <div className="text-xs text-gray-500">#{product.id}</div>
          {product.brand && <div className="text-xs text-gray-500">{product.brand}</div>}
        </div>
      ),
    },
    {
      header: "Price",
      key: "price",
      render: (product) => (
        <span className="font-medium text-gray-900 whitespace-nowrap">
          ${Number.parseFloat(product.price || 0).toFixed(2)}
        </span>
      ),
    },
    {
      header: "Stock",
      key: "stock",
      render: (product) => (
        <Badge variant={stockBadgeVariant(product.stock)} size="sm">
          {product.stock?.replace("_", " ").toUpperCase() || "UNKNOWN"}
        </Badge>
      ),
    },
    {
      header: "Type",
      key: "product_type",
      render: (product) => (
        <Badge variant={productTypeBadgeVariant(product.product_type)} size="sm">
          {(product.product_type || "N/A").charAt(0).toUpperCase() + (product.product_type || "").slice(1)}
        </Badge>
      ),
    },
    {
      header: "Seller Level",
      key: "seller_level",
      render: (product) =>
        product.seller_level ? (
          <Badge variant={sellerLevelBadgeVariant(product.seller_level)} size="sm">
            {product.seller_level}
          </Badge>
        ) : (
          <span className="text-xs text-gray-400">—</span>
        ),
    },
    {
      header: "Actions",
      key: "actions",
      render: (product) => (
        <div className="flex gap-2 justify-center">
          <a href={`/edit-product/${product.id}`}>
            <Button variant="primary" size="sm" icon={<FaEdit />}>
              Edit
            </Button>
          </a>
          <Button
            variant="danger"
            size="sm"
            icon={<FaTrashAlt />}
            onClick={() => setProductToDelete(product)}
          >
            Delete
          </Button>
        </div>
      ),
    },
  ]

  if (loading) {
    return (
      <AdminLayout>
        <div className="p-4 sm:p-6">
          <PageHeader
            icon={<FaBoxOpen />}
            title="Products"
            subtitle="Manage your product catalog"
          />
          <Card padding="lg">
            <Spinner size="lg" label="Loading products..." />
          </Card>
        </div>
      </AdminLayout>
    )
  }

  const hasActiveFilters = searchTerm || filterCategory || filterStock || filterProductType

  return (
    <AdminLayout>
      <ToastContainer position="top-center" />

      <div className="p-4 sm:p-6">
        <PageHeader
          icon={<FaBoxOpen />}
          title="Products"
          subtitle={`${filteredProducts.length} of ${products.length} products`}
          actions={
            <>
              {/* View Mode Toggle */}
              <div className="flex bg-gray-100 rounded-lg p-1">
                <button
                  onClick={() => setViewMode("cards")}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors flex items-center gap-1.5 ${
                    viewMode === "cards" ? "bg-brand-500 text-white" : "text-gray-600"
                  }`}
                >
                  <FaThLarge /> Cards
                </button>
                <button
                  onClick={() => setViewMode("table")}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors flex items-center gap-1.5 ${
                    viewMode === "table" ? "bg-brand-500 text-white" : "text-gray-600"
                  }`}
                >
                  <FaList /> Table
                </button>
              </div>

              {/* Filter Toggle */}
              <Button
                variant={showFilters ? "primary" : "outline"}
                size="md"
                icon={<FaFilter />}
                onClick={() => setShowFilters(!showFilters)}
              >
                Filters
              </Button>

              {/* Add Product */}
              <a href="/add-product">
                <Button variant="primary" size="md" icon={<FaPlus />}>
                  Add Product
                </Button>
              </a>
            </>
          }
        />

        {/* Search Bar */}
        <Card padding="md" className="mb-4">
          <SearchBar
            value={searchTerm}
            onChange={setSearchTerm}
            placeholder="Search by ID, name, or brand..."
          />
        </Card>

        {/* Collapsible Filters */}
        {showFilters && (
          <Card padding="md" className="mb-6">
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="flex-1">
                <Select
                  label="Category"
                  value={filterCategory}
                  onChange={(e) => setFilterCategory(e.target.value)}
                  options={categoryOptions}
                  placeholder="All Categories"
                />
              </div>

              <div className="flex-1">
                <Select
                  label="Stock"
                  value={filterStock}
                  onChange={(e) => setFilterStock(e.target.value)}
                  options={stockOptions}
                  placeholder="All Stock Status"
                />
              </div>

              <div className="flex-1">
                <Select
                  label="Product Type"
                  value={filterProductType}
                  onChange={(e) => setFilterProductType(e.target.value)}
                  options={productTypeOptions}
                  placeholder="All Types"
                />
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-3 mt-3">
              <div className="flex-1">
                <Select
                  label="Sort By"
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  options={sortByOptions}
                  placeholder={null}
                />
              </div>
              <div className="flex items-end">
                <Button
                  variant="outline"
                  size="md"
                  onClick={() => setSortOrder(sortOrder === "asc" ? "desc" : "asc")}
                  title={`Sort ${sortOrder === "asc" ? "Descending" : "Ascending"}`}
                >
                  {sortOrder === "asc" ? "↑ Ascending" : "↓ Descending"}
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Card View - responsive grid */}
        {viewMode === "cards" && (
          <>
            {currentProducts.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {currentProducts.map((product) => (
                  <Card key={product.id} padding="md" className="flex flex-col">
                    <div className="flex justify-between items-start mb-3">
                      <div className="flex-1 min-w-0">
                        <h3 className="font-semibold text-gray-900 text-sm truncate">{product.title}</h3>
                        {product.brand && <p className="text-xs text-gray-500 mt-1">{product.brand}</p>}
                      </div>
                      <div className="ml-3 text-right shrink-0">
                        <div className="text-lg font-bold text-gray-900">
                          ${Number.parseFloat(product.price || 0).toFixed(2)}
                        </div>
                        <div className="text-xs text-gray-500">#{product.id}</div>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2 mb-3">
                      <Badge variant={stockBadgeVariant(product.stock)} size="sm">
                        {product.stock?.replace("_", " ").toUpperCase() || "UNKNOWN"}
                      </Badge>
                      <Badge variant="indigo" size="sm">
                        {getCategoryName(product.catItems)}
                      </Badge>
                      <Badge variant={productTypeBadgeVariant(product.product_type)} size="sm">
                        {(product.product_type || "N/A").charAt(0).toUpperCase() + (product.product_type || "").slice(1)}
                      </Badge>
                      {product.seller_level && (
                        <Badge variant={sellerLevelBadgeVariant(product.seller_level)} size="sm">
                          {product.seller_level}
                        </Badge>
                      )}
                      {product.variations?.length > 0 && (
                        <Badge variant="purple" size="sm">
                          {product.variations.length} variations
                        </Badge>
                      )}
                    </div>

                    <div className="flex justify-between items-center mt-auto pt-2">
                      <div className="text-xs text-gray-500">
                        {product.created_at ? formatDate(product.created_at) : "N/A"}
                      </div>
                      <div className="flex gap-2">
                        <a href={`/edit-product/${product.id}`}>
                          <Button variant="primary" size="sm" icon={<FaEdit />}>
                            Edit
                          </Button>
                        </a>
                        <Button
                          variant="danger"
                          size="sm"
                          icon={<FaTrashAlt />}
                          onClick={() => setProductToDelete(product)}
                        >
                          Delete
                        </Button>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            ) : (
              <Card padding="lg">
                <EmptyState
                  icon={<FaBoxOpen />}
                  title="No products found"
                  description={
                    hasActiveFilters
                      ? "No products found matching your criteria."
                      : "No products available yet."
                  }
                  action={
                    <a href="/add-product">
                      <Button variant="primary" size="md" icon={<FaPlus />}>
                        Add Product
                      </Button>
                    </a>
                  }
                />
              </Card>
            )}
          </>
        )}

        {/* Table View */}
        {viewMode === "table" && (
          <Table
            columns={tableColumns}
            data={currentProducts}
            emptyMessage={
              hasActiveFilters
                ? "No products found matching your criteria."
                : "No products available."
            }
          />
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-6">
            <div className="flex justify-center items-center gap-2 mb-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => paginate(currentPage - 1)}
                disabled={currentPage === 1}
              >
                ‹
              </Button>

              <span className="px-3 py-2 text-sm text-gray-700">
                {currentPage} of {totalPages}
              </span>

              <Button
                variant="outline"
                size="sm"
                onClick={() => paginate(currentPage + 1)}
                disabled={currentPage === totalPages}
              >
                ›
              </Button>
            </div>

            {/* Page Jump for larger screens */}
            <div className="hidden sm:flex justify-center gap-1">
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                let pageNum
                if (totalPages <= 5) {
                  pageNum = i + 1
                } else if (currentPage <= 3) {
                  pageNum = i + 1
                } else if (currentPage >= totalPages - 2) {
                  pageNum = totalPages - 4 + i
                } else {
                  pageNum = currentPage - 2 + i
                }

                return (
                  <Button
                    key={pageNum}
                    variant={currentPage === pageNum ? "primary" : "outline"}
                    size="sm"
                    onClick={() => paginate(pageNum)}
                  >
                    {pageNum}
                  </Button>
                )
              })}
            </div>
          </div>
        )}
      </div>

      {/* Delete Confirmation Modal */}
      <Modal
        open={!!productToDelete}
        onClose={() => setProductToDelete(null)}
        title="Delete Product"
        size="sm"
        footer={
          <div className="flex justify-end gap-2">
            <Button
              variant="secondary"
              size="md"
              onClick={() => setProductToDelete(null)}
              disabled={deleting}
            >
              Cancel
            </Button>
            <Button
              variant="danger"
              size="md"
              icon={<FaTrashAlt />}
              loading={deleting}
              onClick={handleDelete}
            >
              Delete
            </Button>
          </div>
        }
      >
        <Alert type="warning" title="Are you sure?">
          Are you sure you want to delete this product? This action cannot be undone.
        </Alert>
        {productToDelete && (
          <div className="mt-4 p-3 bg-gray-50 rounded-lg">
            <p className="font-medium text-gray-900 text-sm">{productToDelete.title}</p>
            <p className="text-xs text-gray-500 mt-1">#{productToDelete.id}</p>
          </div>
        )}
      </Modal>
    </AdminLayout>
  )
}

export default ProductList
