import React from 'react';

const PageHeader = ({ icon = null, title, subtitle = null, actions = null, breadcrumb = null }) => {
  return (
    <div className="mb-6">
      {breadcrumb && (
        <nav className="mb-2 text-xs text-gray-500">
          {breadcrumb}
        </nav>
      )}
      <div className="flex items-start justify-between flex-wrap gap-4">
        <div className="flex items-center gap-3">
          {icon && (
            <div className="w-10 h-10 rounded-lg bg-brand-50 flex items-center justify-center text-brand-600 text-base flex-shrink-0">
              {icon}
            </div>
          )}
          <div>
            <h1 className="text-lg sm:text-xl font-bold text-gray-900 leading-tight">{title}</h1>
            {subtitle && <p className="text-sm text-gray-500 mt-0.5">{subtitle}</p>}
          </div>
        </div>
        {actions && <div className="flex items-center gap-2 flex-wrap">{actions}</div>}
      </div>
    </div>
  );
};

export default PageHeader;
