import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  AiOutlineMore,
  AiOutlineClose,
} from "react-icons/ai";
import { BsBoxSeam } from "react-icons/bs";
import {
  FaBox,
  FaProductHunt,
  FaCheck,
  FaUsers,
  FaUser,
  FaMapMarkerAlt,
  FaGift,
  FaWallet,
  FaCommentDots,
  FaStore,
  FaTools,
  FaFileAlt,
  FaCar,
  FaTachometerAlt,
} from "react-icons/fa";

const BottomNav = () => {
  const [showMoreMenu, setShowMoreMenu] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const coreItems = [
    { id: "dashboard", label: "Home", icon: <FaTachometerAlt />, route: "/dashboard" },
    { id: "orders", label: "Orders", icon: <BsBoxSeam />, route: "/" },
    { id: "products", label: "Products", icon: <FaProductHunt />, route: "/productlist" },
    { id: "approved", label: "Approve", icon: <FaCheck />, route: "/product-approvals" },
  ];

  const moreItems = [
    { id: "add-product", label: "Add Product", icon: <FaBox />, route: "/addproduct" },
    { id: "sellers", label: "Sellers", icon: <FaUser />, route: "/sellers" },
    { id: "users", label: "Users", icon: <FaUsers />, route: "/users" },
    { id: "referrals", label: "Referrals", icon: <FaGift />, route: "/referrals" },
    { id: "wallet", label: "Wallet", icon: <FaWallet />, route: "/wallet" },
    { id: "nearby-delivery", label: "Nearby Delivery", icon: <FaMapMarkerAlt />, route: "/nearby-delivery" },
    { id: "telalaki", label: "Telalaki", icon: <FaCar />, route: "/telalaki" },
    { id: "add-categories", label: "Add Category", icon: <FaStore />, route: "/addcategories" },
    { id: "shop", label: "Shop Locations", icon: <FaStore />, route: "/shop" },
    { id: "assigned", label: "Assigned Orders", icon: <FaFileAlt />, route: "/assigned" },
    { id: "deliveryboy", label: "Delivery Boy", icon: <FaUsers />, route: "/deliveryboy" },
    { id: "chat", label: "Chat", icon: <FaCommentDots />, route: "/chat" },
    { id: "uom", label: "UOM", icon: <FaTools />, route: "/uom" },
  ];

  const handleNavigation = (route) => {
    navigate(route);
    setShowMoreMenu(false);
  };

  const handleMoreClick = () => setShowMoreMenu(!showMoreMenu);

  const isActive = (route) => location.pathname === route;

  return (
    <>
      {/* More Menu Modal */}
      {showMoreMenu && (
        <div className="fixed inset-0 bg-black/50 z-30 flex items-end lg:hidden" onClick={() => setShowMoreMenu(false)}>
          <div
            className="bg-white w-full rounded-t-lg shadow-md max-h-[75vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Modal Header */}
            <div className="flex justify-between items-center px-5 py-4 border-b border-gray-200 sticky top-0 bg-white z-10">
              <h3 className="text-base font-semibold text-gray-800">More Options</h3>
              <button
                onClick={() => setShowMoreMenu(false)}
                className="p-2 rounded-md hover:bg-gray-100 transition-colors"
              >
                <AiOutlineClose className="text-lg text-gray-600" />
              </button>
            </div>

            {/* More Items Grid */}
            <div className="p-4">
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                {moreItems.map((item) => (
                  <button
                    key={item.id}
                    className={`flex flex-col items-center justify-center p-3 rounded-lg transition-all ${
                      isActive(item.route)
                        ? "bg-brand-50 text-brand-600"
                        : "bg-gray-50 text-gray-600 hover:bg-brand-50 hover:text-brand-600"
                    }`}
                    onClick={() => handleNavigation(item.route)}
                  >
                    <div className="text-xl mb-1.5">{item.icon}</div>
                    <span className="text-xs font-medium text-center leading-tight">
                      {item.label}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Navigation Bar — mobile only */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 flex items-center h-16 z-20">
        <div className="flex justify-around items-center w-full">
          {/* Core Navigation Items */}
          {coreItems.map((item) => (
            <button
              key={item.id}
              className={`flex flex-col items-center justify-center transition-all ${
                isActive(item.route)
                  ? "text-brand-600"
                  : "text-gray-500 hover:text-brand-600"
              }`}
              onClick={() => handleNavigation(item.route)}
              aria-label={item.label}
            >
              <div className={`text-xl mb-1 ${isActive(item.route) ? "scale-110" : ""} transition-transform`}>
                {item.icon}
              </div>
              <span className={`text-[10px] font-medium ${isActive(item.route) ? "font-semibold" : ""}`}>
                {item.label}
              </span>
            </button>
          ))}

          {/* More Button */}
          <button
            className={`flex flex-col items-center justify-center transition-all ${
              showMoreMenu ? "text-brand-600" : "text-gray-500 hover:text-brand-600"
            }`}
            onClick={handleMoreClick}
            aria-label="More options"
          >
            <div className={`text-xl mb-1 transition-transform ${showMoreMenu ? "rotate-45" : ""}`}>
              <AiOutlineMore />
            </div>
            <span className={`text-[10px] font-medium ${showMoreMenu ? "font-semibold" : ""}`}>
              More
            </span>
          </button>
        </div>
      </nav>
    </>
  );
};

export default BottomNav;
