/**
 * Wallet Management — Gebya Net Admin (Advanced)
 * View user wallets, approve/decline withdrawal requests.
 * Uses unified backend endpoints:
 *   GET  /api/withdraw              — all withdrawals (with stats)
 *   PUT  /api/withdraw/:id/status   — approve/decline (body: { status: 'Approved' | 'Declined' })
 */

import React, { useState, useEffect, useCallback } from 'react';
import apiClient from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Select,
  Badge,
  statusVariant,
  Spinner,
  SearchBar,
  Table,
} from '../components/ui';
import {
  FaWallet, FaCoins, FaArrowDown, FaArrowUp,
  FaCheck, FaTimes, FaClock, FaUserCircle, FaFilter,
} from 'react-icons/fa';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const WalletManagement = () => {
  const [users, setUsers] = useState([]);
  const [withdrawals, setWithdrawals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('withdrawals');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [actionLoading, setActionLoading] = useState(null);
  const [stats, setStats] = useState({
    total_balance: 0,
    pending_withdrawals: 0,
    approved_withdrawals: 0,
    total_withdrawn: 0,
  });

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);

      // Fetch users with wallet info in parallel with withdrawals
      const [usersRes, wdRes] = await Promise.allSettled([
        apiClient.get('/api/user', { params: { limit: 200 } }),
        apiClient.get('/api/withdraw'),
      ]);

      // Users
      if (usersRes.status === 'fulfilled') {
        const usersData = usersRes.value.data.users || usersRes.value.data || [];
        // Only show users who have a non-zero wallet or referral earnings
        const walletUsers = usersData.filter(
          (u) => parseFloat(u.wallet_balance || 0) > 0 || parseFloat(u.referral_earnings || 0) > 0
        );
        setUsers(walletUsers);
      }

      // Withdrawals — backend returns { success, stats, withdrawals }
      if (wdRes.status === 'fulfilled') {
        const wdData = wdRes.value.data.withdrawals || [];
        setWithdrawals(wdData);
        const apiStats = wdRes.value.data.stats || {};
        setStats({
          total_balance: parseFloat(apiStats.total_balance || 0),
          pending_withdrawals: parseFloat(apiStats.pending_withdrawals || 0),
          approved_withdrawals: parseFloat(apiStats.approved_withdrawals || 0),
          total_withdrawn: parseFloat(apiStats.total_withdrawn || 0),
        });
      } else {
        setWithdrawals([]);
      }
    } catch (err) {
      toast.error('Failed to load wallet data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Approve / Decline — backend uses capitalized status values
  const handleWithdrawalAction = async (id, newStatus) => {
    setActionLoading(id);
    try {
      await apiClient.put(`/api/withdraw/${id}/status`, { status: newStatus });
      toast.success(`Withdrawal ${newStatus.toLowerCase()} successfully`);
      fetchData();
    } catch (err) {
      toast.error(`Failed to ${newStatus.toLowerCase()} withdrawal`);
    } finally {
      setActionLoading(null);
    }
  };

  const filteredUsers = users.filter(
    (u) =>
      u.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredWithdrawals = withdrawals.filter((w) => {
    const matchesSearch =
      (w.user?.full_name || w.user_name || '')?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (w.user?.email || w.user_email || '')?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || (w.status || '').toLowerCase() === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const pendingCount = withdrawals.filter((w) => w.status === 'Pending').length;

  const fmt = (n) =>
    Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const StatCard = ({ icon, label, value, sublabel, color }) => (
    <Card padding="md" hover>
      <div className="flex items-start justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-11 h-11 sm:w-12 sm:h-12 rounded-lg flex items-center justify-center ${color} shadow-sm`}>
            {icon}
          </div>
          <div>
            <p className="text-xs sm:text-sm text-gray-500 font-medium">{label}</p>
            <p className="text-xl sm:text-2xl font-bold text-gray-800">{value}</p>
            {sublabel && <p className="text-xs text-gray-400 mt-0.5">{sublabel}</p>}
          </div>
        </div>
      </div>
    </Card>
  );

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center min-h-[60vh]">
          <Spinner size="lg" label="Loading wallet data..." />
        </div>
      </AdminLayout>
    );
  }

  const withdrawalColumns = [
    {
      header: 'User',
      key: 'user',
      render: (w) => (
        <div className="flex items-center gap-2">
          <FaUserCircle className="text-gray-300 text-xl" />
          <div>
            <p className="font-medium text-sm">{w.user?.full_name || w.user_name || 'Unknown'}</p>
            <p className="text-xs text-gray-500">{w.user?.email || w.user_email || ''}</p>
          </div>
        </div>
      ),
    },
    {
      header: 'Amount',
      key: 'amount',
      className: 'text-right',
      render: (w) => (
        <span className="font-bold text-brand-500">{fmt(w.amount)} ETB</span>
      ),
    },
    {
      header: 'Balance Before',
      key: 'balance',
      render: (w) => (
        <span className="text-gray-600">
          {w.user?.wallet_balance != null ? `${fmt(w.user.wallet_balance)} ETB` : '-'}
        </span>
      ),
    },
    {
      header: 'Status',
      key: 'status',
      render: (w) => (
        <Badge variant={statusVariant(w.status)} size="sm">
          {w.status}
        </Badge>
      ),
    },
    {
      header: 'Date',
      key: 'createdAt',
      render: (w) => (
        <span className="text-gray-500">
          {new Date(w.createdAt || w.created_at).toLocaleDateString('en-ET', {
            year: 'numeric', month: 'short', day: 'numeric',
          })}
        </span>
      ),
    },
    {
      header: 'Actions',
      key: 'actions',
      className: 'text-center',
      render: (w) =>
        w.status === 'Pending' ? (
          <div className="flex justify-center gap-2">
            <Button
              size="sm"
              variant="success"
              icon={actionLoading === w.id ? <FaClock className="animate-spin" /> : <FaCheck />}
              loading={actionLoading === w.id}
              onClick={() => handleWithdrawalAction(w.id, 'Approved')}
            >
              Approve
            </Button>
            <Button
              size="sm"
              variant="danger"
              icon={<FaTimes />}
              loading={actionLoading === w.id}
              onClick={() => handleWithdrawalAction(w.id, 'Declined')}
            >
              Decline
            </Button>
          </div>
        ) : (
          <span className="text-xs text-gray-400">—</span>
        ),
    },
  ];

  const walletColumns = [
    {
      header: 'User',
      key: 'full_name',
      render: (u) => (
        <div className="flex items-center gap-2">
          <FaUserCircle className="text-gray-300 text-xl" />
          <div>
            <p className="font-medium text-sm">{u.full_name}</p>
            <p className="text-xs text-gray-500">{u.email}</p>
          </div>
        </div>
      ),
    },
    {
      header: 'Role',
      key: 'role',
      render: (u) => (
        <Badge variant={u.role === 'seller' ? 'purple' : 'default'} size="sm">
          {u.role}{u.seller_level ? ` (${u.seller_level})` : ''}
        </Badge>
      ),
    },
    {
      header: 'Wallet Balance',
      key: 'wallet_balance',
      className: 'text-right',
      render: (u) => <span className="font-bold text-brand-500">{fmt(u.wallet_balance)} ETB</span>,
    },
    {
      header: 'Referral Earnings',
      key: 'referral_earnings',
      className: 'text-right',
      render: (u) => <span className="font-semibold text-amber-600">{fmt(u.referral_earnings)} ETB</span>,
    },
    {
      header: 'Referral Code',
      key: 'referral_code',
      className: 'text-right',
      render: (u) =>
        u.referral_code ? (
          <Badge variant="blue" size="sm" className="font-mono">{u.referral_code}</Badge>
        ) : (
          <span className="text-gray-400">-</span>
        ),
    },
  ];

  return (
    <AdminLayout>
      <div>
        <PageHeader
          icon={<FaWallet />}
          title="Wallet Management"
          subtitle={
            pendingCount > 0 ? (
              <span className="inline-flex items-center gap-1">
                User wallet balances and withdrawal requests
                <Badge variant="yellow" size="sm" className="ml-2">
                  <FaClock className="mr-1" /> {pendingCount} pending
                </Badge>
              </span>
            ) : (
              'User wallet balances and withdrawal requests'
            )
          }
        />

        {/* Stats */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-6">
          <StatCard
            icon={<FaCoins className="text-white text-lg" />}
            label="Total Balance"
            value={`${fmt(stats.total_balance)} ETB`}
            sublabel="Across all users"
            color="bg-brand-500"
          />
          <StatCard
            icon={<FaArrowDown className="text-white text-lg" />}
            label="Pending"
            value={`${fmt(stats.pending_withdrawals)} ETB`}
            sublabel={`${pendingCount} requests`}
            color="bg-amber-500"
          />
          <StatCard
            icon={<FaArrowUp className="text-white text-lg" />}
            label="Approved"
            value={`${fmt(stats.approved_withdrawals)} ETB`}
            sublabel="Total approved"
            color="bg-green-500"
          />
          <StatCard
            icon={<FaCoins className="text-white text-lg" />}
            label="Total Withdrawn"
            value={`${fmt(stats.total_withdrawn)} ETB`}
            sublabel="All time"
            color="bg-purple-500"
          />
        </div>

        {/* Tabs */}
        <div className="flex gap-1 mb-4 bg-gray-100 p-1 rounded-lg w-fit">
          <button
            className={`px-4 py-2 text-sm font-medium rounded-lg transition flex items-center gap-2 ${
              activeTab === 'withdrawals'
                ? 'bg-white text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700'
            }`}
            onClick={() => setActiveTab('withdrawals')}
          >
            <FaArrowDown /> Withdrawals
            {pendingCount > 0 && (
              <span className="px-1.5 py-0.5 bg-amber-500 text-white rounded-full text-xs">{pendingCount}</span>
            )}
          </button>
          <button
            className={`px-4 py-2 text-sm font-medium rounded-lg transition flex items-center gap-2 ${
              activeTab === 'wallets'
                ? 'bg-white text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700'
            }`}
            onClick={() => setActiveTab('wallets')}
          >
            <FaWallet /> User Wallets ({filteredUsers.length})
          </button>
        </div>

        {/* Search + Filter */}
        <div className="flex flex-col sm:flex-row gap-3 mb-4">
          <SearchBar
            value={searchTerm}
            onChange={setSearchTerm}
            placeholder="Search by name or email..."
            className="max-w-md"
          />
          {activeTab === 'withdrawals' && (
            <div className="flex items-center gap-2">
              <FaFilter className="text-gray-400" />
              <Select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                placeholder=""
                options={[
                  { value: 'all', label: 'All Status' },
                  { value: 'pending', label: 'Pending' },
                  { value: 'approved', label: 'Approved' },
                  { value: 'declined', label: 'Declined' },
                ]}
                className="sm:w-48"
              />
            </div>
          )}
        </div>

        {/* Withdrawals Tab */}
        {activeTab === 'withdrawals' && (
          <Table
            columns={withdrawalColumns}
            data={filteredWithdrawals}
            emptyMessage="No withdrawal requests"
          />
        )}

        {/* Wallets Tab */}
        {activeTab === 'wallets' && (
          <Table
            columns={walletColumns}
            data={filteredUsers}
            emptyMessage="No users found"
          />
        )}
      </div>
    </AdminLayout>
  );
};

export default WalletManagement;
