import React, { useState, useEffect } from 'react';
import { FaTags, FaTimes, FaPlus } from 'react-icons/fa';
import apiClient from '../config/api';
import AdminLayout from '../components/AdminLayout';
import {
  PageHeader,
  Card,
  Button,
  Input,
  FileInput,
  Checkbox,
  Badge,
  Alert,
} from '../components/ui';

const CategoryForm = () => {
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [subcategories, setSubcategories] = useState([]);
  const [selectedSubcategories, setSelectedSubcategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Auto-dismiss success message
  useEffect(() => {
    if (success) {
      const t = setTimeout(() => setSuccess(''), 5000);
      return () => clearTimeout(t);
    }
  }, [success]);

  // Fetch subcategories from the backend
  useEffect(() => {
    const fetchSubcategories = async () => {
      try {
        const response = await apiClient.get('/api/subcat');
        setSubcategories(response.data);
      } catch (error) {
        setError('Failed to fetch subcategories. Please try again.');
      }
    };

    fetchSubcategories();
  }, []);

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    const trimmedName = name.trim();
    if (!trimmedName) {
      setError('Category name is required.');
      setLoading(false);
      return;
    }

    const formData = new FormData();
    formData.append('name', trimmedName);
    formData.append('image', image);
    selectedSubcategories.forEach((id) => {
      formData.append('subcatIds[]', id);
    });

    try {
      const response = await apiClient.post(
        '/api/catitem/create',
        formData,
        {
          headers: { 'Content-Type': 'multipart/form-data' },
        }
      );
      setSuccess(response.data.message || 'Category created successfully!');
      setName('');
      setImage(null);
      setSelectedSubcategories([]);
    } catch (error) {
      setError('Failed to create category.');
    } finally {
      setLoading(false);
    }
  };

  // Add or remove subcategories
  const handleAddSubcategory = (id) => {
    if (!selectedSubcategories.includes(id)) {
      setSelectedSubcategories([...selectedSubcategories, id]);
    }
  };

  const handleRemoveSubcategory = (id) => {
    setSelectedSubcategories(selectedSubcategories.filter((subcatId) => subcatId !== id));
  };

  const toggleSubcategory = (id) => {
    if (selectedSubcategories.includes(id)) {
      handleRemoveSubcategory(id);
    } else {
      handleAddSubcategory(id);
    }
  };

  return (
    <AdminLayout>
      <div className="max-w-2xl mx-auto">
        <PageHeader
          icon={<FaTags />}
          title="Create Category"
          subtitle="Add a new product category and link it to subcategories"
        />

        {error && (
          <div className="mb-5">
            <Alert type="error" onClose={() => setError('')}>
              {error}
            </Alert>
          </div>
        )}

        {success && (
          <div className="mb-5">
            <Alert type="success" onClose={() => setSuccess('')}>
              {success}
            </Alert>
          </div>
        )}

        <Card padding="md">
          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Category Name */}
            <Input
              label="Category Name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter category name"
              required
            />

            {/* Category Image */}
            <FileInput
              label="Category Image"
              accept="image/*"
              onChange={(e) => setImage(e.target.files[0])}
              hint="Upload a representative image for this category"
            />

            {/* Subcategories */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Subcategories
              </label>

              {subcategories.length === 0 ? (
                <p className="text-sm text-gray-400">
                  No subcategories available.
                </p>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                  {subcategories.map((subcat) => {
                    const isSelected = selectedSubcategories.includes(subcat.id);
                    return (
                      <div
                        key={subcat.id}
                        className={`flex items-center px-3 py-2.5 border rounded-lg transition-all cursor-pointer ${
                          isSelected
                            ? 'bg-brand-50 border-brand-400'
                            : 'bg-white border-gray-200 hover:border-brand-300'
                        }`}
                        onClick={() => toggleSubcategory(subcat.id)}
                      >
                        <Checkbox
                          checked={isSelected}
                          onChange={() => toggleSubcategory(subcat.id)}
                          label={subcat.name}
                        />
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Selected Subcategories */}
              {selectedSubcategories.length > 0 && (
                <div className="mt-4">
                  <p className="text-xs font-semibold text-gray-500 mb-2">
                    Selected ({selectedSubcategories.length})
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {selectedSubcategories.map((id) => {
                      const subcat = subcategories.find((sub) => sub.id === id);
                      if (!subcat) return null;
                      return (
                        <Badge
                          key={id}
                          variant="blue"
                          size="md"
                          className="gap-1.5"
                        >
                          {subcat.name}
                          <button
                            type="button"
                            onClick={() => handleRemoveSubcategory(id)}
                            className="ml-1 text-brand-500 hover:text-red-600 transition-colors focus:outline-none"
                            aria-label={`Remove ${subcat.name}`}
                          >
                            <FaTimes className="text-[10px]" />
                          </button>
                        </Badge>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>

            {/* Submit Button */}
            <Button
              type="submit"
              variant="primary"
              size="lg"
              loading={loading}
              fullWidth
              icon={<FaPlus />}
            >
              {loading ? 'Creating...' : 'Create Category'}
            </Button>
          </form>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default CategoryForm;
